update public.sejong_pages set payload=jsonb_set(payload,'{completion}','{"path":"/about","title":"세종문화회관","summary":"공연을 만들고, 예술을 나누며, 시민의 문화생활을 넓히는 서울의 문화예술기관입니다.","image":{"src":"https://www.sejongpac.or.kr/cmmn/file/imageSrc.do?fileStreCours=8f2884203bc68b99a313565134d881f5&streFileNm=fe52049bee2203de20659d7fb97d8b27f91317191ed56d5d878495e687f379bf","alt":"세종문화회관 건물 전경"},"sections":[{"type":"prose","title":"시민과 함께하는 제작극장","paragraphs":["세종문화회관은 서울특별시가 설립한 문화예술기관입니다. 1978년 문을 열었으며 1999년 재단법인으로 출범했습니다. 공연·전시·교육을 운영하고 예술가에게는 창작과 발표의 공간을 제공합니다.","서울시예술단의 창작 활동과 여러 규모의 공연장을 바탕으로 작품을 제작합니다. 광화문의 공연장과 미술관, 북서울 꿈의숲아트센터를 통해 다양한 예술 경험을 시민과 나눕니다."]},{"type":"facts","title":"기관 기본 정보","items":[{"label":"기관명","value":"재단법인 세종문화회관"},{"label":"개관","value":"1978년 4월 14일"},{"label":"재단법인 출범","value":"1999년 7월 1일"},{"label":"주소","value":"서울특별시 종로구 세종대로 175 (세종로), 03172"},{"label":"대표 문의","value":"02-399-1000"}]},{"type":"cards","title":"기관을 알아보세요","items":[{"id":"about-introduction","title":"기관 소개","href":"/about/introduction","description":"설립 취지와 세종문화회관이 지향하는 역할"},{"id":"about-companies","title":"서울시예술단","href":"/about/companies","description":"국악·무용·뮤지컬·합창·오페라·연극·발레의 창작 활동"},{"id":"about-esg","title":"ESG경영","href":"/about/esg","description":"환경, 사회적 책임, 청렴·윤리경영의 전략과 공개자료"},{"id":"about-dfac","title":"꿈의숲아트센터","href":"/about/arts-center","description":"북서울 꿈의숲에서 만나는 공연장과 어린이 미술관"}]}],"sources":[{"label":"세종문화회관 개요","url":"https://www.sejongpac.or.kr/portal/main/contents.do?menuNo=200505"},{"label":"공식 연혁","url":"https://www.sejongpac.or.kr/portal/main/contents.do?menuNo=200506"}]}'::jsonb,true) where id='/about' and payload->'completion' is distinct from '{"path":"/about","title":"세종문화회관","summary":"공연을 만들고, 예술을 나누며, 시민의 문화생활을 넓히는 서울의 문화예술기관입니다.","image":{"src":"https://www.sejongpac.or.kr/cmmn/file/imageSrc.do?fileStreCours=8f2884203bc68b99a313565134d881f5&streFileNm=fe52049bee2203de20659d7fb97d8b27f91317191ed56d5d878495e687f379bf","alt":"세종문화회관 건물 전경"},"sections":[{"type":"prose","title":"시민과 함께하는 제작극장","paragraphs":["세종문화회관은 서울특별시가 설립한 문화예술기관입니다. 1978년 문을 열었으며 1999년 재단법인으로 출범했습니다. 공연·전시·교육을 운영하고 예술가에게는 창작과 발표의 공간을 제공합니다.","서울시예술단의 창작 활동과 여러 규모의 공연장을 바탕으로 작품을 제작합니다. 광화문의 공연장과 미술관, 북서울 꿈의숲아트센터를 통해 다양한 예술 경험을 시민과 나눕니다."]},{"type":"facts","title":"기관 기본 정보","items":[{"label":"기관명","value":"재단법인 세종문화회관"},{"label":"개관","value":"1978년 4월 14일"},{"label":"재단법인 출범","value":"1999년 7월 1일"},{"label":"주소","value":"서울특별시 종로구 세종대로 175 (세종로), 03172"},{"label":"대표 문의","value":"02-399-1000"}]},{"type":"cards","title":"기관을 알아보세요","items":[{"id":"about-introduction","title":"기관 소개","href":"/about/introduction","description":"설립 취지와 세종문화회관이 지향하는 역할"},{"id":"about-companies","title":"서울시예술단","href":"/about/companies","description":"국악·무용·뮤지컬·합창·오페라·연극·발레의 창작 활동"},{"id":"about-esg","title":"ESG경영","href":"/about/esg","description":"환경, 사회적 책임, 청렴·윤리경영의 전략과 공개자료"},{"id":"about-dfac","title":"꿈의숲아트센터","href":"/about/arts-center","description":"북서울 꿈의숲에서 만나는 공연장과 어린이 미술관"}]}],"sources":[{"label":"세종문화회관 개요","url":"https://www.sejongpac.or.kr/portal/main/contents.do?menuNo=200505"},{"label":"공식 연혁","url":"https://www.sejongpac.or.kr/portal/main/contents.do?menuNo=200506"}]}'::jsonb;
update public.sejong_pages set payload=jsonb_set(payload,'{completion}','{"path":"/about/arts-center","title":"꿈의숲아트센터","summary":"북서울 꿈의숲 안에서 공연·미술·산책을 함께 즐길 수 있는 문화공간입니다.","sections":[{"type":"prose","title":"자연 가까이에서 만나는 예술","paragraphs":["꿈의숲아트센터는 2009년 10월 17일 개관했습니다. 클래식 음악을 위한 콘서트홀, 무대와 객석의 거리가 가까운 퍼포먼스홀, 어린이를 위한 상상톡톡미술관과 전망대가 있습니다.","공연과 전시는 프로그램별 일정과 관람 조건이 다릅니다. 방문 날짜에 맞는 공연·전시와 이용 공지를 확인한 뒤 공원 산책 동선을 함께 계획해 보세요."]},{"type":"table","title":"공간별 특징","columns":["공간","이용 목적과 특징"],"rows":[["콘서트홀","어쿠스틱 음악에 맞춘 클래식 전문 공연장. 음향 반사판으로 높이와 각도를 조절합니다."],["퍼포먼스홀","무대와 객석 사이에 단이 없는 다목적 공연장. 다양한 장르의 공연을 가까이에서 만납니다."],["상상톡톡미술관","자연과 미술을 연결하는 어린이 미술관. 어린이의 눈높이에 맞춘 전시와 프로그램을 선보입니다."],["전망대","북한산·도봉산·수락산과 서울 도심을 조망하는 공간입니다."]]},{"type":"image","title":"공간 위치 안내","image":{"src":"https://www.sejongpac.or.kr/static/portal/img/content/img_space2_map.png","alt":"꿈의숲아트센터 조감도. 전망대, 아트센터, 퍼포먼스홀, 상상톡톡미술관, 드림갤러리의 위치"}},{"type":"facts","title":"방문 정보","items":[{"label":"주소","value":"서울특별시 강북구 월계로 173 (번동), 01228"},{"label":"문의","value":"02-399-1000"},{"label":"가까운 출입구","value":"북서울 꿈의숲 서문. 동문에서는 아트센터까지 도보 약 10분이 걸립니다."},{"label":"지하철 연계","value":"4호선 미아사거리역에서 강북05 또는 1124번 버스로 서문 이동"},{"label":"주차 확인","value":"아트센터 주차장은 방문자센터 주차장과 별도로 운영됩니다."}]},{"type":"links","title":"방문 전 확인","items":[{"label":"꿈의숲아트센터 공연·전시","href":"https://www.sejongpac.or.kr/dfac/main/main.do"},{"label":"대중교통 안내","href":"https://www.sejongpac.or.kr/dfac/main/contents.do?menuNo=1200055"},{"label":"주차 안내","href":"https://www.sejongpac.or.kr/dfac/main/contents.do?menuNo=1200054"},{"label":"꿈의숲 대관공고","href":"https://www.sejongpac.or.kr/dfac/reservation/reservation/list.do?menuNo=1200060"}]}],"sources":[{"label":"꿈의숲 공간 소개","url":"https://www.sejongpac.or.kr/dfac/main/contents.do?menuNo=1200059"},{"label":"콘서트홀","url":"https://www.sejongpac.or.kr/dfac/main/contents.do?menuNo=1200022"},{"label":"퍼포먼스홀","url":"https://www.sejongpac.or.kr/dfac/main/contents.do?menuNo=1200023"},{"label":"상상톡톡미술관","url":"https://www.sejongpac.or.kr/dfac/main/contents.do?menuNo=1200025"},{"label":"전망대","url":"https://www.sejongpac.or.kr/dfac/main/contents.do?menuNo=1200026"},{"label":"오시는 길","url":"https://www.sejongpac.or.kr/dfac/main/contents.do?menuNo=1200055"},{"label":"세종문화회관 연혁","url":"https://www.sejongpac.or.kr/portal/main/contents.do?menuNo=200506"}]}'::jsonb,true) where id='/about/arts-center' and payload->'completion' is distinct from '{"path":"/about/arts-center","title":"꿈의숲아트센터","summary":"북서울 꿈의숲 안에서 공연·미술·산책을 함께 즐길 수 있는 문화공간입니다.","sections":[{"type":"prose","title":"자연 가까이에서 만나는 예술","paragraphs":["꿈의숲아트센터는 2009년 10월 17일 개관했습니다. 클래식 음악을 위한 콘서트홀, 무대와 객석의 거리가 가까운 퍼포먼스홀, 어린이를 위한 상상톡톡미술관과 전망대가 있습니다.","공연과 전시는 프로그램별 일정과 관람 조건이 다릅니다. 방문 날짜에 맞는 공연·전시와 이용 공지를 확인한 뒤 공원 산책 동선을 함께 계획해 보세요."]},{"type":"table","title":"공간별 특징","columns":["공간","이용 목적과 특징"],"rows":[["콘서트홀","어쿠스틱 음악에 맞춘 클래식 전문 공연장. 음향 반사판으로 높이와 각도를 조절합니다."],["퍼포먼스홀","무대와 객석 사이에 단이 없는 다목적 공연장. 다양한 장르의 공연을 가까이에서 만납니다."],["상상톡톡미술관","자연과 미술을 연결하는 어린이 미술관. 어린이의 눈높이에 맞춘 전시와 프로그램을 선보입니다."],["전망대","북한산·도봉산·수락산과 서울 도심을 조망하는 공간입니다."]]},{"type":"image","title":"공간 위치 안내","image":{"src":"https://www.sejongpac.or.kr/static/portal/img/content/img_space2_map.png","alt":"꿈의숲아트센터 조감도. 전망대, 아트센터, 퍼포먼스홀, 상상톡톡미술관, 드림갤러리의 위치"}},{"type":"facts","title":"방문 정보","items":[{"label":"주소","value":"서울특별시 강북구 월계로 173 (번동), 01228"},{"label":"문의","value":"02-399-1000"},{"label":"가까운 출입구","value":"북서울 꿈의숲 서문. 동문에서는 아트센터까지 도보 약 10분이 걸립니다."},{"label":"지하철 연계","value":"4호선 미아사거리역에서 강북05 또는 1124번 버스로 서문 이동"},{"label":"주차 확인","value":"아트센터 주차장은 방문자센터 주차장과 별도로 운영됩니다."}]},{"type":"links","title":"방문 전 확인","items":[{"label":"꿈의숲아트센터 공연·전시","href":"https://www.sejongpac.or.kr/dfac/main/main.do"},{"label":"대중교통 안내","href":"https://www.sejongpac.or.kr/dfac/main/contents.do?menuNo=1200055"},{"label":"주차 안내","href":"https://www.sejongpac.or.kr/dfac/main/contents.do?menuNo=1200054"},{"label":"꿈의숲 대관공고","href":"https://www.sejongpac.or.kr/dfac/reservation/reservation/list.do?menuNo=1200060"}]}],"sources":[{"label":"꿈의숲 공간 소개","url":"https://www.sejongpac.or.kr/dfac/main/contents.do?menuNo=1200059"},{"label":"콘서트홀","url":"https://www.sejongpac.or.kr/dfac/main/contents.do?menuNo=1200022"},{"label":"퍼포먼스홀","url":"https://www.sejongpac.or.kr/dfac/main/contents.do?menuNo=1200023"},{"label":"상상톡톡미술관","url":"https://www.sejongpac.or.kr/dfac/main/contents.do?menuNo=1200025"},{"label":"전망대","url":"https://www.sejongpac.or.kr/dfac/main/contents.do?menuNo=1200026"},{"label":"오시는 길","url":"https://www.sejongpac.or.kr/dfac/main/contents.do?menuNo=1200055"},{"label":"세종문화회관 연혁","url":"https://www.sejongpac.or.kr/portal/main/contents.do?menuNo=200506"}]}'::jsonb;
update public.sejong_pages set payload=jsonb_set(payload,'{completion}','{"path":"/about/companies","title":"서울시예술단","summary":"서로 다른 예술 언어로 오늘의 무대를 만드는 서울시예술단을 소개합니다.","sections":[{"type":"prose","title":"작품을 만드는 예술단","paragraphs":["세종문화회관은 서울시예술단의 창작역량을 기반으로 공연을 제작합니다. 전통음악의 새로운 해석부터 한국 창작춤, 뮤지컬, 합창, 오페라, 연극과 컨템퍼러리 발레까지 장르별 작품을 선보입니다.","예술단별 페이지에서 창단 배경과 공연의 특징을 살펴보세요. 출연진과 관람 연령, 공연 장소는 작품마다 다르므로 관람할 공연의 상세 정보를 함께 확인하는 것이 좋습니다."]},{"type":"cards","title":"예술단 둘러보기","items":[{"id":"company-traditional","title":"서울시국악관현악단","href":"/about/companies/traditional","description":"1965년 창단. 전통음악의 계승과 창작 국악관현악","category":"국악"},{"id":"company-dance","title":"서울시무용단","href":"/about/companies/dance","description":"1974년 창단. 우리 문화에 뿌리를 둔 한국 창작춤","category":"무용"},{"id":"company-musical","title":"서울시뮤지컬단","href":"/about/companies/musical","description":"1961년 예그린악단에서 시작한 창작·가족뮤지컬","category":"뮤지컬"},{"id":"company-chorus","title":"서울시합창단","href":"/about/companies/chorus","description":"1978년 창단. 합창 명작과 국내 작곡가 위촉 작품","category":"합창"},{"id":"company-opera","title":"서울시오페라단","href":"/about/companies/opera","description":"1985년 창단. 극장과 야외에서 만나는 오페라 제작","category":"오페라"},{"id":"company-theater","title":"서울시극단","href":"/about/companies/theater","description":"1997년 창단. 고전·각색·창작·가족극을 아우르는 연극","category":"연극"},{"id":"company-ballet","title":"서울시발레단","href":"/about/companies/ballet","description":"2024년 출범. 작품별 프로덕션으로 만드는 컨템퍼러리 발레","category":"발레"}]},{"type":"links","title":"공연과 참여","items":[{"label":"공연 일정","href":"/programs"},{"label":"세종시즌","href":"/programs/season/sejong"},{"label":"예술단 채용 공고","href":"/news/notices/recruit"}]}],"sources":[{"label":"서울시국악관현악단","url":"https://www.sejongpac.or.kr/portal/sjartgroups/artMember/list.do?bcode=TRADITION&menuNo=200261"},{"label":"서울시무용단","url":"https://www.sejongpac.or.kr/portal/sjartgroups/artMember/list.do?bcode=DANCE&menuNo=200262"},{"label":"서울시뮤지컬단","url":"https://www.sejongpac.or.kr/portal/sjartgroups/artMember/list.do?bcode=MUSICAL&menuNo=200264"},{"label":"서울시합창단","url":"https://www.sejongpac.or.kr/portal/sjartgroups/artMember/list.do?bcode=CHORUS&menuNo=200263"},{"label":"서울시오페라단","url":"https://www.sejongpac.or.kr/portal/sjartgroups/artMember/list.do?bcode=OPERA&menuNo=200266"},{"label":"서울시극단","url":"https://www.sejongpac.or.kr/portal/sjartgroups/artMember/list.do?bcode=THEATER&menuNo=200265"},{"label":"서울시발레단","url":"https://www.sejongpac.or.kr/portal/sjartgroups/artMember/list.do?bcode=BALLET&menuNo=200580"}]}'::jsonb,true) where id='/about/companies' and payload->'completion' is distinct from '{"path":"/about/companies","title":"서울시예술단","summary":"서로 다른 예술 언어로 오늘의 무대를 만드는 서울시예술단을 소개합니다.","sections":[{"type":"prose","title":"작품을 만드는 예술단","paragraphs":["세종문화회관은 서울시예술단의 창작역량을 기반으로 공연을 제작합니다. 전통음악의 새로운 해석부터 한국 창작춤, 뮤지컬, 합창, 오페라, 연극과 컨템퍼러리 발레까지 장르별 작품을 선보입니다.","예술단별 페이지에서 창단 배경과 공연의 특징을 살펴보세요. 출연진과 관람 연령, 공연 장소는 작품마다 다르므로 관람할 공연의 상세 정보를 함께 확인하는 것이 좋습니다."]},{"type":"cards","title":"예술단 둘러보기","items":[{"id":"company-traditional","title":"서울시국악관현악단","href":"/about/companies/traditional","description":"1965년 창단. 전통음악의 계승과 창작 국악관현악","category":"국악"},{"id":"company-dance","title":"서울시무용단","href":"/about/companies/dance","description":"1974년 창단. 우리 문화에 뿌리를 둔 한국 창작춤","category":"무용"},{"id":"company-musical","title":"서울시뮤지컬단","href":"/about/companies/musical","description":"1961년 예그린악단에서 시작한 창작·가족뮤지컬","category":"뮤지컬"},{"id":"company-chorus","title":"서울시합창단","href":"/about/companies/chorus","description":"1978년 창단. 합창 명작과 국내 작곡가 위촉 작품","category":"합창"},{"id":"company-opera","title":"서울시오페라단","href":"/about/companies/opera","description":"1985년 창단. 극장과 야외에서 만나는 오페라 제작","category":"오페라"},{"id":"company-theater","title":"서울시극단","href":"/about/companies/theater","description":"1997년 창단. 고전·각색·창작·가족극을 아우르는 연극","category":"연극"},{"id":"company-ballet","title":"서울시발레단","href":"/about/companies/ballet","description":"2024년 출범. 작품별 프로덕션으로 만드는 컨템퍼러리 발레","category":"발레"}]},{"type":"links","title":"공연과 참여","items":