update public.sejong_pages set payload=jsonb_set(payload,'{completion}','{"path":"/about/companies/ballet","title":"서울시발레단","summary":"동시대의 안무와 작품을 중심으로 새로운 발레 무대를 만듭니다.","sections":[{"type":"prose","title":"작품마다 새롭게 구성하는 발레","paragraphs":["2024년 출범한 서울시발레단은 공공 컨템퍼러리 발레단입니다. 안무가와 무용수, 작품을 중심에 두고 공연별 맞춤형 프로덕션으로 운영합니다.","국내외 창작진과 무용수가 동시대의 성찰을 담은 작품을 선보입니다. 시즌 무용수와 객원 무용수, 안무가, 예술스태프의 구성은 공식 예술단 페이지에서 확인할 수 있습니다."]},{"type":"facts","title":"활동 정보","items":[{"label":"출범","value":"2024년"},{"label":"중심 장르","value":"컨템퍼러리 발레"},{"label":"운영 방식","value":"공연별 맞춤형 프로덕션"},{"label":"공식 인스타그램","value":"@seoulmetropolitanballet"}]},{"type":"table","title":"2026년 공식 편성","columns":["작품","일정","장소"],"rows":[["더블 빌 Bliss & Jakie","3월 14일–22일","세종M씨어터"],["In the Bamboo Forest","5월 15일–17일","세종M씨어터"],["더블 빌 죽음과 소녀","8월 14일–16일","국립극장 해오름극장"],["트리플 빌 올 포 한스 판 마넨","11월 19일–22일","세종M씨어터"]],"note":"예술단 공식 소개에 게시된 편성입니다. 예매 가능 여부와 출연진은 개별 공연에서 확인해 주세요."},{"type":"links","title":"무용수와 창작진","items":[{"label":"공식 예술단·시즌 무용수 소개","href":"https://www.sejongpac.or.kr/portal/sjartgroups/artMember/list.do?bcode=BALLET&menuNo=200580"},{"label":"서울시발레단 소개북","href":"https://www.sejongpac.or.kr/e-book/ecatalog5.jsp?Dir=100&catimage="},{"label":"공연 일정 살펴보기","href":"/programs"}]}],"sources":[{"label":"서울시발레단 소개·2026 공연 편성","url":"https://www.sejongpac.or.kr/portal/sjartgroups/artMember/list.do?bcode=BALLET&menuNo=200580"}],"relatedPrograms":{"title":"서울시발레단 공연","query":"서울시발레단"}}'::jsonb,true) where id='/about/companies/ballet' and payload->'completion' is distinct from '{"path":"/about/companies/ballet","title":"서울시발레단","summary":"동시대의 안무와 작품을 중심으로 새로운 발레 무대를 만듭니다.","sections":[{"type":"prose","title":"작품마다 새롭게 구성하는 발레","paragraphs":["2024년 출범한 서울시발레단은 공공 컨템퍼러리 발레단입니다. 안무가와 무용수, 작품을 중심에 두고 공연별 맞춤형 프로덕션으로 운영합니다.","국내외 창작진과 무용수가 동시대의 성찰을 담은 작품을 선보입니다. 시즌 무용수와 객원 무용수, 안무가, 예술스태프의 구성은 공식 예술단 페이지에서 확인할 수 있습니다."]},{"type":"facts","title":"활동 정보","items":[{"label":"출범","value":"2024년"},{"label":"중심 장르","value":"