update public.sejong_pages set payload=jsonb_set(payload,'{completion}','{"path":"/about/companies/chorus","title":"서울시합창단","summary":"목소리가 어우러지는 합창의 깊이와 새로운 무대 형식을 선보입니다.","sections":[{"type":"prose","title":"합창 명작에서 동시대 작품까지","paragraphs":["서울시합창단은 1978년 세종문화회관 개관과 함께 창단했습니다. 합창 음악의 발전과 시민의 정서함양을 목적으로 활동합니다.","음악사적 걸작과 국내외 작곡가의 다양한 합창곡, 국내 작곡가 위촉 작품을 함께 다룹니다. 오케스트라와 함께하는 교향악적 합창 대작뿐 아니라 다른 장르를 접목한 합창 콘서트도 선보입니다."]},{"type":"facts","title":"예술단 정보","items":[{"label":"창단","value":"1978년"},{"label":"단장","value":"이영만"},{"label":"구성","value":"소프라노·알토·테너·베이스와 반주"},{"label":"문의","value":"02-399-1726"},{"label":"공식 인스타그램","value":"@sejongcenter_smchorus"}]},{"type":"prose","title":"단원과 음악을 만나는 방법","paragraphs":["공식 소개에서 성부별 단원과 반주자 프로필을 볼 수 있습니다. 서울시소년소녀합창단은 같은 공식 메뉴 안의 별도 탭으로 소개됩니다.","곡목에 따라 합창단 단독 연주 또는 기악 연주자와의 협연으로 편성됩니다. 공연 상세에서 작곡가·곡목·지휘·협연진을 살펴보면 무대의 구성을 미리 이해할 수 있습니다."]},{"type":"links","title":"공식 자료","items":[{"label":"단원 소개와 합창단 공연","href":"https://www.sejongpac.or.kr/portal/sjartgroups/artMember/list.do?bcode=CHORUS&menuNo=200263"},{"label":"서울시소년소녀합창단 소개","href":"https://www.sejongpac.or.kr/portal/sjartgroups/artMember/list.do?bcode=JUNIOR&menuNo=200263"}]}],"sources":[{"label":"서울시합창단 소개·단장·성부별 단원","url":"https://www.sejongpac.or.kr/portal/sjartgroups/artMember/list.do?bcode=CHORUS&menuNo=200263"}],"relatedPrograms":{"title":"합창 공연","category":"합창","query":"서울시합창단"}}'::jsonb,true) where id='/about/companies/chorus' and payload->'completion' is distinct from '{"path":"/about/companies/chorus","title":"서울시합창단","summary":"목소리가 어우러지는 합창의 깊이와 새로운 무대 형식을 선보입니다.","sections":[{"type":"prose","title":"합창 명작에서 동시대 작품까지","paragraphs":["서울시합창단은 1978년 세종문화회관 개관과 함께 창단했습니다. 합창 음악의 발전과 시민의 정서함양을 목적으로 활동합니다.","음악사적 걸작과 국내외 작곡가의 다양한 합창곡, 국내 작곡가 위촉 작품을 함께 다룹니다. 오케스트라와 함께하는 교향악적 합창 대작뿐 아니라 다른 장르를 접목한 합창 콘서트도 선보입니다."]},{"type":"facts","title":"예술단 정보","items":[{"label":"창단","value":"1978년"},{"label":"단장","value":"이영만"},{"label":"구성","value":"소프라노·알토·테너·베이스와 반주"},{"label":"문의","