update public.sejong_pages set payload=jsonb_set(payload,'{completion}','{"path":"/about/companies/dance","title":"서울시무용단","summary":"우리 문화에 뿌리를 두고 한국 창작춤의 표현을 넓혀갑니다.","sections":[{"type":"prose","title":"한국 창작춤의 무대","paragraphs":["1974년 창단한 서울시무용단은 한국의 문화와 춤을 바탕으로 창작 활동을 이어왔습니다. 예술단체의 사회적 역할을 고민하며 국내외 무대에서 작품을 선보입니다.","1984년 LA 올림픽 폐막식과 1990년 북경 아시안게임 예술축전 등 국제행사에 참여했고, 해외 순회공연과 문화예술축전을 통해 한국 춤을 소개해 왔습니다."]},{"type":"facts","title":"예술단 정보","items":[{"label":"창단","value":"1974년"},{"label":"단장","value":"윤혜정"},{"label":"문의","value":"02-399-1765"},{"label":"공식 인스타그램","value":"@seoulmetropolitandancetheatre"}]},{"type":"table","title":"2026년 공식 편성","columns":["작품","일정","장소"],"rows":[["스피드","5월 1일–3일","세종M씨어터"],["무감서기","9월 10일–13일","세종대극장"]],"note":"공식 예술단 소개에 게시된 편성입니다. 작품별 안무와 출연진은 공연 상세를 확인해 주세요."},{"type":"links","title":"창작진과 공연","items":[{"label":"단장·단원 프로필","href":"https://www.sejongpac.or.kr/portal/sjartgroups/artMember/list.do?bcode=DANCE&menuNo=200262"},{"label":"공연 일정","href":"/programs"}]}],"sources":[{"label":"서울시무용단 소개·2026 공연 편성","url":"https://www.sejongpac.or.kr/portal/sjartgroups/artMember/list.do?bcode=DANCE&menuNo=200262"}],"relatedPrograms":{"title":"서울시무용단 공연","category":"무용","query":"서울시무용단"}}'::jsonb,true) where id='/about/companies/dance' and payload->'completion' is distinct from '{"path":"/about/companies/dance","title":"서울시무용단","summary":"우리 문화에 뿌리를 두고 한국 창작춤의 표현을 넓혀갑니다.","sections":[{"type":"prose","title":"한국 창작춤의 무대","paragraphs":["1974년 창단한 서울시무용단은 한국의 문화와 춤을 바탕으로 창작 활동을 이어왔습니다. 예술단체의 사회적 역할을 고민하며 국내외 무대에서 작품을 선보입니다.","1984년 LA 올림픽 폐막식과 1990년 북경 아시안게임 예술축전 등 국제행사에 참여했고, 해외 순회공연과 문화예술축전을 통해 한국 춤을 소개해 왔습니다."]},{"type":"facts","title":"예술단 정보","items":[{"label":"창단","value":"1974년"},{"label":"단장","value":"윤혜정"},{"label":"문의","value":"02-399-1765"},{"label":"공식 인스타그램","value":"@seoulmetropolitandancetheatre"}]},{"type":"table","title":"2026년 공식 편성","columns":["작품","일정","장소"],"rows":[["스피드","5월 1일–3일","세종M씨어터"],["무감서기","9월 10일–13일","세종대극장"]],"