update public.sejong_pages set payload=jsonb_set(payload,'{completion}','{"path":"/about/companies/musical","title":"서울시뮤지컬단","summary":"창작뮤지컬과 온 가족이 함께 보는 작품으로 관객을 만납니다.","sections":[{"type":"prose","title":"예그린악단에서 이어온 뮤지컬","paragraphs":["서울시뮤지컬단은 1961년 창단한 예그린악단을 모태로 합니다. 창작극을 개발하며 한국 창작뮤지컬의 활성화에 기여하고, 가족뮤지컬을 통해 공연 관객의 폭을 넓혀왔습니다.","서울시가무단, 국립가무단, 서울시립가무단을 거쳐 1999년 세종문화회관의 재단법인 출범과 함께 현재의 명칭을 사용하게 되었습니다. 한국적 소재의 창작 작품과 해외 뮤지컬을 함께 소개합니다."]},{"type":"facts","title":"예술단 정보","items":[{"label":"출발","value":"1961년 예그린악단"},{"label":"현재 명칭","value":"1999년부터 서울시뮤지컬단"},{"label":"단장","value":"김덕희"},{"label":"문의","value":"02-399-1732"},{"label":"공식 인스타그램","value":"@smmt.musical"}]},{"type":"table","title":"2026년 공식 편성","columns":["작품","일정","장소"],"rows":[["더 트라이브","6월 9일–27일","세종M씨어터"],["크리스마스 캐럴","12월 2일–27일","세종M씨어터"]],"note":"관람 연령·할인·캐스팅·예매 상태는 각 공연 상세에서 확인해 주세요."},{"type":"links","title":"예술단을 더 알아보세요","items":[{"label":"서울시뮤지컬단 단원·작품 소개","href":"https://www.sejongpac.or.kr/portal/sjartgroups/artMember/list.do?bcode=MUSICAL&menuNo=200264"},{"label":"공연 예매 안내","href":"/programs/booking-guide"}]}],"sources":[{"label":"서울시뮤지컬단 소개·2026 공연 편성","url":"https://www.sejongpac.or.kr/portal/sjartgroups/artMember/list.do?bcode=MUSICAL&menuNo=200264"}],"relatedPrograms":{"title":"서울시뮤지컬단 공연","category":"뮤지컬","query":"서울시뮤지컬단"}}'::jsonb,true) where id='/about/companies/musical' and payload->'completion' is distinct from '{"path":"/about/companies/musical","title":"서울시뮤지컬단","summary":"창작뮤지컬과 온 가족이 함께 보는 작품으로 관객을 만납니다.","sections":[{"type":"prose","title":"예그린악단에서 이어온 뮤지컬","paragraphs":["서울시뮤지컬단은 1961년 창단한 예그린악단을 모태로 합니다. 창작극을 개발하며 한국 창작뮤지컬의 활성화에 기여하고, 가족뮤지컬을 통해 공연 관객의 폭을 넓혀왔습니다.","서울시가무단, 국립가무단, 서울시립가무단을 거쳐 1999년 세종문화회관의 재단법인 출범과 함께 현재의 명칭을 사용하게 되었습니다. 한국적 소재의 창작 작품과 해외 뮤지컬을 함께 소개합니다."]},{"type":"facts","title":"예술단 정보","items":[{"label":"출발","value":"1961년 예그린악단"},{"label":"현재 명칭","value":"1999년부터 서울시뮤지컬단"},{"label":"단장","value":"김덕희"},{"label":"문의","value":"02-399-1732"},{"label":"공식