update public.sejong_pages set payload=jsonb_set(payload,'{completion}','{"path":"/about/companies/opera","title":"서울시오페라단","summary":"극장과 야외 무대에서 시민에게 가까이 다가가는 오페라를 제작합니다.","sections":[{"type":"prose","title":"다양한 관객을 위한 오페라 제작","paragraphs":["1985년 창단한 서울시오페라단은 오페라 애호가와 입문자를 함께 만나는 공연을 제작합니다. 작품의 예술성과 관객의 접근성을 함께 고민하며 오페라 관객층을 넓혀왔습니다.","극장 공연과 야외오페라를 통해 시민의 문화향유 기회를 확대합니다. 같은 오페라도 공연별로 연출과 성악가, 오케스트라, 장소가 달라지므로 개별 작품의 제작 정보를 살펴보세요."]},{"type":"facts","title":"예술단 정보","items":[{"label":"창단","value":"1985년"},{"label":"중심 활동","value":"오페라 제작·야외오페라·갈라 공연"},{"label":"문의","value":"02-399-1783"},{"label":"공식 인스타그램","value":"@seoul_metropolitan_opera"}]},{"type":"table","title":"2026년 공식 편성","columns":["작품","일정","장소"],"rows":[["나부코","4월 9일–12일","세종대극장"],["제4회 야외오페라 라 트라비아타","5월 22일–23일","여의도 한강공원 물빛무대"],["라보엠","11월 5일–8일","세종대극장"],["오페라 갈라","12월 12일","세종대극장"]],"note":"예술단 공식 편성입니다. 야외 공연의 입장 방식과 운영 공지는 해당 공연에서 확인해 주세요."},{"type":"links","title":"작품과 예술단 정보","items":[{"label":"서울시오페라단 공식 소개","href":"https://www.sejongpac.or.kr/portal/sjartgroups/artMember/list.do?bcode=OPERA&menuNo=200266"},{"label":"공연 일정","href":"/programs"}]}],"sources":[{"label":"서울시오페라단 소개·2026 공연 편성","url":"https://www.sejongpac.or.kr/portal/sjartgroups/artMember/list.do?bcode=OPERA&menuNo=200266"}],"relatedPrograms":{"title":"서울시오페라단 공연","category":"오페라","query":"서울시오페라단"}}'::jsonb,true) where id='/about/companies/opera' and payload->'completion' is distinct from '{"path":"/about/companies/opera","title":"서울시오페라단","summary":"극장과 야외 무대에서 시민에게 가까이 다가가는 오페라를 제작합니다.","sections":[{"type":"prose","title":"다양한 관객을 위한 오페라 제작","paragraphs":["1985년 창단한 서울시오페라단은 오페라 애호가와 입문자를 함께 만나는 공연을 제작합니다. 작품의 예술성과 관객의 접근성을 함께 고민하며 오페라 관객층을 넓혀왔습니다.","극장 공연과 야외오페라를 통해 시민의 문화향유 기회를 확대합니다. 같은 오페라도 공연별로 연출과 성악가, 오케스트라, 장소가 달라지므로 개별 작품의 제작 정보를 살펴보세요."]},{"type":"facts","title":"예술단 정보","items":[{"label":"창단","value":"1985년"},{"label":"중심 활동","value":"오페라 제작·야외오페라·갈라 공연"},{"label":"문의","value":"02-399-1783"},{"label":"공식 인스타그램",