update public.sejong_pages set payload=jsonb_set(payload,'{completion}','{"path":"/about/companies/theater","title":"서울시극단","summary":"고전과 창작극을 통해 시민과 동시대의 질문을 나누는 연극을 만듭니다.","sections":[{"type":"prose","title":"시민과 함께 생각하는 연극","paragraphs":["서울시극단은 시민의 문화수요를 충족하고 수준 높은 연극을 제공하기 위해 1997년 창단했습니다. 연극의 공공성과 미학, 보편적인 주제를 통한 대중적 가치를 지향합니다.","고전극과 장르를 넘나드는 각색극, 동시대를 다른 시선으로 바라보는 창작극, 가족극을 선보여 왔습니다. 시민연극교실과 신진예술가 발굴을 통해 관객의 참여와 창작환경의 확대에도 힘씁니다."]},{"type":"facts","title":"예술단 정보","items":[{"label":"창단","value":"1997년"},{"label":"단장","value":"이준우"},{"label":"문의","value":"02-399-1133"},{"label":"공식 인스타그램","value":"@smt_theatre"}]},{"type":"table","title":"2026년 공식 편성","columns":["작품","일정","장소"],"rows":[["빅 마더","3월 30일–4월 25일","세종M씨어터"],["에너미","10월 26일–11월 14일","세종M씨어터"]],"note":"회차별 공연 시간, 관람 연령과 캐스팅은 공연 상세를 기준으로 확인해 주세요."},{"type":"links","title":"연극과 참여 소식","items":[{"label":"서울시극단 단원·작품 소개","href":"https://www.sejongpac.or.kr/portal/sjartgroups/artMember/list.do?bcode=THEATER&menuNo=200265"},{"label":"시민 참여·모집 소식","href":"/news/notices"}]}],"sources":[{"label":"서울시극단 소개·2026 공연 편성","url":"https://www.sejongpac.or.kr/portal/sjartgroups/artMember/list.do?bcode=THEATER&menuNo=200265"}],"relatedPrograms":{"title":"서울시극단 공연","category":"연극","query":"서울시극단"}}'::jsonb,true) where id='/about/companies/theater' and payload->'completion' is distinct from '{"path":"/about/companies/theater","title":"서울시극단","summary":"고전과 창작극을 통해 시민과 동시대의 질문을 나누는 연극을 만듭니다.","sections":[{"type":"prose","title":"시민과 함께 생각하는 연극","paragraphs":["서울시극단은 시민의 문화수요를 충족하고 수준 높은 연극을 제공하기 위해 1997년 창단했습니다. 연극의 공공성과 미학, 보편적인 주제를 통한 대중적 가치를 지향합니다.","고전극과 장르를 넘나드는 각색극, 동시대를 다른 시선으로 바라보는 창작극, 가족극을 선보여 왔습니다. 시민연극교실과 신진예술가 발굴을 통해 관객의 참여와 창작환경의 확대에도 힘씁니다."]},{"type":"facts","title":"예술단 정보","items":[{"label":"창단","value":"1997년"},{"label":"단장","value":"이준우"},{"label":"문의","value":"02-399-1133"},{"label":"공식 인스타그램","value":"@smt_theatre"}]},{"type":"table","title":"2026년 공식 편성","columns":["작품","일정","장소"],"rows":[["빅 마더",