update public.sejong_pages set payload=jsonb_set(payload,'{completion}','{"path":"/about/companies/traditional","title":"서울시국악관현악단","summary":"전통음악을 계승하고 새로운 창작곡으로 국악관현악의 가능성을 넓힙니다.","sections":[{"type":"prose","title":"전통과 현재를 잇는 관현악","paragraphs":["서울시국악관현악단은 국악관현악의 현대화·대중화·세계화를 목표로 1965년 창단한 대한민국 최초의 국악관현악단입니다. 전통음악을 창조적으로 계승하고 새로운 국악관현악 작품을 선보여 왔습니다.","관현악곡과 협주곡, 실내악을 연주하고 다른 장르의 예술가들과 협업합니다. 전통 악기의 소리를 바탕으로 오늘의 감각을 담은 창작곡을 만날 수 있습니다."]},{"type":"facts","title":"예술단 정보","items":[{"label":"창단","value":"1965년"},{"label":"단장","value":"이승훤"},{"label":"문의","value":"02-399-1761"},{"label":"공식 인스타그램","value":"@sejongcenter_smto"}]},{"type":"table","title":"2026년 공식 편성","columns":["작품","일정","장소"],"rows":[["믹스드 오케스트라 26","4월 16일","세종대극장"],["Re-프로젝트 형식의 재발견","5월 29일","세종M씨어터"],["실내악 시리즈 일노래","7월 3일","세종체임버홀"],["창작 국악 시리즈 신풍류전","9월 4일","세종M씨어터"],["송년 음악회","12월 10일","세종대극장"]],"note":"예매 여부와 곡목·지휘·협연자는 개별 공연 상세에서 확인해 주세요."},{"type":"links","title":"공식 자료","items":[{"label":"예술단원·수석객원지휘자·상주작곡가 소개","href":"https://www.sejongpac.or.kr/portal/sjartgroups/artMember/list.do?bcode=TRADITION&menuNo=200261"},{"label":"공연 일정","href":"/programs"}]}],"sources":[{"label":"서울시국악관현악단 소개·2026 공연 편성","url":"https://www.sejongpac.or.kr/portal/sjartgroups/artMember/list.do?bcode=TRADITION&menuNo=200261"}],"relatedPrograms":{"title":"국악관현악 공연","category":"국악","query":"서울시국악관현악단"}}'::jsonb,true) where id='/about/companies/traditional' and payload->'completion' is distinct from '{"path":"/about/companies/traditional","title":"서울시국악관현악단","summary":"전통음악을 계승하고 새로운 창작곡으로 국악관현악의 가능성을 넓힙니다.","sections":[{"type":"prose","title":"전통과 현재를 잇는 관현악","paragraphs":["서울시국악관현악단은 국악관현악의 현대화·대중화·세계화를 목표로 1965년 창단한 대한민국 최초의 국악관현악단입니다. 전통음악을 창조적으로 계승하고 새로운 국악관현악 작품을 선보여 왔습니다.","관현악곡과 협주곡, 실내악을 연주하고 다른 장르의 예술가들과 협업합니다. 전통 악기의 소리를 바탕으로 오늘의 감각을 담은 창작곡을 만날 수 있습니다."]},{"type":"facts","title":"예술단 정보","items":[{"label":"창단","value":"1965년"},{"label":"단장","value":"이승훤"},{"label":"문의","value":"02-399-1761"},{"label":"공식 인스