update public.sejong_pages set payload=jsonb_set(payload,'{completion}','{"path":"/about/disclosure","title":"정보공개","summary":"사업·예산·결산·회의록 등 기관 운영 자료와 정보공개청구 경로를 안내합니다.","sections":[{"type":"prose","title":"공개자료 찾기","paragraphs":["세종문화회관은 사전공표목록을 통해 공개항목과 공표주기, 시기, 담당 부서를 안내합니다. 이미 공개된 정보는 항목별 자료실에서 바로 확인할 수 있습니다.","연간 계획은 주요업무계획과 예산에서, 집행 결과는 결산보고서와 운영보고서에서 살펴보세요. 필요한 기록을 공개자료에서 찾기 어려운 경우 정보공개포털의 청구 절차를 이용할 수 있습니다."]},{"type":"table","title":"주요 사전공표 항목","columns":["항목","공표주기·시기","담당 부서"],"rows":[["사업설명서·예산","연 1회 · 1월","기획조정팀"],["주요업무계획","연 1회 · 3월","기획조정팀"],["경영실적 평가결과·ESG 경영 보고서","연 1회 · 12월","기획조정팀"],["이사회 회의록","회의 개최 시","기획조정팀"],["업무추진비·정보목록","월별","재무행정팀"],["조직도","조직 개편 시","기획조정팀"]],"note":"공식 사전공표목록의 안내 기준입니다. 자료 게시 여부와 상세 항목은 원문 자료실에서 확인해 주세요."},{"type":"cards","title":"목적에 맞게 확인하세요","items":[{"id":"disclosure-management","title":"경영공시","href":"/about/disclosure/management","description":"예산·결산·경영평가와 공개 재무자료"},{"id":"disclosure-ethics","title":"윤리경영","href":"/about/disclosure/ethics","description":"윤리헌장, 임직원행동강령과 부조리 신고 안내"},{"id":"disclosure-request","title":"정보공개청구","href":"/about/disclosure/request","description":"청구 전 확인할 자료와 공식 접수 경로"}]},{"type":"links","title":"공식 자료실","items":[{"label":"사전공표목록 전체","href":"https://www.sejongpac.or.kr/portal/main/contents.do?menuNo=200528"},{"label":"이사회 회의록","href":"https://www.sejongpac.or.kr/portal/bbs/B0000105/list.do?menuNo=200606"},{"label":"기부금 모금·활용실적","href":"https://www.sejongpac.or.kr/portal/bbs/B0000118/list.do?menuNo=200617"}]}],"sources":[{"label":"정보공개 사전공표목록","url":"https://www.sejongpac.or.kr/portal/main/contents.do?menuNo=200528"}]}'::jsonb,true) where id='/about/disclosure' and payload->'completion' is distinct from '{"path":"/about/disclosure","title":"정보공개","summary":"사업·예산·결산·회의록 등 기관 운영 자료와 정보공개청구 경로를 안내합니다.","sections":[{"type":"prose","title":"공개자료 찾기","paragraphs":["세종문화회관은 사전공표목록을 통해 공개항목과 공표주기, 시기, 담당 부서를 안내합니다. 이미 공개된 정보는 항목별 자료실에서 바로 확인할 수 있습니다.","연간 계획은 주요업무계획과 예산에서, 집행 결과는 결산보고서와 운영보고서에서