update public.sejong_pages set payload=jsonb_set(payload,'{completion}','{"path":"/about/disclosure/ethics","title":"윤리경영","summary":"공정한 조직문화와 투명한 운영을 위한 윤리기준·예방활동·신고 경로입니다.","sections":[{"type":"prose","title":"시민의 신뢰를 위한 운영 원칙","paragraphs":["세종문화회관의 윤리헌장은 합법적이고 투명한 경영, 문화예술의 창작·보급, 시민공연과 예술교육, 해외 문화교류를 통한 사회적 책임을 제시합니다.","윤리경영 추진전략은 부패 사전예방, 자문·진단 감사, 공직기강 확립을 중심으로 운영됩니다. 윤리교육과 제도개선, 정기·수시·일상감사, 시설 안전점검 등을 추진과제로 안내합니다."]},{"type":"table","title":"규범과 확인할 내용","columns":["공식 자료","내용"],"rows":[["윤리헌장","공공 문화예술기관으로서 지켜야 할 가치와 실천 방향"],["임직원행동강령","직무 수행 과정에서 준수할 행동기준"],["청렴계약제","공정한 계약을 위한 청렴 기준"],["신고자 보상내규","비윤리행위 신고자 보호와 보상에 관한 기준"]]},{"type":"facts","title":"부조리 신고 안내","items":[{"label":"주요 대상","value":"입찰 피해, 예산낭비, 계약 관계의 부당행위, 임직원 비리"},{"label":"작성 내용","value":"신고자·위반자 정보, 언제·어디서·어떤 일이 있었는지에 대한 구체적인 내용과 관련 자료"},{"label":"감사관 전용 전화","value":"02-399-1170"},{"label":"팩스","value":"02-399-1175"}]},{"type":"links","title":"규범 원문과 공식 신고","items":[{"label":"윤리헌장","href":"https://www.sejongpac.or.kr/portal/main/contents.do?menuNo=200551"},{"label":"임직원행동강령","href":"https://www.sejongpac.or.kr/portal/main/contents.do?menuNo=200552"},{"label":"청렴계약제","href":"https://www.sejongpac.or.kr/portal/main/contents.do?menuNo=200553"},{"label":"신고자 보상내규","href":"https://www.sejongpac.or.kr/portal/main/contents.do?menuNo=200554"},{"label":"부조리 신고센터","href":"https://www.sejongpac.or.kr/portal/main/contents.do?menuNo=200517"},{"label":"윤리경영 추진전략","href":"https://www.sejongpac.or.kr/portal/main/contents.do?menuNo=200521"}]}],"sources":[{"label":"윤리헌장","url":"https://www.sejongpac.or.kr/portal/main/contents.do?menuNo=200551"},{"label":"윤리경영 추진전략","url":"https://www.sejongpac.or.kr/portal/main/contents.do?menuNo=200521"},{"label":"부조리 신고센터","url":"https://www.sejongpac.or.kr/portal/main/contents.do?menuNo=200517"}]}'::jsonb,true) where id='/about/disclosure/ethics' and payload->'completion' is distinct from '{"path":"/about/disclosure/ethics","title":"윤리경영","summary":"공정한 조직문화와 투명한 운영을 위한 윤리기준·예방활동·신고 경로입니다.","sections":[{"type":"prose","title":"시민의 신뢰를 위한 운영 원칙","paragraphs":["세종문화회관의 윤리헌장은 합법적이고 투명한 경영, 문화예술의 창작·보급, 시민공연과 예술교육, 해외 문화교류를 통한 사회적 책임을 제시합니다.","윤리경영 추진전략은 부패 사전예방, 자문·진단 감사, 공직기강 확립을 중심으로 운영됩니다. 윤리교육과 제도개선, 정기·수시·일상감사, 시설 안전점검 등을 추진과제로 안내합니다."]},{"type":"table","title":"규범과 확인할 내용","columns":["공식 자료","내용"],"rows":[["윤리헌장","공공 문화예술기관으로서 지켜야 할 가치와 실천 방향"],["임직원행동강령","직무 수행 과정에서 준수할 행동기준"],["청렴계약제","공정한 계약을 위한 청렴 기준"],["신고자 보상내규","비윤리행위 신고자 보호와 보상에 관한 기준"]]},{"type":"facts","title":"부조리 신고 안내","items":[{"label":"주요 대상","value":"입찰 피해, 예산낭비, 계약 관계의 부당행위, 임직원 비리"},{"label":"작성 내용","value":"신고자·위반자 정보, 언제·어디서·어떤 일이 있었는지에 대한 구체적인 내용과 관련 자료"},{"label":"감사관 전용 전화","value":"02-399-1170"},{"label":"팩스","value":"02-399-1175"}]},{"type":"links","title":"규범 원문과 공식 신고","items":[{"label":"윤리헌장","href":"https://www.sejongpac.or.kr/portal/main/contents.do?menuNo=200551"},{"label":"임직원행동강령","href":"https://www.sejongpac.or.kr/portal/main/contents.do?menuNo=200552"},{"label":"청렴계약제","href":"https://www.sejongpac.or.kr/portal/main/contents.do?menuNo=200553"},{"label":"신고자 보상내규","href":"https://www.sejongpac.or.kr/portal/main/contents.do?menuNo=200554"},{"label":"부조리 신고센터","href":"https://www.sejongpac.or.kr/portal/main/contents.do?menuNo=200517"},{"label":"윤리경영 추진전략","href":"https://www.sejongpac.or.kr/portal/main/contents.do?menuNo=200521"}]}],"sources":[{"label":"윤리헌장","url":"https://www.sejongpac.or.kr/portal/main/contents.do?menuNo=200551"},{"label":"윤리경영 추진전략","url":"https://www.sejongpac.or.kr/portal/main/contents.do?menuNo=200521"},{"label":"부조리 신고센터","url":"https://www.sejongpac.or.kr/portal/main/contents.do?menuNo=200517"}]}'::jsonb;
update public.sejong_pages set payload=jsonb_set(payload,'{completion}','{"path":"/about/disclosure/management","title":"경영공시","summary":"기관의 계획과 집행 결과를 예산·결산·평가 자료로 확인할 수 있습니다.","sections":[{"type":"prose","title":"계획과 결과를 함께 읽으세요","paragraphs":["사업설명서와 주요업무계획은 기관이 추진하는 사업을, 예산은 해당 연도의 재원과 지출 계획을 보여줍니다. 회계결산보고서와 재무상태표·운영성과표는 회계연도별 결과를 확인하는 자료입니다.","공시 자료를 비교할 때에는 회계연도와 자료명을 먼저 확인해 주세요. 당초 예산과 집행 결과는 구분해 읽고, 세부 금액과 주석은 공식 첨부 원문을 기준으로 확인할 수 있습니다."]},{"type":"table","title":"자료별 활용","columns":["알고 싶은 내용","확인할 자료"],"rows":[["연간 사업의 방향과 구성","사업설명서·주요업무계획"],["한 해의 재정 계획","세종문화회관 예산"],["회계연도별 재정 결과","회계결산보고서·재무상태표·운영성과표"],["기관 운영 평가","경영실적 평가결과·고객만족도 조사결과"],["의사결정 기록","이사회 회의록"],["후원금 활용","기부금 모금·활용실적"]]},{"type":"links","title":"공시 원문 자료실","items":[{"label":"사업설명서","href":"https://www.sejongpac.or.kr/portal/bbs/B0000100/list.do?menuNo=200597"},{"label":"주요업무계획","href":"https://www.sejongpac.or.kr/portal/bbs/B0000101/list.do?menuNo=200600"},{"label":"예산","href":"https://www.sejongpac.or.kr/portal/bbs/B0000102/view.do?menuNo=200603"},{"label":"회계결산보고서","href":"https://www.sejongpac.or.kr/portal/bbs/B0000113/list.do?menuNo=200614","description":"2025·2024·2023·2022 회계연도 보고서가 게시되어 있습니다."},{"label":"경영실적 평가결과","href":"https://www.sejongpac.or.kr/portal/bbs/B0000103/view.do?menuNo=200604"},{"label":"이사회 회의록","href":"https://www.sejongpac.or.kr/portal/bbs/B0000105/list.do?menuNo=200606"},{"label":"기부금 모금·활용실적","href":"https://www.sejongpac.or.kr/portal/bbs/B0000118/list.do?menuNo=200617"},{"label":"ESG 경영 보고서","href":"https://www.sejongpac.or.kr/portal/bbs/B0000123/list.do?menuNo=200633"}]}],"sources":[{"label":"공식 사전공표목록","url":"https://www.sejongpac.or.kr/portal/main/contents.do?menuNo=200528"},{"label":"예산 공개","url":"https://www.sejongpac.or.kr/portal/bbs/B0000102/view.do?menuNo=200603"},{"label":"회계결산보고서 목록","url":"https://www.sejongpac.or.kr/portal/bbs/B0000113/list.do?menuNo=200614"}]}'::jsonb,true) where id='/about/disclosure/management' and payload->'completion' is distinct from '{"path":"/about/disclosure/management","title":"경영공시","summary":"기관의 계획과 집행 결과를 예산·결산·평가 자료로 확인할 수 있습니다.","sections":[{"type":"prose","title":"계획과 결과를 함께 읽으세요","paragraphs":["사업설명서와 주요업무계획은 기관이 추진하는 사업을, 예산은 해당 연도의 재원과 지출 계획을 보여줍니다. 회계결산보고서와 재무상태표·운영성과표는 회계연도별 결과를 확인하는 자료입니다.","공시 자료를 비교할 때에는 회계연도와 자료명을 먼저 확인해 주세요. 당초 예산과 집행 결과는 구분해 읽고, 세부 금액과 주석은 공식 첨부 원문을 기준으로 확인할 수 있습니다."]},{"type":"table","title":"자료별 활용","columns":["알고 싶은 내용","확인할 자료"],"rows":[["연간 사업의 방향과 구성","사업설명서·주요업무계획"],["한 해의 재정 계획","세종문화회관 예산"],["회계연도별 재정 결과","회계결산보고서·재무상태표·운영성과표"],["기관 운영 평가","경영실적 평가결과·고객만족도 조사결과"],["의사결정 기록","이사회 회의록"],["후원금 활용","기부금 모금·활용실적"]]},{"type":"links","title":"공시 원문 자료실","items":[{"label":"사업설명서","href":"https://www.sejongpac.or.kr/portal/bbs/B0000100/list.do?menuNo=200597"},{"label":"주요업무계획","href":"https://www.sejongpac.or.kr/portal/bbs/B0000101/list.do?menuNo=200600"},{"label":"예산","href":"https://www.sejongpac.or.kr/portal/bbs/B0000102/view.do?menuNo=200603"},{"label":"회계결산보고서","href":"https://www.sejongpac.or.kr/portal/bbs/B0000113/list.do?menuNo=200614","description":"2025·2024·2023·2022 회계연도 보고서가 게시되어 있습니다."},{"label":"경영실적 평가결과","href":"https://www.sejongpac.or.kr/portal/bbs/B0000103/view.do?menuNo=200604"},{"label":"이사회 회의록","href":"https://www.sejongpac.or.kr/portal/bbs/B0000105/list.do?menuNo=200606"},{"label":"기부금 모금·활용실적","href":"https://www.sejongpac.or.kr/portal/bbs/B0000118/list.do?menuNo=200617"},{"label":"ESG 경영 보고서","href":"https://www.sejongpac.or.kr/portal/bbs/B0000123/list.do?menuNo=200633"}]}],"sources":[{"label":"공식 사전공표목록","url":"https://www.sejongpac.or.kr/portal/main/contents.do?menuNo=200528"},{"label":"예산 공개","url":"https://www.sejongpac.or.kr/portal/bbs/B0000102/view.do?menuNo=200603"},{"label":"회계결산보고서 목록","url":"https://www.sejongpac.or.kr/portal/bbs/B0000113/list.do?menuNo=200614"}]}'::jsonb;
update public.sejong_pages set payload=jsonb_set(payload,'{completion}','{"path":"/about/disclosure/request","title":"정보공개청구","summary":"먼저 공개자료를 확인한 뒤, 필요한 기록을 정보공개포털에서 청구할 수 있습니다.","sections":[{"type":"prose","title":"청구 전에 확인하세요","paragraphs":["세종문화회관 사전공표목록에는 공개된 경영·재정·회의 자료의 위치가 안내되어 있습니다. 자료가 이미 공개되어 있다면 해당 자료실에서 바로 열람하는 것이 빠릅니다.","공식 정보공개청구 접수 경로는 정보공개포털입니다. 청구기관을 선택하고 필요한 기록의 제목, 대상 기간과 범위를 구체적으로 작성해 주세요. 접수와 처리 내역은 포털에서 확인합니다."]},{"type":"timeline","title":"청구 준비와 접수","items":[{"date":"1","title":"사전공표목록 검색","body":"예산·결산·업무계획·정보목록 등 이미 게시된 자료를 찾습니다."},{"date":"2","title":"기록의 범위 정리","body":"필요한 문서명이나 사업명, 대상 연도·기간, 확인하려는 항목을 정리합니다."},{"date":"3","title":"정보공개포털에서 청구","body":"포털 안내에 따라 청구기관과 공개 방법을 선택하고 신청합니다."},{"date":"4","title":"처리 내역 확인","body":"청구번호를 보관하고 포털의 통지·보완 요청·결정 내용을 확인합니다."}]},{"type":"faq","title":"문의 유형에 맞는 창구","items":[{"question":"예매 변경이나 공연 문의도 정보공개청구로 하나요?","answer":"공연·예매·시설 이용에 관한 문의는 고객문의 또는 대표전화 02-399-1000을 이용해 주세요. 정보공개청구는 기관이 보유한 기록의 공개를 요청하는 절차입니다."},{"question":"공개가 제한되는 정보는 어디서 확인하나요?","answer":"공식 정보공개 메뉴의 비공개 대상정보를 참고하세요. 개별 청구의 공개 범위와 결정 내용은 접수기관의 통지를 확인해야 합니다."}]},{"type":"links","title":"공식 접수와 자료 확인","items":[{"label":"정보공개포털에서 청구","href":"https://www.open.go.kr/com/main/mainView.do"},{"label":"세종문화회관 사전공표목록","href":"https://www.sejongpac.or.kr/portal/main/contents.do?menuNo=200528"},{"label":"비공개 대상정보","href":"https://www.sejongpac.or.kr/portal/bbs/B0000107/view.do?menuNo=200608"},{"label":"공연·이용 문의","href":"/visit/support/inquiry"}]}],"sources":[{"label":"사전공표목록·공식 정보공개청구 연결","url":"https://www.sejongpac.or.kr/portal/main/contents.do?menuNo=200528"}]}'::jsonb,true) where id='/about/disclosure/request' and payload->'completion' is distinct from '{"path":"/about/disclosure/request","title":"정보공개청구","summary":"먼저 공개자료를 확인한 뒤, 필요한 기록을 정보공개포털에서 청구할 수 있습니다.","sections":[{"type":"prose","title":"청구 전에 확인하세요","paragraphs":["세종문화회관 사전공표목록에는 공개된 경영·재정·회의 자료의 위치가 안내되어 있습니다. 자료가 이미 공개되어 있다면 해당 자료실에서 바로 열람하는 것이 빠릅니다.","공식 정보공개청구 접수 경로는 정보공개포털입니다. 청구기관을 선택하고 필요한 기록의 제목, 대상 기간과 범위를 구체적으로 작성해 주세요. 접수와 처리 내역은 포털에서 확인합니다."]},{"type":"timeline","title":"청구 준비와 접수","items":[{"date":"1","title":"사전공표목록 검색","body":"예산·결산·업무계획·정보목록 등 이미 게시된 자료를 찾습니다."},{"date":"2","title":"기록의 범위 정리","body":"필요한 문서명이나 사업명, 대상 연도·기간, 확인하려는 항목을 정리합니다."},{"date":"3","title":"정보공개포털에서 청구","body":"포털 안내에 따라 청구기관과 공개 방법을 선택하고 신청합니다."},{"date":"4","title":"처리 내역 확인","body":"청구번호를 보관하고 포털의 통지·보완 요청·결정 내용을 확인합니다."}]},{"type":"faq","title":"문의 유형에 맞는 창구","items":[{"question":"예매 변경이나 공연 문의도 정보공개청구로 하나요?","answer":"공연·예매·시설 이용에 관한 문의는 고객문의 또는 대표전화 02-399-1000을 이용해 주세요. 정보공개청구는 기관이 보유한 기록의 공개를 요청하는 절차입니다."},{"question":"공개가 제한되는 정보는 어디서 확인하나요?","answer":"공식 정보공개 메뉴의 비공개 대상정보를 참고하세요. 개별 청구의 공개 범위와 결정 내용은 접수기관의 통지를 확인해야 합니다."}]},{"type":"links","title":"공식 접수와 자료 확인","items":[{"label":"정보공개포털에서 청구","href":"https://www.open.go.kr/com/main/mainView.do"},{"label":"세종문화회관 사전공표목록","href":"https://www.sejongpac.or.kr/portal/main/contents.do?menuNo=200528"},{"label":"비공개 대상정보","href":"https://www.sejongpac.or.kr/portal/bbs/B0000107/view.do?menuNo=200608"},{"label":"공연·이용 문의","href":"/visit/support/inquiry"}]}],"sources":[{"label":"사전공표목록·공식 정보공개청구 연결","url":"https://www.sejongpac.or.kr/portal/main/contents.do?menuNo=200528"}]}'::jsonb;
update public.sejong_pages set payload=jsonb_set(payload,'{completion}','{"path":"/about/donation","title":"후원 안내","summary":"세종문화회관의 발전과 문화예술 향유 기회 확대에 함께하는 후원회입니다.","sections":[{"type":"prose","title":"예술의 기반을 함께 만듭니다","paragraphs":["세종문화회관 후원회는 회관 발전을 위한 기금을 마련하고 문화예술 향유 계층과 메세나 활동을 확대하기 위해 활동합니다. 회원 간 친교와 예술인과의 교류도 이어갑니다.","개인과 법인 회원을 구분해 운영하며 후원금에 따른 등급과 예우 프로그램을 안내합니다. 가입 전 담당자에게 후원 목적과 회원 유형을 상담하고, 공식 안내문에서 적용 기준을 확인해 주세요."]},{"type":"timeline","title":"공식 가입 절차","items":[{"date":"1","title":"가입신청서 제출","body":"공식 가입신청서를 작성해 후원회 담당자에게 제출합니다."},{"date":"2","title":"운영진 승인","body":"후원회 운영진의 가입 승인 절차를 거칩니다."},{"date":"3","title":"후원금 납부","body":"승인 후 담당자가 안내하는 방식으로 납부합니다."},{"date":"4","title":"가입 완료","body":"후원회 가입과 해당 예우 프로그램을 안내받습니다."}]},{"type":"facts","title":"후원회 연락처","items":[{"label":"전화","value":"02-399-1722, 02-399-1724"},{"label":"팩스","value":"02-399-1798"},{"label":"이메일","value":"sponsorship@sejongpac.or.kr"},{"label":"공통 예우 안내","value":"총회와 후원회 음악회 초대, 기부금 영수증 발급, 세종문화N 구독 등. 세부 조건은 공식 안내문을 확인해 주세요."}]},{"type":"downloads","title":"후원회 공식 서식","items":[{"label":"후원회 가입신청서","href":"https://www.sejongpac.or.kr/portal/cmmn/file/fileDown.do?atchFileId=a223a62f-42a8-4007-b36f-dd3fd6d0f54b&fileSn=1"},{"label":"후원회 안내","href":"https://www.sejongpac.or.kr/portal/cmmn/file/fileDown.do?atchFileId=b7d94b1ce7e748f6911cfd1c8b288aaf&fileSn=2","description":"회원 등급과 예우 프로그램을 확인할 수 있습니다."}]},{"type":"links","title":"상담과 공개자료","items":[{"label":"후원 상담 신청","href":"/about/donation/apply"},{"label":"기부금 모금·활용실적","href":"https://www.sejongpac.or.kr/portal/bbs/B0000118/list.do?menuNo=200617"},{"label":"공식 후원회 소개","href":"https://www.sejongpac.or.kr/portal/main/contents.do?menuNo=200514"}]}],"sources":[{"label":"후원회 소개·가입 절차·문의","url":"https://www.sejongpac.or.kr/portal/main/contents.do?menuNo=200514"},{"label":"기부금 모금·활용실적","url":"https://www.sejongpac.or.kr/portal/bbs/B0000118/list.do?menuNo=200617"}]}'::jsonb,true) where id='/about/donation' and payload->'completion' is distinct from '{"path":"/about/donation","title":"후원 안내","summary":"세종문화회관의 발전과 문화예술 향유 기회 확대에 함께하는 후원회입니다.","sections":[{"type":"prose","title":"예술의 기반을 함께 만듭니다","paragraphs":["세종문화회관 후원회는 회관 발전을 위한 기금을 마련하고 문화예술 향유 계층과 메세나 활동을 확대하기 위해 활동합니다. 회원 간 친교와 예술인과의 교류도 이어갑니다.","개인과 법인 회원을 구분해 운영하며 후원금에 따른 등급과 예우 프로그램을 안내합니다. 가입 전 담당자에게 후원 목적과 회원 유형을 상담하고, 공식 안내문에서 적용 기준을 확인해 주세요."]},{"type":"timeline","title":"공식 가입 절차","items":[{"date":"1","title":"가입신청서 제출","body":"공식 가입신청서를 작성해 후원회 담당자에게 제출합니다."},{"date":"2","title":"운영진 승인","body":"후원회 운영진의 가입 승인 절차를 거칩니다."},{"date":"3","title":"후원금 납부","body":"승인 후 담당자가 안내하는 방식으로 납부합니다."},{"date":"4","title":"가입 완료","body":"후원회 가입과 해당 예우 프로그램을 안내받습니다."}]},{"type":"facts","title":"후원회 연락처","items":[{"label":"전화","value":"02-399-1722, 02-399-1724"},{"label":"팩스","value":"02-399-1798"},{"label":"이메일","value":"sponsorship@sejongpac.or.kr"},{"label":"공통 예우 안내","value":"총회와 후원회 음악회 초대, 기부금 영수증 발급, 세종문화N 구독 등. 세부 조건은 공식 안내문을 확인해 주세요."}]},{"type":"downloads","title":"후원회 공식 서식","items":[{"label":"후원회 가입신청서","href":"https://www.sejongpac.or.kr/portal/cmmn/file/fileDown.do?atchFileId=a223a62f-42a8-4007-b36f-dd3fd6d0f54b&fileSn=1"},{"label":"후원회 안내","href":"https://www.sejongpac.or.kr/portal/cmmn/file/fileDown.do?atchFileId=b7d94b1ce7e748f6911cfd1c8b288aaf&fileSn=2","description":"회원 등급과 예우 프로그램을 확인할 수 있습니다."}]},{"type":"links","title":"상담과 공개자료","items":[{"label":"후원 상담 신청","href":"/about/donation/apply"},{"label":"기부금 모금·활용실적","href":"https://www.sejongpac.or.kr/portal/bbs/B0000118/list.do?menuNo=200617"},{"label":"공식 후원회 소개","href":"https://www.sejongpac.or.kr/portal/main/contents.do?menuNo=200514"}]}],"sources":[{"label":"후원회 소개·가입 절차·문의","url":"https://www.sejongpac.or.kr/portal/main/contents.do?menuNo=200514"},{"label":"기부금 모금·활용실적","url":"https://www.sejongpac.or.kr/portal/bbs/B0000118/list.do?menuNo=200617"}]}'::jsonb;
update public.sejong_pages set payload=jsonb_set(payload,'{completion}','{"path":"/about/donation/apply","title":"후원 상담 신청","summary":"후원 목적과 관심 분야를 남겨주시면 상담에 필요한 내용을 확인할 수 있습니다.","sections":[{"type":"prose","title":"어떤 후원을 생각하고 계신가요?","paragraphs":["개인 후원, 법인 후원, 후원회 가입 등 상담하려는 유형과 관심 분야를 적어 주세요. 후원 대상이나 시기를 아직 정하지 않았다면 검토 중인 내용을 편하게 남기실 수 있습니다.","이 신청은 후원 상담을 위한 접수입니다. 후원회 가입은 공식 가입신청서 제출, 운영진 승인, 후원금 납부 절차를 거쳐 완료됩니다. 접수만으로 가입이나 결제가 완료되지는 않습니다."]},{"type":"facts","title":"상담을 위해 준비할 내용","items":[{"label":"신청 주체","value":"개인 또는 법인·단체명, 담당자 이름"},{"label":"연락 방법","value":"회신받을 이메일과 연락처"},{"label":"후원 관심 내용","value":"관심 있는 예술 활동, 후원의 목적, 희망 시기"},{"label":"예산·금액","value":"검토 중인 범위가 있으면 본문에 기재해 주세요."}]},{"type":"downloads","title":"정식 가입을 위한 자료","items":[{"label":"후원회 가입신청서","href":"https://www.sejongpac.or.kr/portal/cmmn/file/fileDown.do?atchFileId=a223a62f-42a8-4007-b36f-dd3fd6d0f54b&fileSn=1"},{"label":"후원회 안내문","href":"https://www.sejongpac.or.kr/portal/cmmn/file/fileDown.do?atchFileId=b7d94b1ce7e748f6911cfd1c8b288aaf&fileSn=2"}]},{"type":"links","title":"담당자에게 직접 문의","items":[{"label":"후원회 전화 02-399-1722","href":"tel:02-399-1722"},{"label":"후원회 이메일","href":"mailto:sponsorship@sejongpac.or.kr"}]}],"form":{"kind":"donation","title":"후원 상담 신청","description":"후원 유형과 관심 분야, 희망하는 상담 내용을 작성해 주세요."},"sources":[{"label":"후원회 공식 신청 절차·문의","url":"https://www.sejongpac.or.kr/portal/main/contents.do?menuNo=200514"}]}'::jsonb,true) where id='/about/donation/apply' and payload->'completion' is distinct from '{"path":"/about/donation/apply","title":"후원 상담 신청","summary":"후원 목적과 관심 분야를 남겨주시면 상담에 필요한 내용을 확인할 수 있습니다.","sections":[{"type":"prose","title":"어떤 후원을 생각하고 계신가요?","paragraphs":["개인 후원, 법인 후원, 후원회 가입 등 상담하려는 유형과 관심 분야를 적어 주세요. 후원 대상이나 시기를 아직 정하지 않았다면 검토 중인 내용을 편하게 남기실 수 있습니다.","이 신청은 후원 상담을 위한 접수입니다. 후원회 가입은 공식 가입신청서 제출, 운영진 승인, 후원금 납부 절차를 거쳐 완료됩니다. 접수만으로 가입이나 결제가 완료되지는 않습니다."]},{"type":"facts","title":"상담을 위해 준비할 내용","items":[{"label":"신청 주체","value":"개인 또는 법인·단체명, 담당자 이름"},{"label":"연락 방법","value":"회신받을 이메일과 연락처"},{"label":"후원 관심 내용","value":"관심 있는 예술 활동, 후원의 목적, 희망 시기"},{"label":"예산·금액","value":"검토 중인 범위가 있으면 본문에 기재해 주세요."}]},{"type":"downloads","title":"정식 가입을 위한 자료","items":[{"label":"후원회 가입신청서","href":"https://www.sejongpac.or.kr/portal/cmmn/file/fileDown.do?atchFileId=a223a62f-42a8-4007-b36f-dd3fd6d0f54b&fileSn=1"},{"label":"후원회 안내문","href":"https://www.sejongpac.or.kr/portal/cmmn/file/fileDown.do?atchFileId=b7d94b1ce7e748f6911cfd1c8b288aaf&fileSn=2"}]},{"type":"links","title":"담당자에게 직접 문의","items":[{"label":"후원회 전화 02-399-1722","href":"tel:02-399-1722"},{"label":"후원회 이메일","href":"mailto:sponsorship@sejongpac.or.kr"}]}],"form":{"kind":"donation","title":"후원 상담 신청","description":"후원 유형과 관심 분야, 희망하는 상담 내용을 작성해 주세요."},"sources":[{"label":"후원회 공식 신청 절차·문의","url":"https://www.sejongpac.or.kr/portal/main/contents.do?menuNo=200514"}]}'::jsonb;
update public.sejong_pages set payload=jsonb_set(payload,'{completion}','{"path":"/about/esg","title":"ESG경영","summary":"환경을 생각하고, 예술의 기회를 넓히고, 신뢰받는 기관 운영을 실천합니다.","sections":[{"type":"prose","title":"지속가능한 예술 생태계를 향해","paragraphs":["세종문화회관은 시민과 예술을 잇는 문화 플랫폼으로서 지속가능한 예술 생태계를 이끄는 것을 ESG 미션으로 제시합니다. 비전은 누구나 예술을 누리면서 함께 지속하는 문화예술기관을 만드는 것입니다.","친환경 경영, 동반·상생의 사회적 책임 경영, 청렴·윤리 경영의 세 영역에 10대 전략과제를 두고 있습니다. 구체적인 연간 활동과 실적은 ESG 경영 보고서에서 확인할 수 있습니다."]},{"type":"cards","title":"세 가지 실천 영역","items":[{"id":"esg-environment","title":"환경","href":"/about/esg/environment","description":"에너지 효율, 폐기물 감축, 지속가능한 공연 제작"},{"id":"esg-social","title":"사회","href":"/about/esg/social","description":"예술 접근성, 약자와의 동행, 안전·인권과 상생협력"},{"id":"esg-governance","title":"지배구조","href":"/about/esg/governance","description":"청렴·준법, 정보공개, ESG 성과관리"}]},{"type":"links","title":"전략과 활동 원문","items":[{"label":"공식 ESG경영 전략체계","href":"https://www.sejongpac.or.kr/portal/main/contents.do?menuNo=200632"},{"label":"ESG 경영 보고서","href":"https://www.sejongpac.or.kr/portal/bbs/B0000123/list.do?menuNo=200633","description":"2025년·2024년 보고서가 게시되어 있습니다."},{"label":"경영공시","href":"/about/disclosure/management"}]}],"sources":[{"label":"ESG경영 전략체계","url":"https://www.sejongpac.or.kr/portal/main/contents.do?menuNo=200632"},{"label":"ESG 경영 보고서 목록","url":"https://www.sejongpac.or.kr/portal/bbs/B0000123/list.do?menuNo=200633"}]}'::jsonb,true) where id='/about/esg' and payload->'completion' is distinct from '{"path":"/about/esg","title":"ESG경영","summary":"환경을 생각하고, 예술의 기회를 넓히고, 신뢰받는 기관 운영을 실천합니다.","sections":[{"type":"prose","title":"지속가능한 예술 생태계를 향해","paragraphs":["세종문화회관은 시민과 예술을 잇는 문화 플랫폼으로서 지속가능한 예술 생태계를 이끄는 것을 ESG 미션으로 제시합니다. 비전은 누구나 예술을 누리면서 함께 지속하는 문화예술기관을 만드는 것입니다.","친환경 경영, 동반·상생의 사회적 책임 경영, 청렴·윤리 경영의 세 영역에 10대 전략과제를 두고 있습니다. 구체적인 연간 활동과 실적은 ESG 경영 보고서에서 확인할 수 있습니다."]},{"type":"cards","title":"세 가지 실천 영역","items":[{"id":"esg-environment","title":"환경","href":"/about/esg/environment","description":"에너지 효율, 폐기물 감축, 지속가능한 공연 제작"},{"id":"esg-social","title":"사회","href":"/about/esg/social","description":"예술 접근성, 약자와의 동행, 안전·인권과 상생협력"},{"id":"esg-governance","title":"지배구조","href":"/about/esg/governance","description":"청렴·준법, 정보공개, ESG 성과관리"}]},{"type":"links","title":"전략과 활동 원문","items":[{"label":"공식 ESG경영 전략체계","href":"https://www.sejongpac.or.kr/portal/main/contents.do?menuNo=200632"},{"label":"ESG 경영 보고서","href":"https://www.sejongpac.or.kr/portal/bbs/B0000123/list.do?menuNo=200633","description":"2025년·2024년 보고서가 게시되어 있습니다."},{"label":"경영공시","href":"/about/disclosure/management"}]}],"sources":[{"label":"ESG경영 전략체계","url":"https://www.sejongpac.or.kr/portal/main/contents.do?menuNo=200632"},{"label":"ESG 경영 보고서 목록","url":"https://www.sejongpac.or.kr/portal/bbs/B0000123/list.do?menuNo=200633"}]}'::jsonb;
update public.sejong_pages set payload=jsonb_set(payload,'{completion}','{"path":"/about/esg/environment","title":"환경경영","summary":"공간 운영과 공연 제작 과정에서 환경 부담을 줄이는 방향을 제시합니다.","sections":[{"type":"table","title":"환경 분야의 세 가지 전략과제","columns":["과제","추진 방향"],"rows":[["탄소중립과 에너지 효율","공연장과 시설 운영에서 에너지 효율을 높이고 탄소중립을 고려합니다."],["친환경 운영과 폐기물 감축","기관 운영 과정의 환경 부담과 폐기물 발생을 줄이는 방향입니다."],["지속가능한 공연 제작","작품 제작과 운영의 지속가능성을 높이는 체계를 확대합니다."]],"note":"공식 ESG 전략과제의 취지를 정리했습니다. 연도별 이행 실적과 산정 기준은 ESG 경영 보고서 원문을 확인해 주세요."},{"type":"prose","title":"관람할 때 함께할 수 있는 일","paragraphs":["공연장 방문 시 대중교통을 이용하고, 현장의 분리배출 안내에 맞춰 쓰레기를 배출해 주세요. 필요할 때 모바일 예매 내역과 온라인 공연 정보를 활용하면 종이 사용을 줄이는 데 도움이 됩니다.","친환경 운영의 실제 성과는 목표와 구분해 살펴보는 것이 좋습니다. 연간 보고서를 읽을 때에는 보고 대상 기간, 에너지·배출량의 측정 범위와 이전 연도 비교 기준을 함께 확인해 보세요."]},{"type":"links","title":"관련 자료와 방문 정보","items":[{"label":"ESG 경영 보고서","href":"https://www.sejongpac.or.kr/portal/bbs/B0000123/list.do?menuNo=200633"},{"label":"ESG 전략체계","href":"https://www.sejongpac.or.kr/portal/main/contents.do?menuNo=200632"},{"label":"대중교통으로 오시는 길","href":"/visit/directions"}]}],"sources":[{"label":"환경 분야 ESG 전략과제","url":"https://www.sejongpac.or.kr/portal/main/contents.do?menuNo=200632"},{"label":"연간 ESG 경영 보고서","url":"https://www.sejongpac.or.kr/portal/bbs/B0000123/list.do?menuNo=200633"}]}'::jsonb,true) where id='/about/esg/environment' and payload->'completion' is distinct from '{"path":"/about/esg/environment","title":"환경경영","summary":"공간 운영과 공연 제작 과정에서 환경 부담을 줄이는 방향을 제시합니다.","sections":[{"type":"table","title":"환경 분야의 세 가지 전략과제","columns":["과제","추진 방향"],"rows":[["탄소중립과 에너지 효율","공연장과 시설 운영에서 에너지 효율을 높이고 탄소중립을 고려합니다."],["친환경 운영과 폐기물 감축","기관 운영 과정의 환경 부담과 폐기물 발생을 줄이는 방향입니다."],["지속가능한 공연 제작","작품 제작과 운영의 지속가능성을 높이는 체계를 확대합니다."]],"note":"공식 ESG 전략과제의 취지를 정리했습니다. 연도별 이행 실적과 산정 기준은 ESG 경영 보고서 원문을 확인해 주세요."},{"type":"prose","title":"관람할 때 함께할 수 있는 일","paragraphs":["공연장 방문 시 대중교통을 이용하고, 현장의 분리배출 안내에 맞춰 쓰레기를 배출해 주세요. 필요할 때 모바일 예매 내역과 온라인 공연 정보를 활용하면 종이 사용을 줄이는 데 도움이 됩니다.","친환경 운영의 실제 성과는 목표와 구분해 살펴보는 것이 좋습니다. 연간 보고서를 읽을 때에는 보고 대상 기간, 에너지·배출량의 측정 범위와 이전 연도 비교 기준을 함께 확인해 보세요."]},{"type":"links","title":"관련 자료와 방문 정보","items":[{"label":"ESG 경영 보고서","href":"https://www.sejongpac.or.kr/portal/bbs/B0000123/list.do?menuNo=200633"},{"label":"ESG 전략체계","href":"https://www.sejongpac.or.kr/portal/main/contents.do?menuNo=200632"},{"label":"대중교통으로 오시는 길","href":"/visit/directions"}]}],"sources":[{"label":"환경 분야 ESG 전략과제","url":"https://www.sejongpac.or.kr/portal/main/contents.do?menuNo=200632"},{"label":"연간 ESG 경영 보고서","url":"https://www.sejongpac.or.kr/portal/bbs/B0000123/list.do?menuNo=200633"}]}'::jsonb;
update public.sejong_pages set payload=jsonb_set(payload,'{completion}','{"path":"/about/esg/governance","title":"투명경영","summary":"청렴·준법과 정보공개를 바탕으로 시민의 신뢰를 높입니다.","sections":[{"type":"table","title":"지배구조 분야 전략과제","columns":["과제","확인할 내용"],"rows":[["청렴·준법과 내부통제","윤리경영 추진전략, 임직원행동강령, 감사·신고 제도"],["시민참여와 정보공개","사전공표목록, 예산·결산·업무추진비, 이사회 회의록"],["ESG 운영·성과관리","ESG 전략체계와 연간 경영 보고서"]]},{"type":"prose","title":"의사결정과 운영자료 공개","paragraphs":["기관의 공식 조직도에서 이사회와 사장, 본부·부서 구성을 확인할 수 있습니다. 이사회 회의록은 회의 개최 시 공개하는 사전공표 항목입니다.","윤리기준은 윤리헌장과 임직원행동강령 등으로 안내하고 있습니다. 입찰 피해나 예산낭비, 부당한 계약 관계, 임직원 비리 관련 신고는 공식 부조리 신고센터에서 접수합니다."]},{"type":"links","title":"투명경영 확인 경로","items":[{"label":"조직과 이사회","href":"/about/introduction/organization"},{"label":"이사회 회의록 원문","href":"https://www.sejongpac.or.kr/portal/bbs/B0000105/list.do?menuNo=200606"},{"label":"경영공시 자료","href":"/about/disclosure/management"},{"label":"윤리경영·신고 안내","href":"/about/disclosure/ethics"},{"label":"ESG 경영 보고서","href":"https://www.sejongpac.or.kr/portal/bbs/B0000123/list.do?menuNo=200633"}]}],"sources":[{"label":"ESG 전략과제","url":"https://www.sejongpac.or.kr/portal/main/contents.do?menuNo=200632"},{"label":"조직도","url":"https://www.sejongpac.or.kr/portal/organizationalList/organizationalList/list.do?menuNo=200471"},{"label":"사전공표목록","url":"https://www.sejongpac.or.kr/portal/main/contents.do?menuNo=200528"},{"label":"부조리 신고센터","url":"https://www.sejongpac.or.kr/portal/main/contents.do?menuNo=200517"}]}'::jsonb,true) where id='/about/esg/governance' and payload->'completion' is distinct from '{"path":"/about/esg/governance","title":"투명경영","summary":"청렴·준법과 정보공개를 바탕으로 시민의 신뢰를 높입니다.","sections":[{"type":"table","title":"지배구조 분야 전략과제","columns":["과제","확인할 내용"],"rows":[["청렴·준법과 내부통제","윤리경영 추진전략, 임직원행동강령, 감사·신고 제도"],["시민참여와 정보공개","사전공표목록, 예산·결산·업무추진비, 이사회 회의록"],["ESG 운영·성과관리","ESG 전략체계와 연간 경영 보고서"]]},{"type":"prose","title":"의사결정과 운영자료 공개","paragraphs":["기관의 공식 조직도에서 이사회와 사장, 본부·부서 구성을 확인할 수 있습니다. 이사회 회의록은 회의 개최 시 공개하는 사전공표 항목입니다.","윤리기준은 윤리헌장과 임직원행동강령 등으로 안내하고 있습니다. 입찰 피해나 예산낭비, 부당한 계약 관계, 임직원 비리 관련 신고는 공식 부조리 신고센터에서 접수합니다."]},{"type":"links","title":"투명경영 확인 경로","items":[{"label":"조직과 이사회","href":"/about/introduction/organization"},{"label":"이사회 회의록 원문","href":"https://www.sejongpac.or.kr/portal/bbs/B0000105/list.do?menuNo=200606"},{"label":"경영공시 자료","href":"/about/disclosure/management"},{"label":"윤리경영·신고 안내","href":"/about/disclosure/ethics"},{"label":"ESG 경영 보고서","href":"https://www.sejongpac.or.kr/portal/bbs/B0000123/list.do?menuNo=200633"}]}],"sources":[{"label":"ESG 전략과제","url":"https://www.sejongpac.or.kr/portal/main/contents.do?menuNo=200632"},{"label":"조직도","url":"https://www.sejongpac.or.kr/portal/organizationalList/organizationalList/list.do?menuNo=200471"},{"label":"사전공표목록","url":"https://www.sejongpac.or.kr/portal/main/contents.do?menuNo=200528"},{"label":"부조리 신고센터","url":"https://www.sejongpac.or.kr/portal/main/contents.do?menuNo=200517"}]}'::jsonb;
update public.sejong_pages set payload=jsonb_set(payload,'{completion}','{"path":"/about/esg/social","title":"사회적 책임","summary":"문화예술의 접근성을 높이고 안전·인권·상생을 함께 살핍니다.","sections":[{"type":"facts","title":"사회 분야 전략과제","items":[{"label":"접근환경","value":"예술공간에 접근하기 쉽도록 환경과 이용 편의를 개선합니다."},{"label":"문화향유","value":"약자와 동행하며 문화예술을 경험할 기회를 넓힙니다."},{"label":"안전과 인권","value":"안전과 인권을 중심에 두고 기관을 운영합니다."},{"label":"상생","value":"일자리와 포용적인 조직문화를 만들고 협력 주체와 상생합니다."}]},{"type":"prose","title":"일상 속에서 누리는 예술","paragraphs":["사회공헌 프로그램 「모든 누구나」는 시민의 문화예술 경험을 넓히기 위한 사업입니다. 「누구나 클래식」은 해설을 더한 공연과 관람료 선택제를, 「누구나 꿈나무오케스트라」는 저소득층·다문화 가정 유·청소년의 예술교육 기회를 제공합니다.","「누구나 세종썸머페스티벌」은 시민을 위한 야외 공연예술 축제입니다. 프로그램별 참가 대상과 일정, 신청 방식은 각 사업의 공지를 확인해 주세요."]},{"type":"prose","title":"이용자와 일하는 사람의 인권","paragraphs":["세종문화회관은 기관의 경영활동과 사업 수행에서 인간의 존엄과 가치를 중시하는 인권경영을 안내합니다. 임직원·협력사·지역주민 등 이해관계자의 인권침해 요인을 조사하고 예방하며, 피해자 구제제도를 통해 권리를 보호하는 방향입니다."]},{"type":"links","title":"참여와 권리 보호","items":[{"label":"모든 누구나 사업 소개","href":"https://www.sejongpac.or.kr/portal/main/contents.do?menuNo=200446"},{"label":"장애인·접근성 이용 안내","href":"/visit/accessibility"},{"label":"인권경영 소개","href":"https://www.sejongpac.or.kr/portal/main/contents.do?menuNo=200524"},{"label":"인권침해신고센터","href":"https://www.sejongpac.or.kr/portal/main/contents.do?menuNo=200654"},{"label":"ESG 경영 보고서","href":"https://www.sejongpac.or.kr/portal/bbs/B0000123/list.do?menuNo=200633"}]}],"sources":[{"label":"사회 분야 ESG 전략과제","url":"https://www.sejongpac.or.kr/portal/main/contents.do?menuNo=200632"},{"label":"모든 누구나 소개","url":"https://www.sejongpac.or.kr/portal/main/contents.do?menuNo=200446"},{"label":"인권경영이란?","url":"https://www.sejongpac.or.kr/portal/main/contents.do?menuNo=200524"}]}'::jsonb,true) where id='/about/esg/social' and payload->'completion' is distinct from '{"path":"/about/esg/social","title":"사회적 책임","summary":"문화예술의 접근성을 높이고 안전·인권·상생을 함께 살핍니다.","sections":[{"type":"facts","title":"사회 분야 전략과제","items":[{"label":"접근환경","value":"예술공간에 접근하기 쉽도록 환경과 이용 편의를 개선합니다."},{"label":"문화향유","value":"약자와 동행하며 문화예술을 경험할 기회를 넓힙니다."},{"label":"안전과 인권","value":"안전과 인권을 중심에 두고 기관을 운영합니다."},{"label":"상생","value":"일자리와 포용적인 조직문화를 만들고 협력 주체와 상생합니다."}]},{"type":"prose","title":"일상 속에서 누리는 예술","paragraphs":["사회공헌 프로그램 「모든 누구나」는 시민의 문화예술 경험을 넓히기 위한 사업입니다. 「누구나 클래식」은 해설을 더한 공연과 관람료 선택제를, 「누구나 꿈나무오케스트라」는 저소득층·다문화 가정 유·청소년의 예술교육 기회를 제공합니다.","「누구나 세종썸머페스티벌」은 시민을 위한 야외 공연예술 축제입니다. 프로그램별 참가 대상과 일정, 신청 방식은 각 사업의 공지를 확인해 주세요."]},{"type":"prose","title":"이용자와 일하는 사람의 인권","paragraphs":["세종문화회관은 기관의 경영활동과 사업 수행에서 인간의 존엄과 가치를 중시하는 인권경영을 안내합니다. 임직원·협력사·지역주민 등 이해관계자의 인권침해 요인을 조사하고 예방하며, 피해자 구제제도를 통해 권리를 보호하는 방향입니다."]},{"type":"links","title":"참여와 권리 보호","items":[{"label":"모든 누구나 사업 소개","href":"https://www.sejongpac.or.kr/portal/main/contents.do?menuNo=200446"},{"label":"장애인·접근성 이용 안내","href":"/visit/accessibility"},{"label":"인권경영 소개","href":"https://www.sejongpac.or.kr/portal/main/contents.do?menuNo=200524"},{"label":"인권침해신고센터","href":"https://www.sejongpac.or.kr/portal/main/contents.do?menuNo=200654"},{"label":"ESG 경영 보고서","href":"https://www.sejongpac.or.kr/portal/bbs/B0000123/list.do?menuNo=200633"}]}],"sources":[{"label":"사회 분야 ESG 전략과제","url":"https://www.sejongpac.or.kr/portal/main/contents.do?menuNo=200632"},{"label":"모든 누구나 소개","url":"https://www.sejongpac.or.kr/portal/main/contents.do?menuNo=200446"},{"label":"인권경영이란?","url":"https://www.sejongpac.or.kr/portal/main/contents.do?menuNo=200524"}]}'::jsonb;
update public.sejong_pages set payload=jsonb_set(payload,'{completion}','{"path":"/about/introduction/ci","title":"CI 소개","summary":"세종문화회관의 건축과 한글에서 출발한 심볼, 로고와 색상 체계를 소개합니다.","sections":[{"type":"image","title":"공식 심볼마크","image":{"src":"https://www.sejongpac.or.kr/static/portal/img/content/ci_0101.png","alt":"세종문화회관 공식 심볼마크"}},{"type":"prose","title":"한글과 건축이 만나는 심볼","paragraphs":["심볼마크는 세종문화회관 첫 음절의 초성인 「ㅅ」과 건물 전면의 보 하나·기둥 여섯 개를 형상화했습니다. 기둥은 장막이 걷힌 무대를 암시하는 프레임으로도 확장됩니다.","공식 대표 이미지이면서 다양한 시각 결과물에 활용할 수 있는 가변 프레임입니다. 프레임으로 활용할 때에도 가로획과 세로획 사이의 간격을 유지하도록 안내합니다."]},{"type":"table","title":"기본 색상","columns":["구분","색상","RGB"],"rows":[["주색","검정","0, 0, 0"],["보조색 · 천","하늘색","84, 200, 232"],["보조색 · 지","황토색","195, 109, 21"],["보조색 · 인","노란색","255, 232, 0"],["보조색","흰색","255, 255, 255"]],"note":"천·지·인을 색상 체계로 표현하며 다양한 관람객을 나타낼 수 있도록 색상 확장성을 둡니다. 인쇄용 색상과 세부 적용은 공식 컬러 안내를 확인해 주세요."},{"type":"downloads","title":"공식 원본 내려받기","items":[{"label":"심볼마크 AI","href":"https://www.sejongpac.or.kr/portal/cmmn/file/fileDown.do?atchFileId=2a174cf0db4c4746a10da4b1811e3808&fileSn=4"},{"label":"심볼마크 JPG","href":"https://www.sejongpac.or.kr/portal/cmmn/file/fileDown.do?atchFileId=2a174cf0db4c4746a10da4b1811e3808&fileSn=2"},{"label":"로고타입 AI","href":"https://www.sejongpac.or.kr/portal/cmmn/file/fileDown.do?atchFileId=2a174cf0db4c4746a10da4b1811e3808&fileSn=6"},{"label":"로고타입 JPG","href":"https://www.sejongpac.or.kr/portal/cmmn/file/fileDown.do?atchFileId=2a174cf0db4c4746a10da4b1811e3808&fileSn=5"}]},{"type":"links","title":"사용 기준과 변화 과정","items":[{"label":"공식 로고·시그니처·사용 크기","href":"https://www.sejongpac.or.kr/portal/main/contents.do?menuNo=200508"},{"label":"아이덴티티 컬러","href":"https://www.sejongpac.or.kr/portal/main/contents.do?menuNo=200510"},{"label":"CI 히스토리","href":"https://www.sejongpac.or.kr/portal/main/contents.do?menuNo=200509"}]}],"sources":[{"label":"공식 아이덴티티 로고","url":"https://www.sejongpac.or.kr/portal/main/contents.do?menuNo=200508"},{"label":"공식 아이덴티티 컬러","url":"https://www.sejongpac.or.kr/portal/main/contents.do?menuNo=200510"}]}'::jsonb,true) where id='/about/introduction/ci' and payload->'completion' is distinct from '{"path":"/about/introduction/ci","title":"CI 소개","summary":"세종문화회관의 건축과 한글에서 출발한 심볼, 로고와 색상 체계를 소개합니다.","sections":[{"type":"image","title":"공식 심볼마크","image":{"src":"https://www.sejongpac.or.kr/static/portal/img/content/ci_0101.png","alt":"세종문화회관 공식 심볼마크"}},{"type":"prose","title":"한글과 건축이 만나는 심볼","paragraphs":["심볼마크는 세종문화회관 첫 음절의 초성인 「ㅅ」과 건물 전면의 보 하나·기둥 여섯 개를 형상화했습니다. 기둥은 장막이 걷힌 무대를 암시하는 프레임으로도 확장됩니다.","공식 대표 이미지이면서 다양한 시각 결과물에 활용할 수 있는 가변 프레임입니다. 프레임으로 활용할 때에도 가로획과 세로획 사이의 간격을 유지하도록 안내합니다."]},{"type":"table","title":"기본 색상","columns":["구분","색상","RGB"],"rows":[["주색","검정","0, 0, 0"],["보조색 · 천","하늘색","84, 200, 232"],["보조색 · 지","황토색","195, 109, 21"],["보조색 · 인","노란색","255, 232, 0"],["보조색","흰색","255, 255, 255"]],"note":"천·지·인을 색상 체계로 표현하며 다양한 관람객을 나타낼 수 있도록 색상 확장성을 둡니다. 인쇄용 색상과 세부 적용은 공식 컬러 안내를 확인해 주세요."},{"type":"downloads","title":"공식 원본 내려받기","items":[{"label":"심볼마크 AI","href":"https://www.sejongpac.or.kr/portal/cmmn/file/fileDown.do?atchFileId=2a174cf0db4c4746a10da4b1811e3808&fileSn=4"},{"label":"심볼마크 JPG","href":"https://www.sejongpac.or.kr/portal/cmmn/file/fileDown.do?atchFileId=2a174cf0db4c4746a10da4b1811e3808&fileSn=2"},{"label":"로고타입 AI","href":"https://www.sejongpac.or.kr/portal/cmmn/file/fileDown.do?atchFileId=2a174cf0db4c4746a10da4b1811e3808&fileSn=6"},{"label":"로고타입 JPG","href":"https://www.sejongpac.or.kr/portal/cmmn/file/fileDown.do?atchFileId=2a174cf0db4c4746a10da4b1811e3808&fileSn=5"}]},{"type":"links","title":"사용 기준과 변화 과정","items":[{"label":"공식 로고·시그니처·사용 크기","href":"https://www.sejongpac.or.kr/portal/main/contents.do?menuNo=200508"},{"label":"아이덴티티 컬러","href":"https://www.sejongpac.or.kr/portal/main/contents.do?menuNo=200510"},{"label":"CI 히스토리","href":"https://www.sejongpac.or.kr/portal/main/contents.do?menuNo=200509"}]}],"sources":[{"label":"공식 아이덴티티 로고","url":"https://www.sejongpac.or.kr/portal/main/contents.do?menuNo=200508"},{"label":"공식 아이덴티티 컬러","url":"https://www.sejongpac.or.kr/portal/main/contents.do?menuNo=200510"}]}'::jsonb;
update public.sejong_pages set payload=jsonb_set(payload,'{completion}','{"path":"/about/introduction/greeting","title":"CEO 인사말","summary":"시민의 예술 참여와 향유를 넓히고, 도전적인 작품을 만드는 세종문화회관의 방향입니다.","sections":[{"type":"image","title":"세종문화회관 사장","image":{"src":"https://www.sejongpac.or.kr/static/portal/img/content/img_ceo01.png","alt":"세종문화회관 사장 안호상"}},{"type":"facts","title":"기관 대표","items":[{"label":"사장","value":"안호상"},{"label":"기관","value":"재단법인 세종문화회관"}]},{"type":"prose","title":"공식 인사말의 주요 방향","paragraphs":["안호상 사장은 세종문화회관을 한국 공연예술의 역사와 함께해 온 문화예술기관으로 소개하며 시민의 예술 참여와 향유 확대를 강조합니다.","서울시예술단의 창작역량을 바탕으로 도전적이고 차별화된 작품을 선보여 제작극장의 정체성을 확립하고, 공연·전시·교육을 통해 서울의 문화적 긍지를 보여주는 예술공간을 지향합니다.","이 페이지는 공식 인사말의 취지를 요약한 소개입니다. 인사말 전문과 현재 기관 대표 정보는 아래 공식 원문에서 확인할 수 있습니다."]},{"type":"links","title":"기관의 방향과 활동","items":[{"label":"CEO 인사말 전문","href":"https://www.sejongpac.or.kr/portal/main/contents.do?menuNo=200469"},{"label":"서울시예술단","href":"/about/companies"},{"label":"조직도","href":"/about/introduction/organization"}]}],"sources":[{"label":"공식 CEO 인사말","url":"https://www.sejongpac.or.kr/portal/main/contents.do?menuNo=200469"}]}'::jsonb,true) where id='/about/introduction/greeting' and payload->'completion' is distinct from '{"path":"/about/introduction/greeting","title":"CEO 인사말","summary":"시민의 예술 참여와 향유를 넓히고, 도전적인 작품을 만드는 세종문화회관의 방향입니다.","sections":[{"type":"image","title":"세종문화회관 사장","image":{"src":"https://www.sejongpac.or.kr/static/portal/img/content/img_ceo01.png","alt":"세종문화회관 사장 안호상"}},{"type":"facts","title":"기관 대표","items":[{"label":"사장","value":"안호상"},{"label":"기관","value":"재단법인 세종문화회관"}]},{"type":"prose","title":"공식 인사말의 주요 방향","paragraphs":["안호상 사장은 세종문화회관을 한국 공연예술의 역사와 함께해 온 문화예술기관으로 소개하며 시민의 예술 참여와 향유 확대를 강조합니다.","서울시예술단의 창작역량을 바탕으로 도전적이고 차별화된 작품을 선보여 제작극장의 정체성을 확립하고, 공연·전시·교육을 통해 서울의 문화적 긍지를 보여주는 예술공간을 지향합니다.","이 페이지는 공식 인사말의 취지를 요약한 소개입니다. 인사말 전문과 현재 기관 대표 정보는 아래 공식 원문에서 확인할 수 있습니다."]},{"type":"links","title":"기관의 방향과 활동","items":[{"label":"CEO 인사말 전문","href":"https://www.sejongpac.or.kr/portal/main/contents.do?menuNo=200469"},{"label":"서울시예술단","href":"/about/companies"},{"label":"조직도","href":"/about/introduction/organization"}]}],"sources":[{"label":"공식 CEO 인사말","url":"https://www.sejongpac.or.kr/portal/main/contents.do?menuNo=200469"}]}'::jsonb;
update public.sejong_pages set payload=jsonb_set(payload,'{completion}','{"path":"/about/introduction/history","title":"연혁","summary":"1978년 개관부터 공연장 확장과 시민공간 조성으로 이어지는 주요 발자취입니다.","sections":[{"type":"prose","title":"공연장을 넘어 복합 문화공간으로","paragraphs":["1974년 착공한 세종문화회관은 1978년 4월 14일 개관했습니다. 1999년 재단법인 출범 이후 공연장과 미술관, 예술교육 공간을 확장하며 시민과 만나는 방식을 넓혀왔습니다."]},{"type":"timeline","title":"개관과 재단 출범","items":[{"date":"1974.01.01","title":"세종문화회관 착공","body":"현재 세종문화회관으로 이어지는 건립 공사가 시작되었습니다."},{"date":"1978.04.14","title":"준공 및 개관","body":"세종문화회관이 시민을 맞이했습니다."},{"date":"1999.07.01","title":"재단법인 출범","body":"재단법인 세종문화회관이 설립되었습니다."}]},{"type":"timeline","title":"예술공간의 확장","items":[{"date":"2004.03.02","title":"대극장 재개관","body":"시설 개·보수공사를 마치고 재개관했습니다."},{"date":"2006.08.14","title":"세종체임버홀 개관","body":"실내악을 위한 공연공간을 열었습니다."},{"date":"2007.06.19","title":"세종예술아카데미 개원","body":"시민의 예술교육을 위한 공간이 마련되었습니다."},{"date":"2007.12.01","title":"세종M씨어터 개관","body":"다양한 작품을 만나는 중규모 공연장이 문을 열었습니다."},{"date":"2009.10.09","title":"세종이야기 개관","body":"세종대왕의 업적을 만나는 전시공간을 열었습니다."},{"date":"2009.10.17","title":"북서울 꿈의숲아트센터 개관","body":"북서울 지역에 공연·전시 문화공간을 열었습니다."},{"date":"2010.04.28","title":"충무공이야기 개관","body":"충무공 이순신의 생애와 업적을 소개하는 공간을 열었습니다."},{"date":"2012.12.01","title":"세종예술동 증축","body":"예술 활동을 위한 공간을 확충했습니다."},{"date":"2015.04.06","title":"세종미술관 재개관","body":"전시공간을 새롭게 정비했습니다."},{"date":"2018.10.18","title":"세종S씨어터 개관","body":"새로운 공연 형식을 선보일 수 있는 공간을 열었습니다."}]},{"type":"timeline","title":"시민을 위한 공간","items":[{"date":"2019.06.19","title":"세종 아티스트라운지 개장","body":"예술가를 위한 교류공간을 마련했습니다."},{"date":"2023.02.07","title":"세종라운지 개장","body":"관람과 휴식을 연결하는 공간을 열었습니다."},{"date":"2023.12.29","title":"자료실 및 시민편의공간 개장","body":"시민을 위한 이용공간을 확장했습니다."}]},{"type":"links","title":"더 긴 역사와 오늘의 공간","items":[{"label":"공식 연혁 전체","href":"https://www.sejongpac.or.kr/portal/main/contents.do?menuNo=200506","description":"부민관·시민회관으로 이어지는 이전 역사도 확인할 수 있습니다."},{"label":"공연장과 공간 안내","href":"/visit"}]}],"sources":[{"label":"세종문화회관 공식 