update public.sejong_pages set payload=jsonb_set(payload,'{completion}','{"path":"/about/introduction/organization","title":"조직도","summary":"이사회와 사장, 경영·공연예술·문화사업 부문의 구성과 담당 창구를 안내합니다.","sections":[{"type":"facts","title":"기관 운영","items":[{"label":"이사장","value":"조미진"},{"label":"상임이사·사장","value":"안호상"},{"label":"사장 직속 조직","value":"정책보좌역, 감사실, 커뮤니케이션팀, 리빌딩추진단"}]},{"type":"table","title":"본부별 구성","columns":["본부","소속 부서"],"rows":[["경영본부","기획조정팀 · 재무행정팀 · 인사팀 · 시설운영팀 · 안전관리팀"],["공연예술본부","공연DX팀 · 공연제작1팀 · 공연제작2팀 · 발레제작팀 · 공연장운영팀 · 무대기술팀"],["문화사업본부","문화Biz개발팀 · 교육전시팀 · 시민예술팀 · 꿈의숲아트센터팀"]],"note":"2026년 10월 공식 조직도에서 확인한 구성입니다. 최신 조직과 직원별 담당업무·연락처는 공식 조직도에서 확인할 수 있습니다."},{"type":"prose","title":"담당 부서를 찾으실 때","paragraphs":["공식 조직도에서 부서 이름을 선택하면 담당업무와 연락처를 볼 수 있습니다. 문의할 공연명·공간명·신청 유형을 먼저 정리하면 담당자에게 내용을 전달하기 쉽습니다.","공연 관람과 예매 문의는 대표전화 02-399-1000으로, 후원회와 협력 제안은 각 안내 페이지의 담당 창구로 문의해 주세요. 예술단 정보는 서울시예술단 소개에서 확인할 수 있습니다."]},{"type":"links","title":"조직과 담당 창구","items":[{"label":"공식 조직도·직원별 담당업무","href":"https://www.sejongpac.or.kr/portal/organizationalList/organizationalList/list.do?menuNo=200471"},{"label":"서울시예술단","href":"/about/companies"},{"label":"후원회 문의","href":"/about/donation"},{"label":"협력·협찬 문의","href":"/about/partners"},{"label":"이사회 회의록","href":"https://www.sejongpac.or.kr/portal/bbs/B0000105/list.do?menuNo=200606"}]}],"sources":[{"label":"공식 조직도·이사회","url":"https://www.sejongpac.or.kr/portal/organizationalList/organizationalList/list.do?menuNo=200471"}]}'::jsonb,true) where id='/about/introduction/organization' and payload->'completion' is distinct from '{"path":"/about/introduction/organization","title":"조직도","summary":"이사회와 사장, 경영·공연예술·문화사업 부문의 구성과 담당 창구를 안내합니다.","sections":[{"type":"facts","title":"기관 운영","items":[{"label":"이사장","value":"조미진"},{"label":"상임이사·사장","value":"안호상"},{"label":"사장 직속 조직","value":"정책보좌역, 감사실, 커뮤니케이션팀, 리빌딩추진단"}]},{"type":"table","title":"본부별 구성","columns":["본부","소속 부서"],"rows":[["경영본부","기획조정팀 · 재무행정팀 · 인사팀 · 시설운영팀 · 안전관리팀"],["공연예술본부","공연DX팀 