update public.sejong_pages set payload=jsonb_set(payload,'{completion}','{"path":"/about/partners","title":"협력·협찬","summary":"기업과 다양한 협력 주체가 예술단·공간·콘텐츠·문화공헌 활동에 함께할 수 있습니다.","sections":[{"type":"prose","title":"예술을 함께 만드는 파트너십","paragraphs":["세종문화회관은 기업과 다양한 협력 주체가 가치를 공유하는 파트너십을 통해 시민과 예술가에게 더 넓은 기회를 제공하고자 합니다. 공식 안내는 예술단, 공간, 콘텐츠, 문화공헌 콘텐츠와의 협업을 제시합니다.","협력하고 싶은 대상과 목적을 먼저 정리해 주세요. 사업의 내용과 일정, 제공 가능한 자원과 기대하는 협력 방식에 따라 구체적인 실행 범위를 협의할 수 있습니다."]},{"type":"table","title":"공식 협업 분야","columns":["분야","제안할 때 정리할 내용"],"rows":[["예술단과 협업","관심 예술단이나 작품, 협력 목적과 희망 시기"],["공간과 협업","희망 공간, 사용 목적, 운영 방식과 일정"],["콘텐츠와 협업","콘텐츠 주제, 제작·유통 방식과 각 기관의 역할"],["문화공헌 콘텐츠와 협업","참여 대상, 예술 경험을 나누는 방식과 지원 내용"]],"note":"협업 분야는 공식 파트너십 안내를 따릅니다. 구체적인 실행 조건과 권리는 개별 협의가 필요합니다."},{"type":"facts","title":"파트너십 문의","items":[{"label":"전화","value":"02-399-1722"},{"label":"팩스","value":"02-399-1798"},{"label":"공식 안내에 게시된 이메일","value":"k2i7m@naver.com"}]},{"type":"links","title":"제안과 참고 자료","items":[{"label":"협력·협찬 제안하기","href":"/about/partners/apply"},{"label":"공식 파트너십 안내","href":"https://www.sejongpac.or.kr/portal/main/contents.do?menuNo=200512"},{"label":"후원회 가입 안내","href":"/about/donation","description":"개인·법인 후원회 가입을 검토할 때 확인해 주세요."},{"label":"대관 안내","href":"/rental","description":"공간 대관을 신청하려는 경우 대관공고와 절차를 확인해 주세요."}]}],"sources":[{"label":"공식 파트너십 분야·문의","url":"https://www.sejongpac.or.kr/portal/main/contents.do?menuNo=200512"}]}'::jsonb,true) where id='/about/partners' and payload->'completion' is distinct from '{"path":"/about/partners","title":"협력·협찬","summary":"기업과 다양한 협력 주체가 예술단·공간·콘텐츠·문화공헌 활동에 함께할 수 있습니다.","sections":[{"type":"prose","title":"예술을 함께 만드는 파트너십","paragraphs":["세종문화회관은 기업과 다양한 협력 주체가 가치를 공유하는 파트너십을 통해 시민과 예술가에게 더 넓은 기회를 제공하고자 합니다. 공식 안내는 예술단, 공간, 콘텐츠, 문화공헌 콘텐츠와의 협업을 제시합니다.","협력하고 싶은 대상과 목적을 먼저 정리해 주세요. 사업의 내용과 일정, 제공 가능한 자원과 기대하는 협력 방식에 따라 구체적인 실행 범위를 협의할 수 있습니다."]},{"type":"table","title":"공식 협업 분야","columns":["분야","제안할 때 정리할 내용"],"rows":[["예술단과 협업","관심 예술단이나 작품, 협력 목적과 희망 시기"],