update public.sejong_pages set payload=jsonb_set(payload,'{completion}','{"path":"/about/partners/apply","title":"협력·협찬 제안","summary":"기관 소개와 협력 목적, 대상과 일정을 정리해 제안해 주세요.","sections":[{"type":"prose","title":"함께할 내용을 알려주세요","paragraphs":["기업·기관·단체가 제안하는 협력의 목적과 실행 방식을 적어 주세요. 예술단, 공간, 콘텐츠, 문화공헌 중 관심 분야를 함께 작성하면 제안의 방향을 이해하는 데 도움이 됩니다.","이 신청은 제안 내용을 전달하기 위한 접수입니다. 접수 후 구체적인 사업 조건을 검토하고 협의하게 되며, 공연·공간 사용이나 협찬 권리가 확정되는 것은 아닙니다."]},{"type":"table","title":"제안서에 담으면 좋은 내용","columns":["항목","작성 안내"],"rows":[["제안 주체","기업·기관명, 사업 분야, 담당자와 회신 연락처"],["목적과 대상","협력하려는 이유, 관심 공연·예술단·공간 또는 참여 대상"],["실행 내용","운영 방식, 콘텐츠 구성, 각 기관이 맡을 역할"],["일정과 자원","희망 기간, 지원 가능한 현금·현물·인력 등 자원"],["기대 효과","관객·시민·예술가에게 제공할 경험과 제안 기관의 목표"]]},{"type":"faq","title":"접수 전 확인","items":[{"question":"공간을 빌리려는 경우에도 여기에 접수하나요?","answer":"공간 대관을 목적으로 하는 신청은 대관안내에서 모집 공고와 신청 절차를 확인해 주세요. 파트너십 제안만으로 공연장 사용 일정이 확보되지는 않습니다."},{"question":"구체적인 예산이나 일정이 정해지지 않았습니다.","answer":"현재 검토 중인 범위와 협의가 필요한 내용을 본문에 적어 주세요. 확인되지 않은 금액이나 일정을 확정해 작성할 필요는 없습니다."}]},{"type":"links","title":"분야 확인과 문의","items":[{"label":"공식 파트너십 안내","href":"https://www.sejongpac.or.kr/portal/main/contents.do?menuNo=200512"},{"label":"파트너십 전화 02-399-1722","href":"tel:02-399-1722"},{"label":"대관 절차","href":"/rental/process"}]}],"form":{"kind":"partnership","title":"협력·협찬 제안","description":"기관 소개, 협력 목적, 희망 분야와 일정을 작성해 주세요."},"sources":[{"label":"공식 파트너십 분야·문의","url":"https://www.sejongpac.or.kr/portal/main/contents.do?menuNo=200512"}]}'::jsonb,true) where id='/about/partners/apply' and payload->'completion' is distinct from '{"path":"/about/partners/apply","title":"협력·협찬 제안","summary":"기관 소개와 협력 목적, 대상과 일정을 정리해 제안해 주세요.","sections":[{"type":"prose","title":"함께할 내용을 알려주세요","paragraphs":["기업·기관·단체가 제안하는 협력의 목적과 실행 방식을 적어 주세요. 예술단, 공간, 콘텐츠, 문화공헌 중 관심 분야를 함께 작성하면 제안의 방향을 이해하는 데 도움이 됩니다.","이 신청은 제안 내용을 전달하기 위한 접수입니다. 접수 후 구체적인 사업 조건을 검토하고 협의하게 되며, 공연·공간 사용이나 협찬 권리가 확정되는 것은 아닙니다."]},{"type":"table","title":"제안서에 담으면 좋은 내용","columns":["항목","작성 안내"],"rows":[["제안 주체","기업·기관명, 사업 분야, 담당자와 회신 연락처"],["목적과 대상","협력하려는 이유, 관심 공연·예술단·공간 또는 참여 대상"],["실행 내용","운영 방식, 콘텐츠 구성, 각 기관이 맡을 역할"],["일정과 자원","희망 기간, 지원 가능한 현금·현물·인력 등 자원"],["기대 효과","관객·시민·예술가에게 제공할 경험과 제안 기관의 목표"]]},{"type":"faq","title":"접수 전 확인","items":[{"question":"공간을 빌리려는 경우에도 여기에 접수하나요?","answer":"공간 대관을 목적으로 하는 신청은 대관안내에서 모집 공고와 신청 절차를 확인해 주세요. 파트너십 제안만으로 공연장 사용 일정이 확보되지는 않습니다."},{"question":"구체적인 예산이나 일정이 정해지지 않았습니다.","answer":"현재 검토 중인 범위와 협의가 필요한 내용을 본문에 적어 주세요. 확인되지 않은 금액이나 일정을 확정해 작성할 필요는 없습니다."}]},{"type":"links","title":"분야 확인과 문의","items":[{"label":"공식 파트너십 안내","href":"https://www.sejongpac.or.kr/portal/main/contents.do?menuNo=200512"},{"label":"파트너십 전화 02-399-1722","href":"tel:02-399-1722"},{"label":"대관 절차","href":"/rental/process"}]}],"form":{"kind":"partnership","title":"협력·협찬 제안","description":"기관 소개, 협력 목적, 희망 분야와 일정을 작성해 주세요."},"sources":[{"label":"공식 파트너십 분야·문의","url":"https://www.sejongpac.or.kr/portal/main/contents.do?menuNo=200512"}]}'::jsonb;
update public.sejong_pages set payload=jsonb_set(payload,'{completion}','{"path":"/english","title":"Visit Sejong Center","summary":"Find performances, plan your journey and check ticket information for your visit to central Seoul.","sections":[{"type":"facts","title":"Before you travel","items":[{"label":"Address","value":"175 Sejong-daero, Jongno-gu, Seoul 03172, Republic of Korea"},{"label":"Ticket enquiries","value":"+82 2 399 1000 · 09:00–20:00"},{"label":"Main venues","value":"Sejong Grand Theater, Sejong M Theater, Sejong S Theater and Sejong Chamber Hall"}]},{"type":"table","title":"Arriving by subway","columns":["Line","Station","Walking route"],"rows":[["5","Gwanghwamun","Exits 1, 7 or 8; approximately 200 metres toward Gwanghwamun"],["3","Gyeongbokgung","Exit 6; walk toward Sejong-daero"],["1","Jonggak","Exit 1; approximately 350 metres toward Gwanghwamun"]],"note":"Routes follow the official visitor guide. Check current station access and transport information before travelling."},{"type":"timeline","title":"Plan your performance visit","items":[{"date":"1","title":"Choose a performance","body":"Check the date, time, venue, age restrictions and language information on the individual listing."},{"date":"2","title":"Book through the official service","body":"The official English booking guide describes email verification, date and seat selection, and payment. Online booking usually closes two hours before the performance; exceptions apply."},{"date":"3","title":"Check collection and cancellation rules","body":"Use the instructions supplied with your confirmed booking. An enquiry or saved request does not issue a ticket."}]},{"type":"prose","title":"Accessibility and assistance","paragraphs":["The official accessibility guide describes tactile guidance, assistance call buttons, wheelchair lifts and elevators. Contact the centre before your visit to confirm a suitable entrance and assistance for your venue.","For current ticket availability and confirmed boo