update public.sejong_pages set payload=jsonb_set(payload,'{completion}','{"path":"/news/events/winners","title":"당첨자 발표","summary":"공식 당첨 발표문과 안내 절차를 확인하세요. 개인별 명단은 원문에서 확인할 수 있습니다.","sections":[{"type":"cards","title":"최근 발표","searchable":true,"items":[{"id":"winner-50219","title":"〈한스 짐머 영화음악 콘서트 2026〉 세종S멤버십 기대평 이벤트 당첨자 발표","href":"https://www.sejongpac.or.kr/portal/bbs/B0000012/view.do?menuNo=200443&nttId=50219&pageIndex=1","date":"2026-10-23","meta":"이벤트 기간 2026.10.14–10.21","status":"발표"},{"id":"winner-50209","title":"SJF at the Theater 〈Diana Krall〉 세종S멤버십 기대평 이벤트 당첨자 발표","href":"https://www.sejongpac.or.kr/portal/bbs/B0000012/view.do?menuNo=200443&nttId=50209&pageIndex=1","date":"2026-10-19","meta":"이벤트 기간 2026.10.08–10.15","status":"발표"},{"id":"winner-50201","title":"2026 누구나 클래식 with 국립심포니오케스트라 이벤트 당첨자 발표","href":"https://www.sejongpac.or.kr/portal/bbs/B0000012/view.do?menuNo=200443&nttId=50201&pageIndex=1","date":"2026-10-12","meta":"이벤트 기간 2026.09.08–10.06","status":"발표"}]},{"type":"faq","title":"발표 확인 안내","items":[{"question":"이름과 연락처는 어디서 확인하나요?","answer":"해당 이벤트의 공식 발표문에서 확인하세요. 이 화면에는 당첨자의 이름이나 연락처를 복제하지 않습니다."},{"question":"당첨 안내를 받지 못했다면?","answer":"한스 짐머 이벤트 발표문은 회원정보상의 휴대전화로 안내한다고 명시합니다. 회원정보를 확인한 뒤 해당 발표문에 기재된 담당 부서로 문의해 주세요. 안내 방식은 행사마다 다를 수 있습니다."}]}],"sources":[{"label":"공식 당첨자 발표 목록","url":"https://www.sejongpac.or.kr/portal/bbs/B0000012/list.do?menuNo=200443"},{"label":"한스 짐머 이벤트 발표문","url":"https://www.sejongpac.or.kr/portal/bbs/B0000012/view.do?menuNo=200443&nttId=50219&pageIndex=1"}]}'::jsonb,true) where id='/news/events/winners' and payload->'completion' is distinct from '{"path":"/news/events/winners","title":"당첨자 발표","summary":"공식 당첨 발표문과 안내 절차를 확인하세요. 개인별 명단은 원문에서 확인할 수 있습니다.","sections":[{"type":"cards","title":"최근 발표","searchable":true,"items":[{"id":"winner-50219","title":"〈한스 짐머 영화음악 콘서트 2026〉 세종S멤버십 기대평 이벤트 당첨자 발표","href":"https://www.sejongpac.or.kr/portal/bbs/B0000012/view.do?menuNo=200443&nttId=50219&pageIndex=1","date":"2026