update public.sejong_pages set payload=jsonb_set(payload,'{completion}','{"path":"/news/goods","title":"세종굿즈","summary":"공식 굿즈 목록에서 확인한 상품을 살펴보고 구매 요청할 상품을 장바구니에 담으세요.","special":"goods","sections":[{"type":"facts","title":"구매 요청 전 확인","items":[{"label":"상품·가격 확인","value":"2026.10.23 세종문화회관 공식 굿즈 소개 기준"},{"label":"재고·옵션","value":"실시간 확인 불가 · 요청 후 별도 확인 필요"},{"label":"접수 범위","value":"미결제 구매 요청 저장"}]},{"type":"prose","title":"선택부터 구매 요청까지","paragraphs":["상품을 장바구니에 담아 수량과 표시 금액을 확인할 수 있습니다. 제출하면 웹사이트 운영자에게 구매 요청이 접수됩니다. 결제, 재고 확보, 배송 확정은 이루어지지 않습니다.","표시 가격은 공식 소개 페이지의 확인 당시 금액입니다. 최종 판매 가격, 선택 가능한 옵션과 수령 방법은 실제 판매처 확인이 필요합니다."]},{"type":"links","title":"상품·요청 확인","items":[{"label":"장바구니","href":"/news/goods/cart"},{"label":"내 구매 요청","href":"/news/goods/orders"},{"label":"공식 전체 굿즈 목록","href":"https://www.sejongpac.or.kr/portal/goods/store/userList.do?menuNo=200660"}]}],"sources":[{"label":"공식 굿즈 소개 · 2026-10-23 가격 확인","url":"https://www.sejongpac.or.kr/portal/goods/store/userList.do?menuNo=200660"}]}'::jsonb,true) where id='/news/goods' and payload->'completion' is distinct from '{"path":"/news/goods","title":"세종굿즈","summary":"공식 굿즈 목록에서 확인한 상품을 살펴보고 구매 요청할 상품을 장바구니에 담으세요.","special":"goods","sections":[{"type":"facts","title":"구매 요청 전 확인","items":[{"label":"상품·가격 확인","value":"2026.10.23 세종문화회관 공식 굿즈 소개 기준"},{"label":"재고·옵션","value":"실시간 확인 불가 · 요청 후 별도 확인 필요"},{"label":"접수 범위","value":"미결제 구매 요청 저장"}]},{"type":"prose","title":"선택부터 구매 요청까지","paragraphs":["상품을 장바구니에 담아 수량과 표시 금액을 확인할 수 있습니다. 제출하면 웹사이트 운영자에게 구매 요청이 접수됩니다. 결제, 재고 확보, 배송 확정은 이루어지지 않습니다.","표시 가격은 공식 소개 페이지의 확인 당시 금액입니다. 최종 판매 가격, 선택 가능한 옵션과 수령 방법은 실제 판매처 확인이 필요합니다."]},{"type":"links","title":"상품·요청 확인","items":[{"label":"장바구니","href":"/news/goods/cart"},{"label":"내 구매 요청","href":"/news/goods/orders"},{"label":"공식 전체 굿즈 목록","href":"https://www.sejongpac.or.kr/portal/goods/store/userList.do?menuNo=200660"}]}],"sources":[{"label":"공식 굿즈 소개 · 2026-10-23 가격 확인","url":"https://www.sejongpac.or.kr/portal/goods/st