update public.sejong_pages set payload=jsonb_set(payload,'{completion}','{"path":"/news/goods/cart","title":"장바구니","special":"cart","summary":"담은 상품과 수량을 확인하고 미결제 구매 요청을 제출하세요.","sections":[{"type":"prose","title":"제출 전 확인","paragraphs":["상품의 표시 가격과 수량으로 요청 금액을 계산합니다. 재고, 옵션, 배송비와 최종 판매 금액은 확인되지 않았습니다.","구매 요청을 제출해도 대금이 청구되지 않으며 상품 확보나 배송이 확정되지 않습니다. 저장한 요청의 접수 상태는 내 구매 요청에서 확인할 수 있습니다."]},{"type":"links","title":"계속 이용하기","items":[{"label":"굿즈 더 살펴보기","href":"/news/goods"},{"label":"내 구매 요청 확인","href":"/news/goods/orders"}]}],"sources":[{"label":"상품과 표시 가격의 공식 출처","url":"https://www.sejongpac.or.kr/portal/goods/store/userList.do?menuNo=200660"}],"form":{"kind":"order","title":"구매 요청"}}'::jsonb,true) where id='/news/goods/cart' and payload->'completion' is distinct from '{"path":"/news/goods/cart","title":"장바구니","special":"cart","summary":"담은 상품과 수량을 확인하고 미결제 구매 요청을 제출하세요.","sections":[{"type":"prose","title":"제출 전 확인","paragraphs":["상품의 표시 가격과 수량으로 요청 금액을 계산합니다. 재고, 옵션, 배송비와 최종 판매 금액은 확인되지 않았습니다.","구매 요청을 제출해도 대금이 청구되지 않으며 상품 확보나 배송이 확정되지 않습니다. 저장한 요청의 접수 상태는 내 구매 요청에서 확인할 수 있습니다."]},{"type":"links","title":"계속 이용하기","items":[{"label":"굿즈 더 살펴보기","href":"/news/goods"},{"label":"내 구매 요청 확인","href":"/news/goods/orders"}]}],"sources":[{"label":"상품과 표시 가격의 공식 출처","url":"https://www.sejongpac.or.kr/portal/goods/store/userList.do?menuNo=200660"}],"form":{"kind":"order","title":"구매 요청"}}'::jsonb;
update public.sejong_pages set payload=jsonb_set(payload,'{completion}','{"path":"/news/goods/orders","title":"내 구매 요청","special":"orders","summary":"제출한 상품과 수량, 미결제 구매 요청의 상태를 확인하세요.","sections":[{"type":"faq","title":"구매 요청 상태 안내","items":[{"question":"접수는 무엇을 뜻하나요?","answer":"상품과 수량, 연락 정보가 웹사이트 운영자에게 전달된 상태입니다. 결제가 완료되거나 공식 판매처 주문번호가 발급된 상태를 뜻하지 않습니다."},{"question":"재고가 확보된 건가요?","answer":"재고를 확보하지 않습니다. 실제 판매 여부, 옵션과 수령 방법은 판매처 확인이 필요합니다."},{"question":"공식 매장에서 구매한 내역도 보이나요?","answer":"이 화면에는 장바구니에서 제출한 구매 요청을 표시합니다. 공식 매장이나 외부 판매처의 결제·구매 내역은 해당 판매처에서 확인하세요."}]},{"type":"links","title":"굿즈 이용","items":[{"label":"굿즈 목록","href":"/news/goods"},{"label":"장바구니","href":"/news/goods/cart"}]}],"sources":[{"label":"세종문화회관 공식 굿즈 소개","url":"https://www.sejongpac.or.kr/portal/goods/store/userList.do?menuNo=200660"}]}'::jsonb,true) where id='/news/goods/orders' and payload->'completion' is distinct from '{"path":"/news/goods/orders","title":"내 구매 요청","special":"orders","summary":"제출한 상품과 수량, 미결제 구매 요청의 상태를 확인하세요.","sections":[{"type":"faq","title":"구매 요청 상태 안내","items":[{"question":"접수는 무엇을 뜻하나요?","answer":"상품과 수량, 연락 정보가 웹사이트 운영자에게 전달된 상태입니다. 결제가 완료되거나 공식 판매처 주문번호가 발급된 상태를 뜻하지 않습니다."},{"question":"재고가 확보된 건가요?","answer":"재고를 확보하지 않습니다. 실제 판매 여부, 옵션과 수령 방법은 판매처 확인이 필요합니다."},{"question":"공식 매장에서 구매한 내역도 보이나요?","answer":"이 화면에는 장바구니에서 제출한 구매 요청을 표시합니다. 공식 매장이나 외부 판매처의 결제·구매 내역은 해당 판매처에서 확인하세요."}]},{"type":"links","title":"굿즈 이용","items":[{"label":"굿즈 목록","href":"/news/goods"},{"label":"장바구니","href":"/news/goods/cart"}]}],"sources":[{"label":"세종문화회관 공식 굿즈 소개","url":"https://www.sejongpac.or.kr/portal/goods/store/userList.do?menuNo=200660"}]}'::jsonb;
