update public.sejong_pages set payload=jsonb_set(payload,'{completion}','{"path":"/news/membership/benefits","title":"멤버십 혜택","summary":"공연 할인과 선예매, 초대 및 제휴 혜택의 적용 조건을 확인하세요.","sections":[{"type":"table","title":"공식 등급별 주요 혜택","columns":["등급","공연·전시 할인","아카데미","초대"],"rows":[["웰컴","비정기 할인 쿠폰","별도 정률 할인 안내 없음","별도 초대 횟수 안내 없음"],["스타트","최대 20% · 1인 2매","5%","최대 1회"],["스페셜","최대 30% · 1인 4매","10%","최대 2회"],["시그니처","최대 35% · 1인 4매","10%","최대 3회"]],"note":"모든 등급에 비정기 할인 쿠폰·예매수수료 면제·제휴 혜택이 안내되어 있습니다. 선예매는 스타트 이상입니다. 혜택은 1년 단위이며 일부 공연·전시는 할인율과 매수가 다릅니다."},{"type":"faq","title":"제휴 혜택 이용 조건","items":[{"question":"제휴 매장에서 무엇을 제시하나요?","answer":"공식 홈페이지 회원 로그인 화면을 이용 전에 제시해야 합니다. 티켓 소지자 혜택은 당일 티켓에 한해 예매내역이나 실물 티켓을 미리 제시합니다."},{"question":"다른 할인과 함께 쓸 수 있나요?","answer":"공식 안내는 회원 본인 1회 또는 테이블당 1회 적용, 다른 할인과 중복 불가를 명시합니다. 일부 품목이 제외될 수 있으므로 매장별 조건을 확인하세요."}]},{"type":"links","title":"상세 조건 확인","items":[{"label":"공식 제휴업체 혜택","href":"https://www.sejongpac.or.kr/portal/main/contents.do?menuNo=200438"},{"label":"등급 조건 확인","href":"/news/membership"},{"label":"가입 안내 및 문의","href":"/news/membership/join"}]}],"sources":[{"label":"공식 등급별 혜택","url":"https://www.sejongpac.or.kr/portal/main/contents.do?menuNo=200437"},{"label":"공식 제휴 이용 조건","url":"https://www.sejongpac.or.kr/portal/main/contents.do?menuNo=200438"}]}'::jsonb,true) where id='/news/membership/benefits' and payload->'completion' is distinct from '{"path":"/news/membership/benefits","title":"멤버십 혜택","summary":"공연 할인과 선예매, 초대 및 제휴 혜택의 적용 조건을 확인하세요.","sections":[{"type":"table","title":"공식 등급별 주요 혜택","columns":["등급","공연·전시 할인","아카데미","초대"],"rows":[["웰컴","비정기 할인 쿠폰","별도 정률 할인 안내 없음","별도 초대 횟수 안내 없음"],["스타트","최대 20% · 1인 2매","5%","최대 1회"],["스페셜","최대 30% · 1인 4매","10%","최대 2회"],["시그니처","최대 35% · 1인 4매","10%","최대 3회"]],"note":"모든 등급에 비정기 할인 쿠폰·예매수수료 면제·제휴 혜택이 안내되어 있습니다. 선예매는 스타트 이상입니다. 혜택은 1년 단위이며 일부 공연·전시는 할인율과 매수가 다릅니다."},{"type":"faq","title":"제휴 혜택 이용 조건","items":[{"question":"제휴 매장에서 무엇을 제시하나요?","answer":"공식 홈페이지 회원 로그인 화면을 이용 전에 제시해야