.do?menuNo=200299&nttId=50002&pageIndex=1","date":"2026-04-28","category":"2026년 5월호"}],"emptyMessage":"일치하는 호가 없습니다. 연도나 월을 바꾸어 검색해 주세요."},{"type":"prose","title":"발행 정보 읽는 법","paragraphs":["날짜는 공식 목록의 게시일입니다. 발행월보다 앞선 날짜에 게시된 호가 있습니다.","공식 10월호와 8월호의 발행년도 필드에는 2027년이 표시되지만, 게시물 제목과 본문 이미지는 2026년으로 표시됩니다. 이 목록은 제목과 본문을 기준으로 정리했으며 원문을 함께 연결했습니다."]},{"type":"links","title":"다른 발행본과 구독","items":[{"label":"공식 전체 아카이브","href":"https://www.sejongpac.or.kr/portal/bbs/B0000056/list.do?menuNo=200299"},{"label":"구독 안내","href":"/news/newsletter"}]}],"sources":[{"label":"공식 뉴스레터 목록 · 2026-10-23 확인","url":"https://www.sejongpac.or.kr/portal/bbs/B0000056/list.do?menuNo=200299"},{"label":"10월호 제목·발행년도 원문","url":"https://www.sejongpac.or.kr/portal/bbs/B0000056/view.do?menuNo=200299&nttId=50179&pageIndex=1"},{"label":"8월호 제목·발행년도 원문","url":"https://www.sejongpac.or.kr/portal/bbs/B0000056/view.do?menuNo=200299&nttId=50102&pageIndex=1"}]}'::jsonb;
update public.sejong_pages set payload=jsonb_set(payload,'{completion}','{"path":"/news/notices/recruit/apply","title":"채용 지원 안내","summary":"확인된 모집 공고와 접수 상태를 확인하세요. 종료된 공고에는 지원서를 제출할 수 없습니다.","sections":[{"type":"table","title":"최근 확인한 채용 안내","columns":["공고","접수 상태","확인할 내용"],"rows":[["공연장 안내원 51기","접수 종료 · 2026.10.15 18:00","공식 공고의 합격자 개별 안내 및 교육 일정"],["2027년 상반기 직원 채용 일정 사전 안내","본 채용 공고 전 사전 안내","향후 확정 공고에서 직무·인원·접수 기간 확인"]],"note":"2026.10.23 확인 기준입니다. 사전 안내에 적힌 일정은 변경될 수 있으며 확정 모집 일정으로 사용하지 않습니다."},{"type":"prose","title":"현재 지원서를 받지 않습니다","paragraphs":["안내원 51기는 접수 마감일이 지났고, 2027년 상반기 직원 채용 문서는 본 모집 공고 전의 사전 안내입니다. 현재 이 페이지와 연결할 수 있는 접수 중 모집을 확인하지 못해 지원서 제출을 닫았습니다.","새 공고가 게시되면 해당 공고에 명시된 접수 기간, 자격, 제출 서류와 접수처를 확인해 주세요."]},{"type":"downloads","title":"종료 공고의 참고 자료","items":[{"label":"공연장 안내원 51기 지원서 양식 HWPX","href":"https://www.sejongpac.or.kr/portal/cmmn/file/fileDown.do?atchFileId=0aac3e2ec36746cca915cf651b6e5189&bbsId=B0000065&fileSn=1","description":"공식 종료 공고의 첨부 양식 · 신규 공고에 재사용하기 전에 최신 양식 확인"}]},{"type":"links","title":"공식 공고 확인","items":[{"label":"공연장 안내원 51기 공고 원문","href":"https://www.sejongpac.or.kr/portal/bbs/B0000065/view.do?menuNo=200571&nttId=50182&pageIndex=1"},{"label":"2027년 상반기 채용 사전 안내","href":"https://www.sejongpac.or.kr/portal/bbs/B0000065/view.do?menuNo=200571&nttId=50204&pageIndex=1"},{"label":"공식 채용공고 전체","href":"https://www.sejongpac.or.kr/portal/bbs/B0000065/list.do?menuNo=200571"}]}],"form":{"kind":"recruitment","title":"채용 지원서","entityId":"recruitment-unavailable","closed":true,"closedReason":"공연장 안내원 51기 접수는 2026.10.15 18:00 종료됐습니다. 2027년 상반기 채용은 사전 안내 단계로, 현재 연결할 수 있는 접수 중 공고가 없습니다."},"sources":[{"label":"안내원 51기 접수 기간과 첨부 양식","url":"https://www.sejongpac.or.kr/portal/bbs/B0000065/view.do?menuNo=200571&nttId=50182&pageIndex=1"},{"label":"2027년 상반기 채용 사전 안내","url":"https://www.sejongpac.or.kr/portal/bbs/B0000065/view.do?menuNo=200571&nttId=50204&pageIndex=1"},{"label":"공식 채용공고 목록","url":"https://www.sejongpac.or.kr/portal/bbs/B0000065/list.do?menuNo=200571"}]}'::jsonb,true) where id='/news/notices/recruit/apply' and payload->'completion' is distinct from '{"path":"/news/notices/recruit/apply","title":"채용 지원 안내","summary":"확인된 모집 공고와 접수 상태를 확인하세요. 종료된 공고에는 지원서를 제출할 수 없습니다.","sections":[{"type":"table","title":"최근 확인한 채용 안내","columns":["공고","접수 상태","확인할 내용"],"rows":[["공연장 안내원 51기","접수 종료 · 2026.10.15 18:00","공식 공고의 합격자 개별 안내 및 교육 일정"],["2027년 상반기 직원 채용 일정 사전 안내","본 채용 공고 전 사전 안내","향후 확정 공고에서 직무·인원·접수 기간 확인"]],"note":"2026.10.23 확인 기준입니다. 사전 안내에 적힌 일정은 변경될 수 있으며 확정 모집 일정으로 사용하지 않습니다."},{"type":"prose","title":"현재 지원서를 받지 않습니다","paragraphs":["안내원 51기는 접수 마감일이 지났고, 2027년 상반기 직원 채용 문서는 본 모집 공고 전의 사전 안내입니다. 현재 이 페이지와 연결할 수 있는 접수 중 모집을 확인하지 못해 지원서 제출을 닫았습니다.","새 공고가 게시되면 해당 공고에 명시된 접수 기간, 자격, 제출 서류와 접수처를 확인해 주세요."]},{"type":"downloads","title":"종료 공고의 참고 자료","items":[{"label":"공연장 안내원 51기 지원서 양식 HWPX","href":"https://www.sejongpac.or.kr/portal/cmmn/file/fileDown.do?atchFileId=0aac3e2ec36746cca915cf651b6e5189&bbsId=B0000065&fileSn=1","description":"공식 종료 공고의 첨부 양식 · 신규 공고에 재사용하기 전에 최신 양식 확인"}]},{"type":"links","title":"공식 공고 확인","items":[{"label":"공연장 안내원 51기 공고 원문","href":"https://www.sejongpac.or.kr/portal/bbs/B0000065/view.do?menuNo=200571&nttId=50182&pageIndex=1"},{"label":"2027년 상반기 채용 사전 안내","href":"https://www.sejongpac.or.kr/portal/bbs/B0000065/view.do?menuNo=200571&nttId=50204&pageIndex=1"},{"label":"공식 채용공고 전체","href":"https://www.sejongpac.or.kr/portal/bbs/B0000065/list.do?menuNo=200571"}]}],"form":{"kind":"recruitment","title":"채용 지원서","entityId":"recruitment-unavailable","closed":true,"closedReason":"공연장 안내원 51기 접수는 2026.10.15 18:00 종료됐습니다. 2027년 상반기 채용은 사전 안내 단계로, 현재 연결할 수 있는 접수 중 공고가 없습니다."},"sources":[{"label":"안내원 51기 접수 기간과 첨부 양식","url":"https://www.sejongpac.or.kr/portal/bbs/B0000065/view.do?menuNo=200571&nttId=50182&pageIndex=1"},{"label":"2027년 상반기 채용 사전 안내","url":"https://www.sejongpac.or.kr/portal/bbs/B0000065/view.do?menuNo=200571&nttId=50204&pageIndex=1"},{"label":"공식 채용공고 목록","