update public.sejong_pages set payload=jsonb_set(payload,'{completion}','{"path":"/policy/email","title":"이메일 무단수집 거부","summary":"게시된 연락처의 용도를 존중해 주세요. 공식 기관의 이메일 무단수집 거부 고지를 안내합니다.","sections":[{"type":"prose","title":"공식 기관의 고지","paragraphs":["세종문화회관은 홈페이지에 게시한 이메일 주소를 수집 프로그램이나 기술적 장치로 무단 수집하는 것을 거부한다고 고지합니다. 원문은 위반 시 관련 법에 따른 처벌 가능성을 안내합니다.","기관의 공식 고지 게시일은 2015년 10월 12일입니다. 전체 문구는 아래 공식 원문에서 확인할 수 있습니다."]},{"type":"faq","title":"연락처 이용 안내","items":[{"question":"게시된 담당자 이메일로 무엇이든 보내도 되나요?","answer":"해당 연락처에 안내된 업무와 접수 목적을 먼저 확인해 주세요. 특히 채용 서류 접수 전용 주소처럼 사용 기간과 목적이 제한된 주소가 있습니다."},{"question":"뉴스레터 신청도 무단수집에 해당하나요?","answer":"본인이 수신 안내를 확인하고 구독을 신청하는 절차와 게시된 타인의 주소를 무단으로 수집하는 행위는 구분됩니다. 구독 신청 화면의 수집·이용 내용을 확인해 주세요."}]},{"type":"links","title":"고지와 문의","items":[{"label":"공식 이메일 무단수집 거부 고지","href":"https://www.sejongpac.or.kr/portal/main/contents.do?menuNo=200150"},{"label":"고객 문의 작성","href":"/visit/support/inquiry"},{"label":"뉴스레터 구독 안내","href":"/news/newsletter"}]}],"sources":[{"label":"세종문화회관 이메일 무단수집 거부","url":"https://www.sejongpac.or.kr/portal/main/contents.do?menuNo=200150"},{"label":"채용 전용 이메일의 목적·기간 안내","url":"https://www.sejongpac.or.kr/portal/bbs/B0000065/view.do?menuNo=200571&nttId=50182&pageIndex=1"}]}'::jsonb,true) where id='/policy/email' and payload->'completion' is distinct from '{"path":"/policy/email","title":"이메일 무단수집 거부","summary":"게시된 연락처의 용도를 존중해 주세요. 공식 기관의 이메일 무단수집 거부 고지를 안내합니다.","sections":[{"type":"prose","title":"공식 기관의 고지","paragraphs":["세종문화회관은 홈페이지에 게시한 이메일 주소를 수집 프로그램이나 기술적 장치로 무단 수집하는 것을 거부한다고 고지합니다. 원문은 위반 시 관련 법에 따른 처벌 가능성을 안내합니다.","기관의 공식 고지 게시일은 2015년 10월 12일입니다. 전체 문구는 아래 공식 원문에서 확인할 수 있습니다."]},{"type":"faq","title":"연락처 이용 안내","items":[{"question":"게시된 담당자 이메일로 무엇이든 보내도 되나요?","answer":"해당 연락처에 안내된 업무와 접수 목적을 먼저 확인해 주세요. 특히 채용 서류 접수 전용 주소처럼 사용 기간과 목적이 제한된 주소가 있습니다."},{"question":"뉴스레터 신청도 무단수집에 해당하나요?","answer":"본인이 수신 안내를 확인하고 구독을 신청하는 절차와 게시된 타인의 주소를 무단으로 수집하는 행위는 구분됩니다. 구독 신청 화면의 수집·이용 내용을 확인해 주세요."}]},{"type":"links","title":"고지와 문의","items":[{"label":"공식 이메일 무단수집 거부 고지","href":"https://www.sejongpac.or.kr/portal/main/contents.do?menuNo=200150"},{"label":"고객 문의 작성","href":"/visit/support/inquiry"},{"label":"뉴스레터 구독 안내","href":"/news/newsletter"}]}],"sources":[{"label":"세종문화회관 이메일 무단수집 거부","url":"https://www.sejongpac.or.kr/portal/main/contents.do?menuNo=200150"},{"label":"채용 전용 이메일의 목적·기간 안내","url":"https://www.sejongpac.or.kr/portal/bbs/B0000065/view.do?menuNo=200571&nttId=50182&pageIndex=1"}]}'::jsonb;
update public.sejong_pages set payload=jsonb_set(payload,'{completion}','{"path":"/policy/privacy","title":"개인정보 안내","summary":"신청 정보의 처리 범위와 세종문화회관 공식 개인정보처리방침을 확인하세요.","sections":[{"type":"prose","title":"신청 정보를 제출하기 전에","paragraphs":["신청·문의·구매 요청의 접수 대상은 웹사이트 운영자입니다. 기관의 공식 회원·예매 시스템 등록이나 담당 기관에 대한 전달은 별도 절차입니다.","제출 전 각 양식에 표시된 수집 항목, 이용 목적, 보유 기간과 동의 내용을 확인해 주세요. 아래의 세종문화회관 처리방침 요약은 기관이 처리하는 정보에 대한 안내이며, 신청 양식의 별도 수집·이용 동의를 대신하지 않습니다."]},{"type":"facts","title":"공식 기관 처리방침 요약","items":[{"label":"방침의 주체","value":"재단법인 세종문화회관"},{"label":"현행 원문의 시행일","value":"2026년 7월 1일"},{"label":"포함하는 내용","value":"처리 목적·항목·보유 기간, 제3자 제공, 위탁, 파기, 권리 행사와 안전성 확보조치"},{"label":"정보주체의 권리","value":"열람·정정·삭제·처리정지 등을 기관에 요구할 수 있으며 법령에 따른 제한이 있을 수 있음"}]},{"type":"prose","title":"기관 정보의 확인과 권리 행사","paragraphs":["공식 원문은 회원정보, 채용지원자 정보 등 개인정보파일별 처리 범위를 구분합니다. 불필요해진 정보는 파기하고, 법령상 보존 의무가 있는 정보는 구분해 보관한다고 안내합니다.","공식 기관에 보유된 정보의 열람 등은 원문의 담당 부서와 서식을 이용하세요. 아래 서식은 세종문화회관에 권리를 행사할 때 사용하는 공식 자료입니다. 이 화면은 원문을 대체하지 않습니다."]},{"type":"downloads","title":"공식 권리 행사 서식","items":[{"label":"개인정보 열람 요구서","href":"https://www.sejongpac.or.kr/portal/cmmn/file/fileDown.do?atchFileId=507bc7cd887f4c33bea1a0f02b098151&fileSn=1"},{"label":"대리인 위임장","href":"https://www.sejongpac.or.kr/portal/cmmn/file/fileDown.do?atchFileId=507bc7cd887f4c33bea1a0f02b098151&fileSn=2"}]},{"type":"links","title":"적용 범위와 전체 원문","items":[{"label":"세종문화회관 개인정보처리방침 전체","href":"https://www.sejongpac.or.kr/portal/main/contents.do?menuNo=200148","description":"개인정보파일별 항목·보유 기간, 담당 부서와 이전 방침 확인"},{"label":"신청 정보 문의","href":"/visit/support/inquiry"},{"label":"이용약관 안내","href":"/policy/terms"}]}],"sources":[{"label":"세종문화회관 현행 개인정보처리방침 · 2026.10.23 확인","url":"https://www.sejongpac.or.kr/portal/main/contents.do?menuNo=200148"}]}'::jsonb,true) where id='/policy/privacy' and payload->'completion' is distinct from '{"path":"/policy/privacy","title":"개인정보 안내","summary":"신청 정보의 처리 범위와 세종문화회관 공식 개인정보처리방침을 확인하세요.","sections":[{"type":"prose","title":"신청