update public.sejong_pages set payload=jsonb_set(payload,'{completion}','{"path":"/policy/terms","title":"이용약관 안내","summary":"신청·구매 요청의 처리 범위와 공식 회원 서비스의 이용 조건을 확인하세요.","sections":[{"type":"prose","title":"접수 결과의 의미","paragraphs":["문의·신청·구매 요청을 제출하면 웹사이트 운영자에게 접수 기록이 생성됩니다. 기관의 공식 접수처에 제출이 필요한 업무는 해당 공고의 절차를 확인하세요.","공식 회원 자격, 공연 예매, 결제와 티켓 발행은 각 공식 서비스의 절차 및 이용 조건에 따라 확인해야 합니다. 굿즈 구매 요청은 미결제 상태로 접수되며 판매·재고·배송을 확정하지 않습니다."]},{"type":"table","title":"공식 회원 약관의 주요 항목","columns":["구분","원문에서 확인할 내용"],"rows":[["서비스 이용계약","공식 가입 양식 작성과 가입 완료, 가입 제한 및 취소 사유"],["회원과 서비스","회원 자격·혜택·이용 조건 및 관련 개별 규정"],["이용자의 책임","타인 명의·정보 도용, 허위 정보와 서비스 방해 등에 관한 제한"],["공연 주체","기획·공동 주최·대관 공연의 권한과 책임 범위 구분"]]},{"type":"prose","title":"세부 조건은 해당 서비스에서 확인하세요","paragraphs":["공식 약관은 세종문화회관과 공식 회원 간의 권리·의무 및 책임을 다루며, 별도 서비스 규정과 함께 적용된다고 안내합니다. 공연별 판매처, 할인 증빙, 취소·환불 기준은 실제 예매 화면과 해당 공연 공고도 함께 확인하세요.","이 페이지는 핵심 내용을 읽기 쉽게 정리한 요약입니다. 정확한 적용 조항과 개정 내용은 공식 원문을 확인해 주세요."]},{"type":"links","title":"전체 규정과 이용 안내","items":[{"label":"공식 회원 이용약관 전체","href":"https://www.sejongpac.or.kr/portal/main/contents.do?menuNo=200635"},{"label":"예매 안내","href":"/programs/booking-guide"},{"label":"개인정보 안내","href":"/policy/privacy"},{"label":"이용 문의","href":"/visit/support/inquiry"}]}],"sources":[{"label":"세종문화회관 공식 이용약관 · 2026.10.23 확인","url":"https://www.sejongpac.or.kr/portal/main/contents.do?menuNo=200635"}]}'::jsonb,true) where id='/policy/terms' and payload->'completion' is distinct from '{"path":"/policy/terms","title":"이용약관 안내","summary":"신청·구매 요청의 처리 범위와 공식 회원 서비스의 이용 조건을 확인하세요.","sections":[{"type":"prose","title":"접수 결과의 의미","paragraphs":["문의·신청·구매 요청을 제출하면 웹사이트 운영자에게 접수 기록이 생성됩니다. 기관의 공식 접수처에 제출이 필요한 업무는 해당 공고의 절차를 확인하세요.","공식 회원 자격, 공연 예매, 결제와 티켓 발행은 각 공식 서비스의 절차 및 이용 조건에 따라 확인해야 합니다. 굿즈 구매 요청은 미결제 상태로 접수되며 판매·재고·배송을 확정하지 않습니다."]},{"type":"table","title":"공식 회원 약관의 주요 항목","columns":["구분","원문에서 확인할 내용"],"rows":[["서비스 이용계약","공식 가입 양식 작성과 가입 완료, 가입 제한 및 취소 사유"],["회원과 서비스","회원 자격·혜택·이용 조건 및 관련 개별 규정"],["이용자의 책임","타인 명의·정보 도용, 허위 정보와 서비스 방해 등에 관한 제한"],["공연 주체","기획·공동 주최·대관 공연의 권한과 책임 범위 구분"]]},{"type":"prose","title":"세부 조건은 해당 서비스에서 확인하세요","paragraphs":["공식 약관은 세종문화회관과 공식 회원 간의 권리·의무 및 책임을 다루며, 별도 서비스 규정과 함께 적용된다고 안내합니다. 공연별 판매처, 할인 증빙, 취소·환불 기준은 실제 예매 화면과 해당 공연 공고도 함께 확인하세요.","이 페이지는 핵심 내용을 읽기 쉽게 정리한 요약입니다. 정확한 적용 조항과 개정 내용은 공식 원문을 확인해 주세요."]},{"type":"links","title":"전체 규정과 이용 안내","items":[{"label":"공식 회원 이용약관 전체","href":"https://www.sejongpac.or.kr/portal/main/contents.do?menuNo=200635"},{"label":"예매 안내","href":"/programs/booking-guide"},{"label":"개인정보 안내","href":"/policy/privacy"},{"label":"이용 문의","href":"/visit/support/inquiry"}]}],"sources":[{"label":"세종문화회관 공식 이용약관 · 2026.10.23 확인","url":"https://www.sejongpac.or.kr/portal/main/contents.do?menuNo=200635"}]}'::jsonb;
update public.sejong_pages set payload=jsonb_set(payload,'{completion}','{"path":"/programs/booking-guide","title":"예매 안내","summary":"예매 방법과 티켓 수령, 취소·변경 조건을 확인하세요. 공연별 별도 공지가 있으면 해당 안내를 함께 확인해 주세요.","sections":[{"type":"table","title":"예매 채널","columns":["방법","운영시간","이용 안내"],"rows":[["인터넷·모바일","24시간 / 통상 공연 2시간 전 마감","공연·날짜·회차·좌석 선택 후 결제. 일부 공연 비회원 예매 가능"],["전화 02-399-1000","09:00~20:00, 연중무휴","통상 공연 2시간 전까지. 일부 공연 전화예매 제외"],["서비스플라자","10:00~20:00 / 13:00~14:00 미운영","1층 세종라운지 내 방문 예매"]],"note":"세종문화회관 자체 예매 채널의 예매 수수료는 없습니다. 결제수단과 마감은 작품별로 확인하세요."},{"type":"table","title":"티켓 받기","columns":["방법","준비·확인 사항"],"rows":[["현장매표소","예매내역서 또는 실물 신분증, 휴대폰 뒷 4자리. 할인 예매는 증빙자료 지참"],["무인발권기","알림톡의 티켓 QR코드 또는 예매번호·휴대폰 뒷 4자리. 할인 증빙이 필요하면 매표소 이용"],["디지털 티켓","지원 공연에 한해 카카오톡 알림톡으로 발권. 당일 활성화한 QR코드로 입장하며 캡처본은 사용 불가"]],"note":"매표소는 통상 공연 1시간 30분 전, 무인발권기는 2시간 전부터 운영합니다. 공연별 수령 방법·운영시간은 다를 수 있습니다."},{"type":"table","title":"일반 예매 취소 기준","columns":["취소 시점","취소수수료"],"rows":[["관람일 10일 전 자정까지","없음"],["관람일 9일 전~1일 전 17:00","티켓 금액의 10%"],["관람일 전일 17:00 이후~당일","취소·변경·환불 불가"]],"note":"공식 안내는 관람일 3일 전까지 예매한 건을 인터넷 예매 당일 자정까지 취소하면 수수료가 없으며, 2일 전부터는 당일 취소도 수수료가 발생한다고 설명합니다. 상품·예매처별 규정도 확인하세요."},{"type":"faq","title":"변경과 할인 증빙","items":[{"question":"날짜·좌석·결제수단만 바꿀 수 있나요?","answer":"기존 예매를 취소하고 다시 결제해야 합니다. 취소 수수료가 발생하거나 취소 좌석을 다른 사람이 먼저 예매할 수 있습니다."},{"question":"할인 증빙을 가져오지 못하면 어떻게 되나요?","answer":"현장에서 증빙을 확인하지 못하면 정가 기준 차액을 지불해야 합니다. 공연 상세의 대상·증빙·동반인 적용 범위를 확인하세요."}]},{"type":"links","title":"예매·방문 준비","items":[{"label":"프로그램 선택","href":"/programs"},{"label":"방문 순서 확인","href":"/visit/plan"},{"label":"예매 문의","href":"tel:02-399-1000"}]}],"sources":[{"label":"티켓 구입방법","url":"https://www.sejongpac.or.kr/portal/main/contents.do?menuNo=200322"},{"label":"티켓 수령방법","url":"https://www.sejongpac.or.kr/portal/main/contents.do?menuNo=200323"},{"label":"예매 취소·변경 안내","url":"https://www.sejongpac.or.kr/portal/main/contents.do?menuNo=200324"}]}'::jsonb,true) where id='/programs/booking-guide' and payload->'completion' is distinct from '{"path":"/programs/booking-guide","title":"예매 안내","summary":"예매 방법과 티켓 수령, 취소·변경 조건을 확인하세요. 공연별 별도 공지가 있으면 해당 안내를 함께 확인해 주세요.","sections":[{"type":"table","title":"예매 채널","columns":["방법","운영시간","이용 안내"],"rows":[["인터넷·모바일","24시간 / 통상 공연 2시간 전 마감","공연·날짜·회차·좌석 선택 후 결제. 일부 공연 비회원 예매 가능"],["전화 02-399-1000","09:00~20:00, 연중무휴","통상 공연 2시간 전까지. 일부 공연 전화예매 제외"],["서비스플라자","10:00~20:00 / 13:00~14:00 미운영","1층 세종라운지 내 방문 예매"]],"note":"세종문화회관 자체 예매 채널의 예매 수수료는 없습니다. 결제수단과 마감은 작품별로 확인하세요."},{"type":"table","title":"티켓 받기","columns":["방법","준비·확인 사항"],"rows":[["현장매표소","예매내역서 또는 실물 신분증, 휴대폰 뒷 4자리. 할인 예매는 증빙자료 지참"],["무인발권기","알림톡의 티켓 QR코드 또는 예매번호·휴대폰 뒷 4자리. 할인 증빙이 필요하면 매표소 이용"],["디지털 티켓","지원 공연에 한해 카카오톡 알림톡으로 발권. 당일 활성화한 QR코드로 입장하며 캡처본은 사용 불가"]],"note":"매표소는 통상 공연 1시간 30분 전, 무인발권기는 2시간 전부터 운영합니다. 공연별 수령 방법·운영시간은 다를 수 있습니다."},{"type":"table","title":"일반 예매 취소 기준","columns":["취소 시점","취소수수료"],"rows":[["관람일 10일 전 자정까지","없음"],["관람일 9일 전~1일 전 17:00","티켓 금액의 10%"],["관람일 전일 17:00 이후~당일","취소·변경·환불 불가"]],"note":"공식 안내는 관람일 3일 전까지 예매한 건을 인터넷 예매 당일 자정까지 취소하면 수수료가 없으며, 2일 전부터는 당일 취소도 수수료가 발생한다고 설명합니다. 상품·예매처별 규정도 확인하세요."},{"type":"faq","title":"변경과 할인 증빙","items":[{"question":"날짜·좌석·결제수단만 바꿀 수 있나요?","answer":"기존 예매를 취소하고 다시 결제해야 합니다. 취소 수수료가 발생하거나 취소 좌석을 다른 사람이 먼저 예매할 수 있습니다."},{"question":"할인 증빙을 가져오지 못하면 어떻게 되나요?","answer":"현장에서 증빙을 확인하지 못하면 정가 기준 차액을 지불해야 합니다. 공연 상세의 대상·증빙·동반인 적용 범위를 확인하세요."}]},{"type":"links","title":"예매·방문 준비","items":[{"label":"프로그램 선택","href":"/programs"},{"label":"방문 순서 확인","href":"/visit/plan"},{"label":"예매 문의","href":"tel:02-399-1000"}]}],"sources":[{"label":"티켓 구입방법","url":"https://www.sejongpac.or.kr/portal/main/contents.do?menuNo=200322"},{"label":"티켓 수령방법","url":"https://www.sejongpac.or.kr/portal/main/contents.do?menuNo=200323"},{"label":"예매 취소·변경 안내","url":"https://www.sejongpac.or.kr/portal/main/contents.do?menuNo=200324"}]}'::jsonb;
update public.sejong_pages set payload=jsonb_set(payload,'{completion}','{"path":"/programs/education/apply-guide","title":"교육 수강 안내","summary":"예술 감상과 실기 강좌의 일정·커리큘럼을 확인하고 수강을 신청하세요.","sections":[{"type":"prose","title":"세종예술아카데미","paragraphs":["2007년 6월 개원한 시민 예술교육 공간입니다. 점심·저녁 시간을 활용한 클래식·뮤지컬·미술 감상 강좌와 청소년 문화강좌 등을 운영합니다."]},{"type":"timeline","title":"수강 신청 순서","items":[{"date":"강좌 선택","title":"일정과 커리큘럼 확인","body":"대상, 강의 날짜·회차, 강의실, 수강료와 재료비를 강좌 상세에서 확인하세요. ‘진행중’ 표시가 신규 접수 가능을 뜻하는지는 잔여 정원과 별도로 확인해야 합니다."},{"date":"신청","title":"회원 로그인 후 접수","body":"공식 홈페이지 수강신청에는 회원가입이 필요합니다. 공식 FAQ는 개강 약 1개월 전부터 홈페이지·콜센터·현장에서 접수를 안내합니다."},{"date":"수강 전","title":"결제와 준비물 확인","body":"신청 강좌와 수강 확정 여부, 첫 수업 일시·장소를 확인하세요. 재료와 준비물은 강좌마다 다릅니다."}]},{"type":"cards","title":"2026 하반기 운영 강좌","items":[{"id":"course-vocal-2026","title":"뮤지컬 보컬 스테이션","href":"https://www.sejongpac.or.kr/portal/academy/academyProgram/view.do?courseCd=CS102103262790000064&listType=1&menuNo=200560&pageIndex=1&searchYear=2026","meta":"2026.10.14~12.16 · 수요일 · 서클홀","description":"공식 교육 일정에 진행 중인 강좌로 등록되어 있습니다. 회차와 신청 조건은 강좌 상세에서 확인하세요."},{"id":"course-brunch-2026","title":"클래식 브런치","href":"https://www.sejongpac.or.kr/portal/academy/academyProgram/view.do?courseCd=CS102103262030000050&listType=1&menuNo=200560&pageIndex=1&searchYear=2026","meta":"2026.09.09~11.25 · 수요일 · 서클홀","description":"하반기 클래식 감상 강좌입니다. 정규 강좌와 1회권의 신청 조건을 구분해 확인하세요."},{"id":"course-musical-2026","title":"뮤지컬의 탄생: 유럽뮤지컬–역사와 문학의 향연","href":"https://www.sejongpac.or.kr/portal/academy/academyProgram/view.do?courseCd=CS102103262030000049&listType=1&menuNo=200560&pageIndex=1&searchYear=2026","meta":"2026.09.03~11.05 · 목요일 · 서클홀","description":"유럽뮤지컬을 주제로 한 하반기 강좌입니다. 회차별 내용과 잔여 정원을 확인하세요."}]},{"type":"faq","title":"취소·환불과 문의","items":[{"question":"개강 전에 취소하면 환불되나요?","answer":"공식 FAQ는 개강일 전날까지 취소하면 전액 환불을 안내합니다. 재료 준비가 필요한 강좌의 재료비는 강의 시작 4일 전까지 취소해야 반환받을 수 있습니다."},{"question":"수업이 시작된 뒤에는 어떻게 취소하나요?","answer":"콜센터 02-399-1000으로 문의하세요. 강좌 기간·진행 시점과 패키지 할인 여부에 따라 환불액이 달라집니다. 단순 결석이 취소 신청을 대신하지 않습니다."}]}],"form":{"kind":"education","title":"교육 수강 신청","description":"희망 강좌명과 회차, 수강 관련 요청을 입력해 주세요. 강좌별 수강료와 잔여 정원을 확인한 후 신청하세요."},"sources":[{"label":"아카데미 소개","url":"https://www.sejongpac.or.kr/portal/main/contents.do?menuNo=200561"},{"label":"수강 신청·환불 FAQ","url":"https://www.sejongpac.or.kr/portal/bbs/B0000059/list.do?menuNo=200562"},{"label":"2026 공식 교육 일정","url":"https://www.sejongpac.or.kr/portal/academy/academyProgram/list.do?menuNo=200560"}]}'::jsonb,true) where id='/programs/education/apply-guide' and payload->'completion' is distinct from '{"path":"/programs/education/apply-guide","title":"교육 수강 안내","summary":"예술 감상과 실기 강좌의 일정·커리큘럼을 확인하고 수강을 신청하세요.","sections":[{"type":"prose","title":"세종예술아카데미","paragraphs":["2007년 6월 개원한 시민 예술교육 공간입니다. 점심·저녁 시간을 활용한 클래식·뮤지컬·미술 감상 강좌와 청소년 문화강좌 등을 운영합니다."]},{"type":"timeline","title":"수강 신청 순서","items":[{"date":"강좌 선택","title":"일정과 커리큘럼 확인","body":"대상, 강의 날짜·회차, 강의실, 수강료와 재료비를 강좌 상세에서 확인하세요. ‘진행중’ 표시가 신규 접수 가능을 뜻하는지는 잔여 정원과 별도로 확인해야 합니다."},{"date":"신청","title":"회원 로그인 후 접수","body":"공식 홈페이지 수강신청에는 회원가입이 필요합니다. 공식 FAQ는 개강 약 1개월 전부터 홈페이지·콜센터·현장에서 접수를 안내합니다."},{"date":"수강 전","title":"결제와 준비물 확인","body":"신청 강좌와 수강 확정 여부, 첫 수업 일시·장소를 확인하세요. 재료와 준비물은 강좌마다 다릅니다."}]},{"type":"cards","title":"2026 하반기 운영 강좌","items":[{"id":"course-vocal-2026","title":"뮤지컬 보컬 스테이션","href":"https://www.sejongpac.or.kr/portal/academy/academyProgram/view.do?courseCd=CS102103262790000064&listType=1&menuNo=200560&pageIndex=1&searchYear=2026","meta":"2026.10.14~12.16 · 수요일 · 서클홀","description":"공식 교육 일정에 진행 중인 강좌로 등록되어 있습니다. 회차와 신청 조건은 강좌 상세에서 확인하세요."},{"id":"course-brunch-2026","title":"클래식 브런치","href":"https://www.sejongpac.or.kr/portal/academy/academyProgram/view.do?courseCd=CS102103262030000050&listType=1&menuNo=200560&pageIndex=1&searchYear=2026","meta":"2026.09.09~11.25 · 수요일 · 서클홀","description":"하반기 클래식 감상 강좌입니다. 정규 강좌와 1회권의 신청 조건을 구분해 확인하세요."},{"id":"course-musical-2026","title":"뮤지컬의 탄생: 유럽뮤지컬–역사와 문학의 향연","href":"https://www.sejongpac.or.kr/portal/academy/academyProgram/view.do?courseCd=CS102103262030000049&listType=1&menuNo=200560&pageIndex=1&searchYear=2026","meta":"2026.09.03~11.05 · 목요일 · 서클홀","description":"유럽뮤지컬을 주제로 한 하반기 강좌입니다. 회차별 내용과 잔여 정원을 확인하세요."}]},{"type":"faq","title":"취소·환불과 문의","items":[{"question":"개강 전에 취소하면 환불되나요?","answer":"공식 FAQ는 개강일 전날까지 취소하면 전액 환불을 안내합니다. 재료 준비가 필요한 강좌의 재료비는 강의 시작 4일 전까지 취소해야 반환받을 수 있습니다."},{"question":"수업이 시작된 뒤에는 어떻게 취소하나요?","answer":"콜센터 02-399-1000으로 문의하세요. 강좌 기간·진행 시점과 패키지 할인 여부에 따라 환불액이 달라집니다. 단순 결석이 취소 신청을 대신하지 않습니다."}]}],"form":{"kind":"education","title":"교육 수강 신청","description":"희망 강좌명과 회차, 수강 관련 요청을 입력해 주세요. 강좌별 수강료와 잔여 정원을 확인한 후 신청하세요."},"sources":[{"label":"아카데미 소개","url":"https://www.sejongpac.or.kr/portal/main/contents.do?menuNo=200561"},{"label":"수강 신청·환불 FAQ","url":"https://www.sejongpac.or.kr/portal/bbs/B0000059/list.do?menuNo=200562"},{"label":"2026 공식 교육 일정","url":"https://www.sejongpac.or.kr/portal/academy/academyProgram/list.do?menuNo=200560"}]}'::jsonb;
update public.sejong_pages set payload=jsonb_set(payload,'{completion}','{"path":"/programs/history","title":"지난 프로그램","summary":"연도별 세종시즌과 Sync Next 기록을 살펴보세요. 지난 기록의 요금과 예매 일정은 당시 기준입니다.","sections":[{"type":"timeline","title":"최근 세종시즌 기록","items":[{"date":"2025","title":"예술단 레퍼토리와 기획공연","body":"서울시발레단 ‘오하드 나하린 데카당스’, 서울시오페라단 ‘파우스트’, 서울시뮤지컬단 ‘더 퍼스트 그레잇 쇼’ 등이 공연되었습니다."},{"date":"2024","title":"서울시발레단 창단 공연","body":"창단 사전 공연 ‘봄의 제전’과 창단 공연 ‘한여름 밤의 꿈’이 시즌에 포함되었습니다. 합창·국악·무용·연극·뮤지컬·오페라와 클래식 기획공연을 확인할 수 있습니다."},{"date":"2023","title":"28개 공연 라인업","body":"공식 시즌 소개는 28개 공연·251회의 라인업을 안내했습니다. 연극 ‘카르멘’, ‘맥베스’, 뮌헨 필하모닉 내한공연 등이 기록되어 있습니다."}]},{"type":"cards","title":"연도별 공식 기록","searchable":true,"items":[{"id":"archive-season-2025","title":"2025 세종시즌","href":"https://www.sejongpac.or.kr/season/season2025/seasonMain.do","date":"2025","description":"월별 라인업과 당시 구독·패키지 안내","image":{"src":"https://www.sejongpac.or.kr/static/season/season2025/img/program/img_program01.png","alt":"2025 세종시즌 오하드 나하린 데카당스 공식 공연 이미지"}},{"id":"archive-season-2024","title":"2024 세종시즌","href":"https://www.sejongpac.or.kr/portal/season/main_2024.do","date":"2024","description":"장르별 공연과 월별 일정, 공식 시즌북"},{"id":"archive-season-2023","title":"2023 세종시즌","href":"https://www.sejongpac.or.kr/portal/season/main_2023.do","date":"2023","description":"예술단·기획공연과 당시 패키지 구성"},{"id":"archive-sync","title":"Sync Next 시즌 아카이브","href":"https://www.sejongpac.or.kr/portal/bbs/B0000053/list.do?menuNo=200667","description":"Sync Next 22·23·24·25·26 연도별 기록"}]},{"type":"downloads","title":"공식 자료","items":[{"label":"2024 세종시즌 시즌북 PDF","href":"https://www.sejongpac.or.kr/portal/cmmn/file/fileDown.do?atchFileId=bedb1ae634e7404eaf5da097e359152e&fileSn=3","description":"공식 2024 시즌 페이지에서 제공하는 32쪽 시즌북"}]},{"type":"links","title":"현재 시즌과 전체 기록","items":[{"label":"2026 세종시즌","href":"/programs/season/sejong"},{"label":"연도별 전체 시즌 기록","href":"https://www.sejongpac.or.kr/portal/bbs/B0000033/list.do?menuNo=200302"}]}],"sources":[{"label":"세종시즌