":"downloads","title":"공식 자료","items":[{"label":"2024 세종시즌 시즌북 PDF","href":"https://www.sejongpac.or.kr/portal/cmmn/file/fileDown.do?atchFileId=bedb1ae634e7404eaf5da097e359152e&fileSn=3","description":"공식 2024 시즌 페이지에서 제공하는 32쪽 시즌북"}]},{"type":"links","title":"현재 시즌과 전체 기록","items":[{"label":"2026 세종시즌","href":"/programs/season/sejong"},{"label":"연도별 전체 시즌 기록","href":"https://www.sejongpac.or.kr/portal/bbs/B0000033/list.do?menuNo=200302"}]}],"sources":[{"label":"세종시즌 연도별 목록","url":"https://www.sejongpac.or.kr/portal/bbs/B0000033/list.do?menuNo=200302"},{"label":"2025 세종시즌","url":"https://www.sejongpac.or.kr/season/season2025/seasonMain.do"},{"label":"2024 세종시즌","url":"https://www.sejongpac.or.kr/portal/season/main_2024.do"},{"label":"2023 세종시즌","url":"https://www.sejongpac.or.kr/portal/season/main_2023.do"},{"label":"Sync Next 연도별 기록","url":"https://www.sejongpac.or.kr/portal/bbs/B0000053/list.do?menuNo=200667"}]}'::jsonb;
update public.sejong_pages set payload=jsonb_set(payload,'{completion}','{"path":"/programs/season/classic","title":"누구나 클래식","summary":"클래식 공연에 해설을 더하고 관객이 관람료를 선택하는 세종문화회관의 문화동행 프로그램입니다.","sections":[{"type":"facts","title":"관람 방식","items":[{"label":"프로그램의 시작","value":"2007년부터 이어 온 대표 사회공헌 프로그램"},{"label":"관람료 선택제","value":"1,000원·3,000원·5,000원·10,000원 중 선택 / 선택 금액과 좌석은 무관"},{"label":"신청·관람","value":"온라인 회원 신청 후 추첨 / 1인 최대 2매 / 만 7세 미만 입장 불가"},{"label":"행복동행석","value":"객석 일부를 문화소외계층을 위한 좌석으로 운영"}]},{"type":"timeline","title":"신청부터 관람까지","items":[{"date":"신청","title":"공연별 기간에 신청","body":"공식 홈페이지 회원가입 후 신청합니다. 같은 공연에 중복 신청할 수 없습니다."},{"date":"추첨 후","title":"기간 내 좌석 선택·결제","body":"당첨 여부를 확인하고 정해진 기간에 예매하세요. 당첨 자체가 티켓 발권을 뜻하지는 않습니다."},{"date":"잔여석","title":"미예매·취소 좌석 선착순 예매","body":"당첨자가 예매하지 않았거나 취소된 좌석은 일반 예매로 이용할 수 있습니다. 잔여석이 없으면 예매할 수 없습니다."}]},{"type":"faq","title":"신청 전 알아두세요","items":[{"question":"당첨 후 예매하지 않으면 불이익이 있나요?","answer":"공식 FAQ는 당첨 후 미예매에는 불이익이 없다고 안내합니다. 예매 후 취소 없이 관람하지 않으면 향후 3회 신청이 제한됩니다."},{"question":"신청 일정은 어디서 확인하나요?","answer":"회차별 공연 안내에서 신청 기간·당첨 발표·예매 기간을 확인하세요. 회차마다 일정과 프로그램이 다릅니다."}]},{"type":"links","title":"회차별 안내","items":[{"label":"누구나 클래식 연간 공연과 이달의 공연","href":"https://www.sejongpac.or.kr/portal/classic4all/schedule/yearList.do?menuNo=200452"},{"label":"누구나 클래식 공식 신청 안내","href":"https://www.sejongpac.or.kr/portal/main/contents.do?menuNo=200450"},{"label":"행복동행석 등 이용 문의","href":"/visit/support/inquiry"}]}],"sources":[{"label":"누구나 클래식 소개·신청·관람료","url":"https://www.sejongpac.or.kr/portal/main/contents.do?menuNo=200450"},{"label":"공식 연간 공연 일정","url":"https://www.sejongpac.or.kr/portal/classic4all/schedule/yearList.do?menuNo=200452"},{"label":"미예매·미관람 FAQ","url":"https://www.sejongpac.or.kr/portal/bbs/B0000044/list.do?menuNo=200503"}]}'::jsonb,true) where id='/programs/season/classic' and payload->'completion' is distinct from '{"path":"/programs/season/classic","title":"누구나 클래식","summary":"클래식 공연에 해설을 더하고 관객이 관람료를 선택하는 세종문화회관의 문화동행 프로그램