update public.sejong_pages set payload=jsonb_set(payload,'{completion}','{"path":"/programs/season/everyone","title":"모든 누구나","summary":"공연 관람, 예술교육, 찾아가는 공연과 시민 합주로 일상에서 예술을 만나는 문화동행 사업입니다.","sections":[{"type":"table","title":"문화동행 프로그램","columns":["사업","참여 방식·대상"],"rows":[["누구나 클래식","오페라·교향곡·성악·발레 등 클래식 공연과 해설, 관람료 선택제"],["누구나 꿈나무오케스트라","문화예술교육 기회가 적은 아동·청소년의 음악교육과 합주"],["누구나 예술로 동행","공연장 방문이 어려운 가족과 이웃을 찾아가는 공연"],["누구나 동행챔버오케스트라","음악으로 모인 시민들의 앙상블 활동"],["누구나 세종썸머페스티벌","광화문 광장 등 열린 공간에서 만나는 야외 공연"]]},{"type":"cards","title":"참여할 프로그램 알아보기","items":[{"id":"everyone-classic","title":"누구나 클래식","href":"/programs/season/classic","description":"추첨 신청·잔여석 예매와 관람료 선택제"},{"id":"everyone-orchestra","title":"누구나 꿈나무오케스트라","href":"/programs/season/orchestra","description":"아동·청소년 음악교육의 취지와 활동 안내"},{"id":"everyone-summer","title":"누구나 세종썸머페스티벌","href":"/programs/season/summer","description":"도심 야외무대의 축제 기록과 장소 안내"}]},{"type":"prose","title":"사업별로 참여 조건이 다릅니다","paragraphs":["공연 예매, 참가자 모집과 기관 신청은 서로 다른 절차로 운영됩니다. 참여하려는 사업을 선택한 뒤 대상·모집 기간·신청처를 확인하세요. 일반 프로그램 예매가 교육단원 선발이나 기관 방문 공연 신청을 대신하지 않습니다."]}],"sources":[{"label":"모든 누구나 사업 소개","url":"https://www.sejongpac.or.kr/portal/main/contents.do?menuNo=200446"}]}'::jsonb,true) where id='/programs/season/everyone' and payload->'completion' is distinct from '{"path":"/programs/season/everyone","title":"모든 누구나","summary":"공연 관람, 예술교육, 찾아가는 공연과 시민 합주로 일상에서 예술을 만나는 문화동행 사업입니다.","sections":[{"type":"table","title":"문화동행 프로그램","columns":["사업","참여 방식·대상"],"rows":[["누구나 클래식","오페라·교향곡·성악·발레 등 클래식 공연과 해설, 관람료 선택제"],["누구나 꿈나무오케스트라","문화예술교육 기회가 적은 아동·청소년의 음악교육과 합주"],["누구나 예술로 동행","공연장 방문이 어려운 가족과 이웃을 찾아가는 공연"],["누구나 동행챔버오케스트라","음악으로 모인 시민들의 앙상블 활동"],["누구나 세종썸머페스티벌","광화문 광장 등 열린 공간에서 만나는 야외 공연"]]},{"type":"cards","title":"참여할 프로그램 알아보기","items":[{"id":"everyone-classic","title":"누구나 클래식","href":"/programs/season/classic","description":"추첨 신청·잔여석 예매와 관람료 선택제"},{"id":"everyone-orchestra","title":"누구나 꿈나무오케스트라","href":"/programs/season/orchestra","description":"아동·청소년 음악교육의 취지와 활동 안내"},{"id":"everyone-summer","title":"누구나 세종썸머페스티벌","href":"/programs/season/summer","description":"도심 야외무대의 축제 기록과 장소 안내"}]},{"type":"prose","title":"사업별로 참여 조건이 다릅니다","paragraphs":["공연 예매, 참가자 모집과 기관 신청은 서로 다른 절차로 운영됩니다. 참여하려는 사업을 선택한 뒤 대상·모집 기간·신청처를 확인하세요. 일반 프로그램 예매가 교육단원 선발이나 기관 방문 공연 신청을 대신하지 않습니다."]}],"sources":[{"label":"모든 누구나 사업 소개","url":"https://www.sejongpac.or.kr/portal/main/contents.do?menuNo=200446"}]}'::jsonb;
update public.sejong_pages set payload=jsonb_set(payload,'{completion}','{"path":"/programs/season/orchestra","title":"누구나 꿈나무오케스트라","summary":"문화예술을 접하기 어려운 아동·청소년이 음악을 배우고 함께 합주하며 성장하는 예술교육 사업입니다.","sections":[{"type":"prose","title":"함께 배우는 음악교육","paragraphs":["저소득층·다문화 가정 등 문화소외 아동·청소년에게 예술교육 기회를 제공합니다. 악기 기량뿐 아니라 함께 음악을 만드는 과정과 예술 경험을 통한 성장을 목표로 합니다.","세종문화회관은 자체 예술 역량을 활용한 ‘한국형 엘 시스테마’의 방향으로 이 음악교육을 추진하고 있습니다."]},{"type":"facts","title":"활동의 방향","items":[{"label":"대상","value":"문화예술교육 기회가 적은 유·청소년"},{"label":"교육","value":"음악과 다양한 예술 경험, 합주를 통한 협력"},{"label":"목표","value":"잠재력 발견과 자아 성장, 문화 참여 기회 확대"}]},{"type":"faq","title":"참여와 공연 관람","items":[{"question":"지금 단원을 신청할 수 있나요?","answer":"이 안내에서 현재 모집 중인 기수·연령·악기별 정원은 확인되지 않았습니다. 모집 공고가 게시되면 공고에 적힌 대상·접수 기간·방법을 확인하세요. 일반 공연 예매와 단원 신청은 별개입니다."},{"question":"사업의 활동 기록을 볼 수 있나요?","answer":"공식 ‘발자취’에서 연주와 활동 기록을 확인할 수 있습니다. 개별 공연 관람 조건은 해당 공연 공지를 따릅니다."}]},{"type":"links","title":"사업 확인·문의","items":[{"label":"공식 발자취","href":"https://www.sejongpac.or.kr/portal/htmlContents/htmlContents/view.do?menuCd=footprints&menuNo=200463"},{"label":"참여 관련 문의","href":"/visit/support/inquiry"},{"label":"모든 누구나 사업","href":"/programs/season/everyone"}]}],"sources":[{"label":"꿈나무오케스트라 대상·교육 목적","url":"https://www.sejongpac.or.kr/portal/main/contents.do?menuNo=200464"},{"label":"활동 발자취","url":"https://www.sejongpac.or.kr/portal/htmlContents/htmlContents/view.do?menuCd=footprints&menuNo=200463"}]}'::jsonb,true) where id='/programs/season/orchestra' and payload->'completion' is distinct from '{"path":"/programs/season/orchestra","title":"누구나 꿈나무오케스트라","summary":"문화예술을 접하기 어려운 아동·청소년이 음악을 배우고 함께 합주하며 성장하는 예술교육 사업입니다.","sections":[{"type":"prose","title":"함께 배우는 음악교육","paragraphs":["저소득층·다문화 가정 등 문화소외 아동·청소년에게 예술교육 기회를 제공합니다. 악기 기량뿐 아니라 함께 음악을 만드는 과정과 예술 경험을 통한 성장을 목표로 합니다.","세종문화회관은 자체 예술 역량을 활용한 ‘한국형 엘 시스테마’의 방향으로 이 음악교육을 추진하고 있습니다."]},{"type":"facts","title":"활동의 방향","items":[{"label":"대상","value":"문화예술교육 기회가 적은 유·청소년"},{"label":"교육","valu