update public.sejong_pages set payload=jsonb_set(payload,'{completion}','{"path":"/programs/season/package","title":"세종시즌 패키지","summary":"2026 세종시즌은 장르·가족·연령별 여덟 가지 패키지를 안내합니다. 구매 후 개별 공연의 회차와 좌석을 지정해야 합니다.","sections":[{"type":"table","title":"2026 패키지 구성","columns":["패키지","공연 선택","대상·특징"],"rows":[["무용","3개 이상","서울시무용단·서울시발레단"],["연극·뮤지컬","3개 이상","서울시극단·서울시뮤지컬단·기획 및 공동주최 공연"],["오페라","3개 모두","서울시오페라단"],["음악","3개 이상","합창·국악관현악·오케스트라"],["세종 인스피레이션","1개 고정+2개 이상","리딩·리스닝 스테이지와 초연작"],["가족","3개 이상","온 가족을 위한 시즌 공연"],["실버","6개 모두","1961년생 포함 이전 출생자 본인"],["올패스","5개 모두","2002.01.01~2019.12.31 출생자 본인"]],"note":"2026 공식 안내 기준입니다. 장르 패키지 최대 35%, 실버·올패스 70% 할인을 안내하며, 판매 기간·잔여 수량·개별 작품의 적용 조건은 구매 단계에서 확인하세요."},{"type":"timeline","title":"구매 후 이용","items":[{"date":"1","title":"패키지와 작품 선택","body":"대상 연령·공연 목록·좌석 등급을 확인하세요. 동일 작품을 중복 선택할 수 없으며 구매 후 선택 작품 변경에는 제한이 있습니다."},{"date":"2","title":"개별 공연 좌석 예매","body":"구매한 예매권으로 관람 날짜·회차·좌석을 지정하세요. 패키지 구매만으로 좌석이 배정되지는 않으며 조기 매진된 회차는 예매할 수 없습니다."},{"date":"3","title":"예매내역 확인","body":"공식 홈페이지 마이페이지의 공연예매내역에서 패키지와 개별 공연의 예매내역을 확인하세요."}]},{"type":"faq","title":"취소 전 확인","items":[{"question":"패키지를 취소하면 개별 공연도 함께 취소되나요?","answer":"공식 FAQ는 개별 공연을 취소한 뒤 패키지를 별도로 취소해야 환불된다고 안내합니다. 일반적으로 해당 패키지 첫 공연 전일 17시가 환불 마감이며, 구매 상품의 규정을 확인해야 합니다."}]},{"type":"links","title":"상품과 공연 확인","items":[{"label":"공식 2026 패키지 상세","href":"https://www.sejongpac.or.kr/season/season2026/pck.do"},{"label":"2026 세종시즌 공연","href":"/programs/season/sejong"}]}],"sources":[{"label":"2026 패키지 구성·대상","url":"https://www.sejongpac.or.kr/season/season2026/pck.do"},{"label":"패키지 예매·취소 FAQ","url":"https://www.sejongpac.or.kr/portal/bbs/B0000044/list.do?menuNo=200503&pageIndex=4"}]}'::jsonb,true) where id='/programs/season/package' and payload->'completion' is distinct from '{"path":"/programs/season/package","title":"세종시즌 패키지","summary":"2026 세종시즌은 장르·가족·연령별 여덟 가지 패키지를 안내합니다. 구매 후 개별 공연의 회차와 좌석을 지정해야 합니다.","sections":[{"type":"table","title":"2026 패키지 구성","columns":["패키지","공연 선택","대상·특징"],"rows":[["무용","3개 이상","서울시무용단·서울시발레단"],["연극·뮤지컬","3개 이상","서울시극단·서울시뮤지컬단·기획 및 공동주최 공연"],["오페라","3개 모두","서울시오페라단"],["음악","3개 이상","합창·국악관현악·오케스트라"],["세종 인스피레이션","1개 고정+2개 이상","리딩·리스닝 스테이지와 초연작"],["가족","3개 이상","온 가족을 위한 시즌 공연"],["실버","6개 모두","1961년생 포함 이전 출생자 본인"],["올패스","5개 모두","2002.01.01~2019.12.31 출생자 본인"]],"note":"2026 공식 안내 기준입니다. 장르 패키지 최대 35%, 실버·올패스 70% 할인을 안내하며, 판매 기간·잔여 수량·개별 작품의 적용 조건은 구매 단계에서 확인하세요."},{"type":"timeline","title":"구매 후 이용","items":[{"date":"1","title":"패키지와 작품 선택","body":"대상 연령·공연 목록·좌석 등급을 확인하세요. 동일 작품을 중복 선택할 수 없으며 구매 후 선택 작품 변경에는 제한이 있습니다."},{"date":"2","title":"개별 공연 좌석 예매","body":"구매한 예매권으로 관람 날짜·회차·좌석을 지정하세요. 패키지 구매만으로 좌석이 배정되지는 않으며 조기 매진된 회차는 예매할 수 없습니다."},{"date":"3","title":"예매내역 확인","body":"공식 홈페이지 마이페이지의 공연예매내역에서 패키지와 개별 공연의 예매내역을 확인하세요."}]},{"type":"faq","title":"취소 전 확인","items":[{"question":"패키지를 취소하면 개별 공연도 함께 취소되나요?","answer":"공식 FAQ는 개별 공연을 취소한 뒤 패키지를 별도로 취소해야 환불된다고 안내합니다. 일반적으로 해당 패키지 첫 공연 전일 17시가 환불 마감이며, 구매 상품의 규정을 확인해야 합니다."}]},{"type":"links","title":"상품과 공연 확인","items":[{"label":"공식 2026 패키지 상세","href":"https://www.sejongpac.or.kr/season/season2026/pck.do"},{"label":"2026 세종시즌 공연","href":"/programs/season/sejong"}]}],"sources":[{"label":"2026 패키지 구성·대상","url":"https://www.sejongpac.or.kr/season/season2026/pck.do"},{"label":"패키지 예매·취소 FAQ","url":"https://www.sejongpac.or.kr/portal/bbs/B0000044/list.do?menuNo=200503&pageIndex=4"}]}'::jsonb;
update public.sejong_pages set payload=jsonb_set(payload,'{completion}','{"path":"/programs/season/sejong","title":"2026 세종시즌","summary":"서울시예술단과 기획·공동주최 공연의 2026 시즌을 만나보세요. 작품마다 공연장과 예매 조건이 다릅니다.","sections":[{"type":"prose","title":"연간 공연을 미리 고르는 시즌","paragraphs":["합창·국악관현악·무용·발레·연극·뮤지컬·오페라와 기획공연을 연간 라인업으로 소개합니다. 국립극장 등 외부 공연장에서 열리는 작품도 있으므로 예매한 작품의 장소를 확인하세요."]},{"type":"cards","title":"2026 하반기 주요 작품","searchable":true,"items":[{"id":"season2026-gagok","title":"가곡시대","href":"https://www.sejongpac.or.kr/portal/performance/performance/performTicket.do?menuNo=200320&performIdx=36789","date":"2026.10.23~10.24","meta":"서울시합창단 · 세종체임버홀","description":"서울시합창단의 가곡 무대. 공연 시간과 관람 조건은 작품 상세에서 확인하세요."},{"id":"season2026-enemy","title":"에너미","href":"https://www.sejongpac.or.kr/portal/performance/performance/performTicket.do?menuNo=200320&performIdx=37669","date":"2026.10.26~11.14","meta":"서울시극단 · 세종M씨어터","description":"서울시극단의 2026 시즌 연극입니다. 회차·출연진은 작품별 상세를 확인하세요."},{"id":"season2026-boheme","title":"라보엠","href":"https://www.sejongpac.or.kr/portal/performance/performance/performTicket.do?menuNo=200320&performIdx=36791","date":"2026.11.05~11.08","meta":"서울시오페라단 · 세종대극장","description":"서울시오페라단의 하반기 오페라. 캐스팅과 좌석 등급별 요금은 작품 상세에 안내합니다."},{"id":"season2026-christmas","title":"크리스마스 캐럴","href":"https://www.sejongpac.or.kr/portal/performance/performance/performTicket.do?menuNo=200320&performIdx=36793","date":"2026.12.02~12.27","meta":"서울시뮤지컬단 · 세종M씨어터","description":"연말 시즌에 만나는 서울시뮤지컬단의 뮤지컬입니다. 휴연일·관람 연령을 확인하세요."}]},{"type":"table","title":"시즌을 고르는 방법","columns":["방법","이용 방식"],"rows":[["개별 공연","원하는 작품·회차·좌석을 선택해 예매"],["구독","2026 구독 라이트·플러스의 선예매·할인 조건 확인 후 개별 공연 예매"],["패키지","장르·가족·연령별 작품 묶음을 구매한 뒤 개별 좌석 지정"]]},{"type":"links","title":"시즌 더 보기","items":[{"label":"전체 2026 라인업","href":"https://www.sejongpac.or.kr/season/season2026/seasonProgram.do"},{"label":"패키지 구성","href":"/programs/season/package"},{"label":"지난 시즌","href":"/programs/history"}]}],"sources":[{"label":"2026 세종시즌 공식 라인업",