update public.sejong_pages set payload=jsonb_set(payload,'{completion}','{"path":"/programs/season/summer","title":"누구나 세종썸머페스티벌","summary":"공연장을 벗어나 광화문 광장 등 열린 공간에서 만나는 야외 클래식 축제입니다.","sections":[{"type":"prose","title":"도심에서 만나는 야외 공연","paragraphs":["누구나 쉽게 클래식 음악을 접할 수 있도록 기획된 시민 친화적 야외 프로그램입니다. 공연장 밖의 열린 공간으로 무대를 넓혀 일상에서 음악을 만나는 기회를 제공합니다."]},{"type":"cards","title":"2026 공식 공연 기록","items":[{"id":"summer2026-aria","title":"광화문에서 만나는 아리아","href":"https://www.sejongpac.or.kr/portal/performance/performance/performTicket.do?menuNo=200592&performIdx=37166","date":"2026.05.22~05.23","meta":"광화문 광장","status":"공연 종료","description":"2026 공식 축제 목록에 등록된 광화문 야외 공연입니다."},{"id":"summer2026-traviata","title":"제4회 야외오페라 라 트라비아타","href":"https://www.sejongpac.or.kr/portal/performance/performance/performTicket.do?menuNo=200592&performIdx=37179","date":"2026.05.22~05.23","meta":"여의도 한강공원 물빛무대","status":"공연 종료","description":"공식 올해의 축제 목록에 함께 안내된 야외오페라입니다. 광화문 광장과 장소가 다릅니다."}]},{"type":"faq","title":"다음 축제를 준비할 때","items":[{"question":"여름에만 열리나요?","answer":"행사명만으로 날짜를 판단하지 마세요. 2026 공식 목록에는 5월 공연이 안내되어 있습니다. 새 축제의 날짜·장소는 해당 연도 공지로 확인하세요."},{"question":"누구나 무료로 입장할 수 있나요?","answer":"공연마다 사전 신청·좌석·관람료 조건이 다를 수 있습니다. 야외 행사라는 이유만으로 무료·자유입장으로 안내하지 않으며, 개별 공연의 관람 안내를 확인해야 합니다."},{"question":"비가 오면 어떻게 하나요?","answer":"야외 공연은 기상 상황에 따른 운영 공지를 확인하세요. 우천 시 진행·변경 여부는 해당 공연 주최 측이 안내합니다."}]},{"type":"links","title":"연도별 안내","items":[{"label":"공식 올해의 축제·지난 축제","href":"https://www.sejongpac.or.kr/portal/sejongSummer/sejongSummer/list.do?menuNo=200592"},{"label":"광화문 대중교통","href":"/visit/directions"}]}],"sources":[{"label":"썸머페스티벌의 취지","url":"https://www.sejongpac.or.kr/portal/main/contents.do?menuNo=200581"},{"label":"2026 공식 축제 목록","url":"https://www.sejongpac.or.kr/portal/sejongSummer/sejongSummer/list.do?menuNo=200592"}]}'::jsonb,true) where id='/programs/season/summer' and payload->'completion' is distinct from '{"path":"/programs/season/summer","title":"누구나 세종썸머페스티벌","summary":"공연장을 벗어나 광화문