update public.sejong_pages set payload=jsonb_set(payload,'{completion}','{"path":"/rental/guide","title":"대관안내","summary":"정기·수시 대관의 차이와 신청 전에 확인할 사항을 정리했습니다.","sections":[{"type":"table","title":"접수 유형","columns":["유형","공연장","미술관"],"rows":[["정기대관","차기년도 사용분을 전년도 3~4월 중 공고","5~7월경 공고를 통해 접수 일정 안내"],["수시대관","정기대관 뒤 유휴일정이 생기면 별도 공고","유휴일정 공고 후 정기대관과 같은 절차"],["장기공연","전년도 2~3월 중 별도 공고·심사","전시 기간과 설치·철수 조건을 담당자와 협의"]],"note":"일반적인 공고 시기이며, 실제 신청 기간과 사용 가능일은 개별 공고가 기준입니다."},{"type":"faq","title":"신청 전 확인","items":[{"question":"희망일을 정하면 바로 사용할 수 있나요?","answer":"공고된 일정에 신청하고 심사·승인·계약을 거쳐야 합니다. 상담 기록은 사용 승인이나 계약을 뜻하지 않습니다."},{"question":"미술관 대관에도 홈페이지 회원 계정을 쓰나요?","answer":"공식 미술관 접수는 대관시스템의 기획사·개인 회원 승인 후 가능합니다. 일반 홈페이지 회원가입과 별도 절차입니다."}]},{"type":"links","title":"다음 준비","items":[{"label":"신청 대상과 기준","href":"/rental/guide/eligibility"},{"label":"서류와 심사","href":"/rental/process/documents"},{"label":"대관 문의","href":"/rental/contact"}]}],"sources":[{"label":"공연장 정기·수시 대관","url":"https://www.sejongpac.or.kr/portal/main/contents.do?menuNo=200404"},{"label":"미술관 대관 절차","url":"https://www.sejongpac.or.kr/portal/main/contents.do?menuNo=200420"}]}'::jsonb,true) where id='/rental/guide' and payload->'completion' is distinct from '{"path":"/rental/guide","title":"대관안내","summary":"정기·수시 대관의 차이와 신청 전에 확인할 사항을 정리했습니다.","sections":[{"type":"table","title":"접수 유형","columns":["유형","공연장","미술관"],"rows":[["정기대관","차기년도 사용분을 전년도 3~4월 중 공고","5~7월경 공고를 통해 접수 일정 안내"],["수시대관","정기대관 뒤 유휴일정이 생기면 별도 공고","유휴일정 공고 후 정기대관과 같은 절차"],["장기공연","전년도 2~3월 중 별도 공고·심사","전시 기간과 설치·철수 조건을 담당자와 협의"]],"note":"일반적인 공고 시기이며, 실제 신청 기간과 사용 가능일은 개별 공고가 기준입니다."},{"type":"faq","title":"신청 전 확인","items":[{"question":"희망일을 정하면 바로 사용할 수 있나요?","answer":"공고된 일정에 신청하고 심사·승인·계약을 거쳐야 합니다. 상담 기록은 사용 승인이나 계약을 뜻하지 않습니다."},{"question":"미술관 대관에도 홈페이지 회원 계정을 쓰나요?","answer":"공식 미술관 접수는 대관시스템의 기획사·개인 회원 승인 후 가능합니다. 일반 홈페이지 회원가입과 별도 절차입니다."}]},{"type":"links","title":"다음 준비","items":[{"label":"신청 대상과 기준","href":"/rental/guide/eligibility"},{"