update public.sejong_pages set payload=jsonb_set(payload,'{completion}','{"path":"/rental/process","title":"대관절차","summary":"심사·승인·계약과 공연 준비에 이르는 순서를 확인하세요.","sections":[{"type":"timeline","title":"공고에서 계약까지","items":[{"date":"01","title":"공고 확인","body":"공간별 정기·수시 공고에서 신청 대상, 사용 기간, 접수 기한을 확인합니다. 공고되지 않은 일정은 대관 대상이 아닙니다."},{"date":"02","title":"신청 준비","body":"행사 개요와 설치·리허설·공연·철수에 필요한 기간을 정하고 계획서를 준비합니다."},{"date":"03","title":"심사","body":"공연·전시 계획을 대관심의위원회에서 심사합니다. 희망일 입력이나 상담만으로 사용 일정이 확정되지는 않습니다."},{"date":"04","title":"결과 확인","body":"공연장 정기대관은 접수 마감 후 4~5주, 수시대관은 2~3주 내 결과를 안내합니다. 미술관은 정기대관 약 한 달, 수시대관 개별 통보를 기준으로 합니다."},{"date":"05","title":"계약·기술 협의","body":"승인 조건에 따라 계약금·잔금을 납부하고 기술·안전·입장권 검인 등 운영 사항을 협의합니다."}]},{"type":"facts","title":"승인 뒤의 기한","items":[{"label":"계약금","value":"공연장 승인 통보 후 9일 이내. 정기대관은 총 대관료의 20%, 수시대관은 40%를 기준으로 합니다."},{"label":"계약","value":"계약금 납부 후 7일 이내 계약 체결. 공연장 전자계약은 ‘도뉴’를 사용하며 방문계약 조건도 안내합니다."},{"label":"입장권 검인","value":"공연 전 유·무료 입장권 전체를 검인받아야 하며, 온라인 발매 최소 2주 전 신청합니다. 대관료와 부대설비 사전신청 비용 완납이 필요합니다."}]},{"type":"links","title":"준비 자료","items":[{"label":"서류와 심사기준","href":"/rental/process/documents"},{"label":"신청 준비 기록","href":"/rental/apply"},{"label":"세종대극장 절차 원문","href":"https://www.sejongpac.or.kr/portal/main/contents.do?menuNo=200404"},{"label":"미술관 절차 원문","href":"https://www.sejongpac.or.kr/portal/main/contents.do?menuNo=200420"}]}],"sources":[{"label":"공연장 계약·검인 절차","url":"https://www.sejongpac.or.kr/portal/main/contents.do?menuNo=200404"},{"label":"전시 대관 절차","url":"https://www.sejongpac.or.kr/portal/main/contents.do?menuNo=200420"}]}'::jsonb,true) where id='/rental/process' and payload->'completion' is distinct from '{"path":"/rental/process","title":"대관절차","summary":"심사·승인·계약과 공연 준비에 이르는 순서를 확인하세요.","sections":[{"type":"timeline","title":"공고에서 계약까지","items":[{"date":"01","title":"공고 확인","body":"공간별 정기·수시 공고에서 신청 대상, 사용 기간, 접수 기한을 확인합니다. 공고되지 않은 일정은 대관 대상이 아닙니다."},{"date":"02","title":"신청 준비","body":"행사 개요와 설치·리허설·공연·철수에 필요한 기간을 