update public.sejong_pages set payload=jsonb_set(payload,'{completion}','{"path":"/rental/process/documents","title":"신청서류 및 심사기준","summary":"공연·전시 계획과 기술·안전 자료를 구분해 준비하세요.","sections":[{"type":"table","title":"서류 준비 목록","columns":["구분","준비 내용","확인처"],"rows":[["행사 개요","행사명·기간·참여진·대상 관객·운영 계획","해당 공고와 신청서"],["전시 포트폴리오","전시 내용을 알 수 있는 도판과 계획. 공식 접수의 PDF 첨부는 30MB 이내","미술관 대관 절차"],["무대·설치","평면도·반입·설치·철수·전력과 장비 요청","공간별 기술자료"],["안전","방염 및 무대 사용 관련 제출 서식","기술 담당자와 최신 양식"],["계약","승인 뒤 계약 주체·사업자 등 필요한 증빙","승인 통보와 계약 안내"]]},{"type":"downloads","title":"공연장 준비 양식","items":[{"label":"각종 제출 서식","href":"https://www.sejongpac.or.kr/portal/cmmn/file/fileDown.do?atchFileId=cd837dc85dcf4e00b051f3db1a9b2177&fileSn=15"},{"label":"방염처리 안내문","href":"https://www.sejongpac.or.kr/portal/cmmn/file/fileDown.do?atchFileId=cd837dc85dcf4e00b051f3db1a9b2177&fileSn=12"},{"label":"방염 관련 준비 서류","href":"https://www.sejongpac.or.kr/portal/cmmn/file/fileDown.do?atchFileId=cd837dc85dcf4e00b051f3db1a9b2177&fileSn=13"}]},{"type":"prose","title":"심사와 제출 시점","paragraphs":["대관심의위원회가 공고와 제출 계획을 심사합니다. 서류 목록과 제출 기한은 개별 공고의 조건이 우선하며, 계약 이후 필요한 기술·안전 자료와 신청 단계의 자료는 구분해 준비하세요."]}],"sources":[{"label":"미술관 포트폴리오 조건","url":"https://www.sejongpac.or.kr/portal/main/contents.do?menuNo=200420"},{"label":"공연장 기술·안전 양식","url":"https://www.sejongpac.or.kr/portal/main/contents.do?menuNo=200407"},{"label":"대관 심사","url":"https://www.sejongpac.or.kr/portal/main/contents.do?menuNo=200404"}]}'::jsonb,true) where id='/rental/process/documents' and payload->'completion' is distinct from '{"path":"/rental/process/documents","title":"신청서류 및 심사기준","summary":"공연·전시 계획과 기술·안전 자료를 구분해 준비하세요.","sections":[{"type":"table","title":"서류 준비 목록","columns":["구분","준비 내용","확인처"],"rows":[["행사 개요","행사명·기간·참여진·대상 관객·운영 계획","해당 공고와 신청서"],["전시 포트폴리오","전시 내용을 알 수 있는 도판과 계획. 공식 접수의 PDF 첨부는 30MB 이내","미술관 대관 절차"],["무대·설치","평면도·반입·설치·철수·전력과 장비 요청","공간별 기술자료"],["안전","방염 및 무대 사용 관련 제출 서식","기술 담당자와 최신 양식"],["계약","승인 뒤 계약 주체·사업자 등 필요한 증빙","승인 통보와 계약 안내"]]},{