update public.sejong_pages set payload=jsonb_set(payload,'{completion}','{"path":"/rental/schedule","title":"대관일정","summary":"공고 게시일을 월별로 확인하고 공고에 명시된 신청·사용 기간을 살펴보세요.","special":"rental-calendar","sections":[{"type":"prose","title":"공고 일정과 사용 가능일은 다릅니다","paragraphs":["이 달력은 게시된 대관 공고의 날짜를 보여줍니다. 날짜에 표시가 없다는 이유로 공간을 사용할 수 있는 것은 아닙니다. 공고에 없는 일정은 임의로 신청 가능 상태로 표시하지 않습니다."]},{"type":"links","title":"공고와 상담","items":[{"label":"공식 대관 공고","href":"https://www.sejongpac.or.kr/portal/reservation/reservation/list.do?menuNo=200402"},{"label":"희망 일정 상담","href":"/rental/contact"},{"label":"대관 신청 준비","href":"/rental/apply"}]}],"sources":[{"label":"공간별 접수 중 공고","url":"https://www.sejongpac.or.kr/portal/reservation/reservation/list.do?menuNo=200402"},{"label":"공고되지 않은 일정에 대한 기준","url":"https://www.sejongpac.or.kr/portal/main/contents.do?menuNo=200404"}]}'::jsonb,true) where id='/rental/schedule' and payload->'completion' is distinct from '{"path":"/rental/schedule","title":"대관일정","summary":"공고 게시일을 월별로 확인하고 공고에 명시된 신청·사용 기간을 살펴보세요.","special":"rental-calendar","sections":[{"type":"prose","title":"공고 일정과 사용 가능일은 다릅니다","paragraphs":["이 달력은 게시된 대관 공고의 날짜를 보여줍니다. 날짜에 표시가 없다는 이유로 공간을 사용할 수 있는 것은 아닙니다. 공고에 없는 일정은 임의로 신청 가능 상태로 표시하지 않습니다."]},{"type":"links","title":"공고와 상담","items":[{"label":"공식 대관 공고","href":"https://www.sejongpac.or.kr/portal/reservation/reservation/list.do?menuNo=200402"},{"label":"희망 일정 상담","href":"/rental/contact"},{"label":"대관 신청 준비","href":"/rental/apply"}]}],"sources":[{"label":"공간별 접수 중 공고","url":"https://www.sejongpac.or.kr/portal/reservation/reservation/list.do?menuNo=200402"},{"label":"공고되지 않은 일정에 대한 기준","url":"https://www.sejongpac.or.kr/portal/main/contents.do?menuNo=200404"}]}'::jsonb;
