update public.sejong_pages set payload=jsonb_set(payload,'{completion}','{"path":"/visit","title":"방문 안내","summary":"교통편부터 티켓 수령, 공연 전후 이용할 시설까지 방문에 필요한 정보를 확인하세요.","sections":[{"type":"facts","title":"처음 방문하시나요?","items":[{"label":"주소","value":"서울특별시 종로구 세종대로 175, 세종문화회관 (03172)"},{"label":"가까운 역","value":"5호선 광화문역 1·8번 또는 7번 출구"},{"label":"전화예매·이용 문의","value":"02-399-1000 · 09:00~20:00"}]},{"type":"cards","title":"필요한 방문 정보","items":[{"id":"visit-transport","title":"오시는 길","href":"/visit/directions","description":"지하철 출구와 버스 정류장별 노선, 공식 위치 지도를 확인하세요."},{"id":"visit-parking","title":"주차 요금·할인","href":"/visit/directions/parking","description":"세종로 공영주차장 공연 관람객 4시간권은 8,000원입니다. 할인 적용 조건을 확인하세요."},{"id":"visit-access","title":"접근성 안내","href":"/visit/accessibility","description":"엘리베이터·휠체어 리프트 위치와 해피콜 도움 요청 방법을 안내합니다."},{"id":"visit-amenities","title":"편의시설·식음료","href":"/visit/amenities","description":"물품보관함, 돌봄시설, 오페라글라스와 식음료 매장을 찾아보세요."}]},{"type":"links","title":"관람을 준비하세요","items":[{"label":"방문 순서와 준비물","href":"/visit/plan"},{"label":"공연 관람 예절","href":"/visit/etiquette"},{"label":"단체관람 문의","href":"/visit/group"},{"label":"고객지원","href":"/visit/support"}]}],"sources":[{"label":"공식 대중교통 이용안내","url":"https://www.sejongpac.or.kr/portal/main/contents.do?menuNo=200352"},{"label":"세종로 공영주차장 요금","url":"https://www.sejongpac.or.kr/portal/main/contents.do?menuNo=200391"}]}'::jsonb,true) where id='/visit' and payload->'completion' is distinct from '{"path":"/visit","title":"방문 안내","summary":"교통편부터 티켓 수령, 공연 전후 이용할 시설까지 방문에 필요한 정보를 확인하세요.","sections":[{"type":"facts","title":"처음 방문하시나요?","items":[{"label":"주소","value":"서울특별시 종로구 세종대로 175, 세종문화회관 (03172)"},{"label":"가까운 역","value":"5호선 광화문역 1·8번 또는 7번 출구"},{"label":"전화예매·이용 문의","value":"02-399-1000 · 09:00~20:00"}]},{"type":"cards","title":"필요한 방문 정보","items":[{"id":"visit-transport","title":"오시는 길","href":"/visit/directions","description":"지하철 출구와 버스 정류장별 노선, 공식 위치 지도를 확인하세요."},{"id":"visit-parking","title":"주차 요금·할인","href":"/