update public.sejong_pages set payload=jsonb_set(payload,'{completion}','{"path":"/visit/accessibility","title":"접근성 안내","summary":"이동 경로와 현장 도움 요청 방법을 확인하고, 좌석·할인 문의는 공연을 선택한 뒤 진행해 주세요.","sections":[{"type":"table","title":"이동을 돕는 시설","columns":["시설","설치·이용 위치"],"rows":[["엘리베이터","대극장 좌·우측 / 세종라운지·세종미술관·세종뜨락·M씨어터 로비 1층 연결"],["휠체어 리프트","대극장 1층, 세종뜨락, M씨어터 입구 계단"],["점자촉지도","대극장 입구"],["점자블록","대극장·M씨어터의 장애인 통로"]]},{"type":"facts","title":"해피콜로 현장 도움을 요청하세요","items":[{"label":"버튼 위치","value":"중앙계단 좌·우측, 세종로 주차장 입구, 광화문역 1·8번 출구 방향, 예술의정원 입구"},{"label":"이용 방법","value":"해피콜 버튼을 누르면 보안 담당자가 방문 위치로 찾아와 이동을 돕습니다."},{"label":"방문 전 문의","value":"02-399-1000 · 09:00~20:00"}]},{"type":"prose","title":"좌석과 우대할인","paragraphs":["휠체어 이용 여부와 필요한 동반 좌석을 예매 전 콜센터에 알려 주세요. 좌석 배치와 이용 가능 회차는 공연마다 다릅니다.","공식 예매 안내는 장애인·국가유공자 우대할인을 안내하고 있습니다. 본인·동반인 적용 범위는 공연 상세의 할인 안내로 확인하고, 티켓 수령 시 복지카드 등 해당 증빙을 제시하세요. 대관공연은 주최사 정책이 다를 수 있습니다."]},{"type":"links","title":"이동 경로와 좌석 확인","items":[{"label":"휠체어 이용관객 이동 안내 영상","href":"https://www.youtube.com/playlist?list=PLzq6IvukAJKe0Gczz6dJOiL0_un06Zh9X"},{"label":"공연장별 공식 이동 경로","href":"https://www.sejongpac.or.kr/portal/main/contents.do?menuNo=200392"},{"label":"좌석배치도","href":"https://www.sejongpac.or.kr/portal/main/contents.do?menuNo=200368"},{"label":"접근성 관련 문의하기","href":"/visit/support/inquiry"}]}],"sources":[{"label":"장애인이용안내","url":"https://www.sejongpac.or.kr/portal/main/contents.do?menuNo=200353"},{"label":"우대할인 예매안내","url":"https://www.sejongpac.or.kr/portal/main/contents.do?menuNo=200322"},{"label":"공식 휠체어 이동 영상 연결","url":"https://www.sejongpac.or.kr/portal/main/contents.do?menuNo=200392"}]}'::jsonb,true) where id='/visit/accessibility' and payload->'completion' is distinct from '{"path":"/visit/accessibility","title":"접근성 안내","summary":"이동 경로와 현장 도움 요청 방법을 확인하고, 좌석·할인 문의는 공연을 선택한 뒤 진행해 주세요.","sections":[{"type":"table","title":"이동을 돕는 시설","columns":["시설","설치·이용 위치"],"rows":[["엘리베이터","대극장 좌·우측 / 세종라운지·세종미술관·세종뜨락·M씨어터 로비 1층 연결"],["휠체어 리프트","대극장 1층, 