update public.sejong_pages set payload=jsonb_set(payload,'{completion}','{"path":"/visit/amenities/dining","title":"식음료 매장","summary":"카페·베이커리부터 식사 공간까지 매장별 위치와 운영시간을 안내합니다.","sections":[{"type":"table","title":"카페·베이커리","columns":["매장","위치","영업시간","문의"],"rows":[["아티제","1층 세종라운지","월 08:30~20:00 / 화~금 08:00~21:30 / 주말 09:00~21:30","02-734-2155"],["오리지널팬케이크하우스","지상 2층, 세종미술관 위","5~10월 평일 09:00·주말/공휴일 08:00~22:00 / 11~4월 같은 개점시간~21:00","0505-1375-7481"],["더베이크","예술동 1층, S씨어터 인근","09:00~20:00","02-738-3060"]]},{"type":"table","title":"식당","columns":["매장","종류·위치","영업시간","문의"],"rows":[["친니","중식 / 지하 1층","11:30~21:30, 15:00~17:00 브레이크타임","02-733-3270"],["설가온","한정식 / 지하 1층","11:30~21:30, 15:00~17:00 브레이크타임","02-733-3276"]],"note":"운영시간·휴무·주문 마감은 매장 사정에 따라 달라질 수 있습니다. 예약과 단체 식사, 알레르기 관련 사항은 각 매장으로 문의하세요."},{"type":"faq","title":"식사와 공연을 함께 계획할 때","items":[{"question":"식당을 이용한 주차 할인은 어디서 받나요?","answer":"지하 식당가 이용객은 매장에서 후불 바코드 주차할인권을 별도로 받으세요. 공연 티켓의 할인과는 적용 방법을 구분해 확인하세요."},{"question":"음식물을 객석에 가져갈 수 있나요?","answer":"공연별 반입 규정을 확인하세요. 음식물과 꽃다발 등 반입 제한 물품은 공연장 물품보관함을 이용할 수 있습니다. 보관한 음식물은 당일 찾아가세요."}]}],"sources":[{"label":"공식 F&B 매장 운영정보","url":"https://www.sejongpac.or.kr/portal/main/contents.do?menuNo=200389"},{"label":"식당가 주차할인권 안내","url":"https://www.sejongpac.or.kr/portal/main/contents.do?menuNo=200391"},{"label":"반입제한 물품 보관 안내","url":"https://www.sejongpac.or.kr/portal/main/contents.do?menuNo=200388"}]}'::jsonb,true) where id='/visit/amenities/dining' and payload->'completion' is distinct from '{"path":"/visit/amenities/dining","title":"식음료 매장","summary":"카페·베이커리부터 식사 공간까지 매장별 위치와 운영시간을 안내합니다.","sections":[{"type":"table","title":"카페·베이커리","columns":["매장","위치","영업시간","문의"],"rows":[["아티제","1층 세종라운지","월 08:30~20:00 / 화~금 08:00~21:30 / 주말 09:00~21:30","02-734-2155"],["오리지널팬케이크하우스","지상 2층, 세종미술관 위","5~10월 평일 09:00·주말/공휴일 08:00~22:00 / 11~4월 같은 개점시간~21:00","0505-1375-7481"],["더베이크","예술동 1층, S씨어터 인근","09:00~20:00","02-738-3060"]]},{"type":"table","title":"식당","columns":["매장",