update public.sejong_pages set payload=jsonb_set(payload,'{completion}','{"path":"/visit/directions/parking","title":"주차 안내","summary":"세종로 공영주차장을 이용하세요. 관람객 할인은 입차 95분 후부터 적용할 수 있습니다.","sections":[{"type":"facts","title":"세종로 공영주차장","items":[{"label":"위치","value":"서울특별시 종로구 세종로 79-10"},{"label":"운영·문의","value":"24시간·연중무휴 / 02-2290-6566"},{"label":"차량 높이","value":"1.8m 이상 차량 진입 불가"}]},{"type":"table","title":"요금과 관람객 할인","columns":["구분","요금","조건"],"rows":[["일반 주차","5분당 430원","미세먼지 시즌제 12~3월에는 5등급 차량 5분당 645원"],["공연 관람객","4시간 8,000원","공연 티켓 바코드·QR코드로 정산"],["유료전시·체험 관람객","2시간 4,000원","해당 티켓 바코드 또는 별도 주차할인권 확인"],["아카데미 수강생","2시간 4,000원","수강 관련 주차할인권 확인"]],"note":"시간제 할인 시간은 입차 시각부터 계산합니다. 세종로 공영주차장 이외의 주차장에는 적용되지 않습니다."},{"type":"timeline","title":"할인 정산 순서","items":[{"date":"입차 후","title":"티켓의 주차 QR코드 확인","body":"디지털 티켓은 ‘주차/물품’ 메뉴에서 확인하세요. 전시는 티켓이나 별도로 받은 할인권을 이용합니다."},{"date":"입차 95분 이후","title":"무인정산기로 사전 정산","body":"차량번호와 티켓 바코드·QR코드를 이용해 할인을 적용하세요. 지하 식당가 이용객은 매장에서 주차할인권을 별도로 받으세요."},{"date":"정산 후 15분 이내","title":"출차","body":"15분을 넘기면 5분당 430원의 추가요금이 발생합니다. 공연 종료 직후에는 출차가 혼잡할 수 있습니다."}]},{"type":"links","title":"출입구와 교통 상황","items":[{"label":"공식 주차장 출입구 지도","href":"https://www.sejongpac.or.kr/static/portal/img/content/parking_0100.gif"},{"label":"대중교통으로 오시는 길","href":"/visit/directions","description":"광화문 행사나 차량 통제 시 주차장 이용이 제한될 수 있습니다."}]}],"sources":[{"label":"공영주차장 주차요금·할인 조건","url":"https://www.sejongpac.or.kr/portal/main/contents.do?menuNo=200391"},{"label":"공영주차장 위치·운영","url":"https://www.sejongpac.or.kr/portal/main/contents.do?menuNo=200390"},{"label":"디지털 티켓의 주차 QR코드","url":"https://www.sejongpac.or.kr/portal/main/contents.do?menuNo=200323"}]}'::jsonb,true) where id='/visit/directions/parking' and payload->'completion' is distinct from '{"path":"/visit/directions/parking","title":"주차 안내","summary":"세종로 공영주차장을 이용하세요. 관람객 할인은 입차 95분 후부터 적용할 수 있습니다.","sections":[{"type":"facts","title":"세종로 공영주차장","items":[{"label":"위치","value":"서울특별시 종로구 세종로 79-10"},{"label