update public.sejong_pages set payload=jsonb_set(payload,'{completion}','{"path":"/visit/etiquette","title":"관람 예절","summary":"같은 공간에서 공연을 즐기는 관객과 출연자를 위해 입장과 촬영·반입 규정을 확인해 주세요.","sections":[{"type":"table","title":"공연 전후 확인할 사항","columns":["상황","안내"],"rows":[["공연 시작 전","티켓의 관람 연령과 입장 시간을 확인하고, 휴대전화의 소리·진동·화면 빛이 관람을 방해하지 않도록 준비하세요."],["늦게 도착한 경우","공연에 따라 지정된 지연 입장 시간에만 입장하며, 예매 좌석 대신 지연 관객석으로 안내될 수 있습니다. 현장 안내원의 안내를 따라 주세요."],["사진·영상·녹음","사전 허용되지 않은 촬영·녹음은 제한됩니다. 커튼콜 촬영도 작품마다 허용 범위가 다르므로 현장 공지를 확인하세요."],["음식물·꽃다발","객석 반입 제한은 공연별 안내를 따릅니다. 반입이 제한된 물품은 보관함을 이용하세요."],["공연 중 퇴장·재입장","작품 진행에 따라 재입장이 제한될 수 있습니다. 부득이하게 이동할 때는 안내원에게 먼저 말씀해 주세요."]],"note":"공연마다 관람 연령, 지연 입장, 촬영과 반입 규정이 다릅니다. 예매한 작품의 상세 공지와 현장 안내를 우선해 주세요."},{"type":"links","title":"입장 전에 준비하세요","items":[{"label":"물품보관함 위치","href":"/visit/amenities/facilities"},{"label":"티켓 수령 안내","href":"/programs/booking-guide"},{"label":"관람 관련 문의","href":"/visit/support/inquiry"}]}],"sources":[{"label":"공식 공연별 관람 규정 예시: 가곡시대","url":"https://www.sejongpac.or.kr/portal/performance/performance/performTicket.do?menuNo=200320&performIdx=36789"},{"label":"반입 제한 물품의 보관","url":"https://www.sejongpac.or.kr/portal/main/contents.do?menuNo=200388"}]}'::jsonb,true) where id='/visit/etiquette' and payload->'completion' is distinct from '{"path":"/visit/etiquette","title":"관람 예절","summary":"같은 공간에서 공연을 즐기는 관객과 출연자를 위해 입장과 촬영·반입 규정을 확인해 주세요.","sections":[{"type":"table","title":"공연 전후 확인할 사항","columns":["상황","안내"],"rows":[["공연 시작 전","티켓의 관람 연령과 입장 시간을 확인하고, 휴대전화의 소리·진동·화면 빛이 관람을 방해하지 않도록 준비하세요."],["늦게 도착한 경우","공연에 따라 지정된 지연 입장 시간에만 입장하며, 예매 좌석 대신 지연 관객석으로 안내될 수 있습니다. 현장 안내원의 안내를 따라 주세요."],["사진·영상·녹음","사전 허용되지 않은 촬영·녹음은 제한됩니다. 커튼콜 촬영도 작품마다 허용 범위가 다르므로 현장 공지를 확인하세요."],["음식물·꽃다발","객석 반입 제한은 공연별 안내를 따릅니다. 반입이 제한된 물품은 보관함을 이용하세요."],["공연 중 퇴장·재입장","작품 진행에 따라 재입장이 제한될 수 있습니다. 부득이하게 이동할 때는 안내원에게 먼저 말씀해 주세요."]],"note":"공연마다 관람 연령, 지연 입장, 촬영과 반입 규정이 다릅니다. 예매한 작품의 상세 공지와 현장 안내를 우선해 주세요."},{"type":"links","title":"입장 전에 준비하세요","items":[{"label":"물품보관함 위치","href":"/visit/amenities/facilities"},{"label":"티켓 수령 안내","href":"/programs/booking-guide"},{"label":"관람 관련 문의","href":"/visit/support/inquiry"}]}],"sources":[{"label":"공식 공연별 관람 규정 예시: 가곡시대","url":"https://www.sejongpac.or.kr/portal/performance/performance/performTicket.do?menuNo=200320&performIdx=36789"},{"label":"반입 제한 물품의 보관","url":"https://www.sejongpac.or.kr/portal/main/contents.do?menuNo=200388"}]}'::jsonb;
update public.sejong_pages set payload=jsonb_set(payload,'{completion}','{"path":"/visit/group","title":"단체관람","summary":"학교·기관·모임의 관람을 계획하고 계신가요? 원하는 작품과 회차, 인원을 정해 문의해 주세요.","sections":[{"type":"table","title":"문의 전에 정할 내용","columns":["항목","필요한 정보"],"rows":[["작품과 회차","공연·전시명, 희망 날짜·시간, 조정 가능한 다른 회차"],["관람 인원","전체 인원, 인솔자 수, 어린이·청소년의 관람 연령 충족 여부"],["좌석과 이동","희망 좌석 등급, 함께 앉아야 하는 인원, 휠체어와 동반 좌석 등 필요한 지원"],["담당자","기관·단체명, 연락받을 담당자, 회신 가능한 연락처"]]},{"type":"faq","title":"단체관람 신청 전 확인","items":[{"question":"몇 명부터 단체 할인을 받을 수 있나요?","answer":"작품별로 기준 인원·할인율·접수처가 다릅니다. 모든 공연에 같은 단체 기준이 적용되는 것은 아니므로 해당 공연의 할인 안내와 주최사 연락처를 확인하세요."},{"question":"문의만 남기면 좌석이 확보되나요?","answer":"좌석 확보와 결제 조건은 공연별 판매처의 확인이 필요합니다. 인원·좌석 배정·결제 기한을 안내받은 뒤 예매를 진행하세요."},{"question":"어린이도 인원에 포함할 수 있나요?","answer":"단체 인원과 별개로 공연별 관람 연령을 충족해야 합니다. 인솔자는 관람 대상자의 연령과 증빙 필요 여부를 먼저 확인하세요."}]},{"type":"links","title":"관람 준비","items":[{"label":"공연·전시 찾기","href":"/programs"},{"label":"이동·접근성 안내","href":"/visit/accessibility"},{"label":"전화로 문의하기","href":"tel:02-399-1000","description":"09:00~20:00"}]}],"form":{"kind":"group","title":"단체관람 문의","description":"단체명, 관람할 작품·회차, 인원과 필요한 지원을 입력해 주세요."},"sources":[{"label":"공식 예매 안내","url":"https://www.sejongpac.or.kr/portal/main/contents.do?menuNo=200322"},{"label":"공연별 관람 조건 예시","url":"https://www.sejongpac.or.kr/portal/performance/performance/performTicket.do?menuNo=200320&performIdx=36789"}]}'::jsonb,true) where id='/visit/group' and payload->'completion' is distinct from '{"path":"/visit/group","title":"단체관람","summary":"학교·기관·모임의 관람을 계획하고 계신가요? 원하는 작품과 회차, 인원을 정해 문의해 주세요.","sections":[{"type":"table","title":"문의 전에 정할 내용","columns":["항목","필요한 정보"],"rows":[["작품과 회차","공연·전시명, 희망 날짜·시간, 조정 가능한 다른 회차"],["관람 인원","전체 인원, 인솔자 수, 어린이·청소년의 관람 연령 충족 여부"],["좌석과 이동","희망 좌석 등급, 함께 앉아야 하는 인원, 휠체어와 동반 좌석 등 필요한 지원"],["담당자","기관·단체명, 연락받을 담당자, 회신 가능한 연락처"]]},{"type":"faq","title":"단체관람 신청 전 확인","items":[{"question":"몇 명부터 단체 할인을 받을 수 있나요?","answer":"작품별로 기준 인원·할인율·접수처가 다릅니다. 모든 공연에 같은 단체 기준이 적용되는 것은 아니므로 해당 공연의 할인 안내와 주최사 연락처를 확인하세요."},{"question":"문의만 남기면 좌석이 확보되나요?","answer":"좌석 확보와 결제 조건은 공연별 판매처의 확인이 필요합니다. 인원·좌석 배정·결제 기한을 안내받은 뒤 예매를 진행하세요."},{"question":"어린이도 인원에 포함할 수 있나요?","answer":"단체 인원과 별개로 공연별 관람 연령을 충족해야 합니다. 인솔자는 관람 대상자의 연령과 증빙 필요 여부를 먼저 확인하세요."}]},{"type":"links","title":"관람 준비","items":[{"label":"공연·전시 찾기","href":"/programs"},{"label":"이동·접근성 안내","href":"/visit/accessibility"},{"label":"전화로 문의하기","href":"tel:02-399-1000","description":"09:00~20:00"}]}],"form":{"kind":"group","title":"단체관람 문의","description":"단체명, 관람할 작품·회차, 인원과 필요한 지원을 입력해 주세요."},"sources":[{"label":"공식 예매 안내","url":"https://www.sejongpac.or.kr/portal/main/contents.do?menuNo=200322"},{"label":"공연별 관람 조건 예시","url":"https://www.sejongpac.or.kr/portal/performance/performance/performTicket.do?menuNo=200320&performIdx=36789"}]}'::jsonb;
update public.sejong_pages set payload=jsonb_set(payload,'{completion}','{"path":"/visit/plan","title":"관람 준비","summary":"공연장과 관람 연령을 확인하고 티켓 수령·입장·귀가 순서로 준비하세요.","sections":[{"type":"timeline","title":"방문 순서","items":[{"date":"출발 전","title":"예매내역과 준비물 확인","body":"공연장·날짜·회차·관람 연령을 확인하세요. 현장 수령에 필요한 예매내역서 또는 실물 신분증, 할인 증빙을 준비하세요."},{"date":"공연 약 1시간 전","title":"티켓 수령","body":"공식 안내는 여유 있는 수령을 위해 1시간 전 도착을 권장합니다. 매표소는 통상 1시간 30분 전, 무인발권기는 2시간 전 운영을 시작하며 공연별로 다릅니다."},{"date":"객석 입장 전","title":"공연장·층·게이트 확인","body":"디지털 티켓은 당일 활성화한 QR코드로 입장하세요. 캡처 이미지는 사용할 수 없습니다. 짐 보관과 화장실 이용도 입장 전에 마쳐 주세요."},{"date":"관람 후","title":"보관물 수령과 주차 정산","body":"물품보관함은 공연 종료 20분 후까지 운영합니다. 주차 정산 후 15분 이내 출차하세요."}]},{"type":"downloads","title":"공식 좌석배치도","items":[{"label":"대극장 1층 좌석 원본 이미지","href":"https://www.sejongpac.or.kr/static/portal/img/content/img_seat_0101.png"},{"label":"대극장 2층 좌석 원본 이미지","href":"https://www.sejongpac.or.kr/static/portal/img/content/img_seat_0102.png"},{"label":"대극장 3층 좌석 원본 이미지","href":"https://www.sejongpac.or.kr/static/portal/img/content/img_seat_0103.png"}]},{"type":"links","title":"방문 조건에 맞게 확인하세요","items":[{"label":"전체 공연장 좌석배치도","href":"https://www.sejongpac.or.kr/portal/main/contents.do?menuNo=200368"},{"label":"아이 동반·짐 보관","href":"/visit/amenities/facilities"},{"label":"이동 지원","href":"/visit/accessibility"},{"label":"식음료 매장","href":"/visit/amenities/dining"}]}],"sources":[{"label":"티켓 수령·디지털 티켓 이용","url":"https://www.sejongpac.or.kr/portal/main/contents.do?menuNo=200323"},{"label":"공식 좌석배치도","url":"https://www.sejongpac.or.kr/portal/main/contents.do?menuNo=200368"},{"label":"물품보관함 운영","url":"https://www.sejongpac.or.kr/portal/main/contents.do?menuNo=200388"},{"label":"주차 정산","url":"https://www.sejongpac.or.kr/portal/main/contents.do?menuNo=200391"}]}'::jsonb,true) where id='/visit/plan' and payload->'completion' is distinct from '{"path":"/visit/plan","title":"관람 준비","summary":"공연장과 관람 연령을 확인하고 티켓 수령·입장·귀가 순서로 준비하세요.","sections":[{"type":"timeline","title":"