insert into public.sejong_service_forms(id,kind,title,definition,enabled) values('/about/donation/apply','donation','후원 상담 신청','{"id":"/about/donation/apply","path":"/about/donation/apply","kind":"donation","title":"후원 상담 신청","enabled":true,"fields":[{"name":"name","label":"이름","type":"text","required":true,"maxLength":80},{"name":"email","label":"연락받을 이메일","type":"email","required":true,"maxLength":254},{"name":"phone","label":"연락처","type":"tel","required":true,"maxLength":30},{"name":"organization","label":"소속","type":"text","required":false,"maxLength":120},{"name":"amount","label":"희망 후원 금액(원, 선택)","type":"number","min":1,"max":1000000000},{"name":"frequency","label":"후원 방식","type":"select","required":true,"options":[{"value":"once","label":"일시 후원"},{"value":"regular","label":"정기 후원 상담"}]},{"name":"message","label":"관심 사업과 상담 내용","type":"textarea","required":false,"maxLength":2000}]}'::jsonb,true) on conflict(id) do update set kind=excluded.kind,title=excluded.title,definition=excluded.definition,enabled=excluded.enabled,revision=sejong_service_forms.revision+case when sejong_service_forms.definition is distinct from excluded.definition then 1 else 0 end;
